window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0185", [{"word":"advertisement","ipa_uk":"/ˌædvəˈtaɪsmənt/","ipa_us":"/ˌædvərˈtaɪzmənt/","definition_zh":"广告；广告作品；分类告示；招募公告","definition_en":"a public notice, especially a paid one that promotes goods, services or an event","core_image":"一张贴在人来人往处的告示，先把路人的目光拽过来，再把一件商品摆到眼前","scene":"街角灯箱里同一张海报反复亮起，路人的目光被那行大字拽住。The advertisement promised a free sample to anyone who walked in.","sceneCN":"街角灯箱反复亮起同一张海报，路人的目光被那行大字拽住；句中的这个词指「付费发布的推销信息」（第 1 个义项：为推销商品或服务而买下版面或时段的公开告示）。图中可辨识物件：灯箱、海报、大号标题、样品柜、走近的脚步。","pos":[{"tag":"n.","zh":"广告；广告作品（可数）"},{"tag":"n.","zh":"公告；告示；招募启事（可数，较早的用法）"}],"collocations":[{"phrase":"place an advertisement","zh":"刊登一则广告"},{"phrase":"a full-page advertisement","zh":"整版广告"},{"phrase":"a job advertisement","zh":"招聘广告"},{"phrase":"online advertisement","zh":"网络广告"},{"phrase":"advertisement for a product","zh":"某产品的广告"},{"phrase":"pull an advertisement","zh":"撤下一则广告"}],"forms":[{"label":"复数","form":"advertisements"},{"label":"动词（做广告）","form":"advertise"},{"label":"名词（广告活动；广告业）","form":"advertising"},{"label":"名词（广告主）","form":"advertiser"},{"label":"形容词（被宣传的）","form":"advertised"}],"derivatives":[{"word":"advertise","pos":"v.","zh":"为……做广告；登广告"},{"word":"advertising","pos":"n.","zh":"广告业；广告活动"},{"word":"advertiser","pos":"n.","zh":"广告主"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"},{"word":"advertised","pos":"adj.","zh":"已公布于广告的"}],"senses":[{"no":"01","title":"Paid public notice for goods","titleCN":"为推销商品而付费发布的公开告示","definition":"a paid notice placed in a newspaper, on a screen or on a wall to persuade people to buy something","definitionCN":"买下报纸版面、屏幕时段或墙面位置，劝人购买某物的付费告示","example":"The advertisement promised a free sample to anyone who walked in.","exampleCN":"这则广告承诺，凡进店者都可得一份免费样品。","why":"The word comes from a Latin verb meaning 'to turn toward', so a notice is literally something that turns your attention toward a seller.","whyCN":"这个词出自一个意为「转向」的拉丁动词，所以一则告示字面上就是「把你的注意力转向某个卖家」的东西。"},{"no":"02","title":"Classified notice","titleCN":"分类告示：招聘、租售、寻物的短条","definition":"a short notice in a special section of a paper or site, announcing a job, a room or something wanted","definitionCN":"登在专门版块上的短告示，用于招人、出租出售房屋或求购某物","example":"She found the flat through a small advertisement in the local paper.","exampleCN":"她通过本地报纸上一则小广告找到了这套房子。","why":"The earliest notices were plain information, and the classified column still keeps that unpersuasive form.","whyCN":"最早的告示只是「告知信息」，分类版块至今保留这种不加劝说的朴素形态。"},{"no":"03","title":"One piece of ad material","titleCN":"一则广告成品","definition":"one item of advertising material, such as a film, a poster or a printed page","definitionCN":"一件广告成品，如一段影片、一张海报或一个印刷版面","example":"They shot three advertisements for the same brand.","exampleCN":"他们为同一个品牌拍了三则广告。","why":"The noun counts objects, so one long campaign made of many messages contains many separate advertisements.","whyCN":"这个名词用来数「物件」，所以一场由许多信息构成的宣传里包含许多则各自独立的广告。"},{"no":"04","title":"Public promotion of a cause","titleCN":"对活动或事业的公开宣传","definition":"a public statement that draws attention to an event, a cause or an idea rather than to goods","definitionCN":"把活动、事业或理念推到公众眼前的公开说法，而非推销货物","example":"The poster is an advertisement for the concert, not for a product.","exampleCN":"这张海报是为音乐会做宣传，而不是推销商品。","why":"Turning attention is the core act; selling is only one use of that act.","whyCN":"「把注意力转过来」才是核心动作，卖货只是这个动作的一种用途。"},{"no":"05","title":"The old sense: a notification","titleCN":"古义：使人知晓的通知","definition":"in earlier English, the act of making something known to someone, or a piece of news","definitionCN":"在早期英语中指「使某人知道某事」的动作，也可指一则消息","example":"In seventeenth-century usage, an advertisement was simply information given.","exampleCN":"在十七世纪的用法里，这个词只是「被告知的信息」。","why":"The selling sense is younger than the word: it first named the act of informing, and only later the printed sheet that sells.","whyCN":"卖货义比这个词本身年轻：它先指「告知」这一动作，后来才指那张卖东西的印刷品。"},{"no":"06","title":"The space or slot that is bought","titleCN":"买下的广告位或时段","definition":"the place in a medium that a seller pays for, rather than the message itself","definitionCN":"卖方在媒体上付费占用的位置，而非内容本身","example":"The magazine sells advertisements on its back cover.","exampleCN":"这本杂志把封底作为广告位出售。","why":"A page or a slot is a container: the medium sells containers and the advertiser fills them.","whyCN":"一个版面或一个时段就是容器：媒体卖容器，广告主往里装内容。"},{"no":"07","title":"A warning example, used ironically","titleCN":"反讽用法：反面样板","definition":"used ironically of a person or thing that shows how bad something is","definitionCN":"反讽地指某个人或某样东西，用来说明某事有多糟","example":"His messy office is an advertisement for doing nothing.","exampleCN":"他那乱糟糟的办公室就是「什么都不做」的活招牌。","why":"The irony keeps the original force: the example still turns your attention to a quality, only now the quality is a warning.","whyCN":"这种反讽保留了原有的力量：这个例子仍把注意力转向某种性质，只是这回那性质是一则警告。"},{"no":"08","title":"Recruitment notice","titleCN":"招募公告","definition":"a notice inviting people to join a job, an army or a volunteer group","definitionCN":"招人加入某个岗位、军队或志愿者团体的公告","example":"The army ran advertisements for recruits in every town.","exampleCN":"军队在每个城镇都张贴招募公告。","why":"Recruiting is a special case of making something known: what is offered is a place inside a group.","whyCN":"招募是「使人知晓」的特例：被提供的东西是某个群体里的一个位置。"}],"etymology":{"intro":{"en":"Advertisement goes back through French to Latin advertere 'to turn toward'. The selling sense is modern; the informing sense is the older one.","cn":"advertisement 经法语上溯到拉丁 advertere「转向、把注意力引向」。卖货义是现代用法，告知义才是较早的意思。"},"items":[{"era":"LATIN VERTERE","en":"Vertere meant 'to turn'. Its past participle versus also gave English versus and verse, and the same root works inside divert, invert and convert.","cn":"vertere 意为「转」。它的过去分词 versus 还给了英语 versus 与 verse，同一词根也出现在 divert、invert、convert 之中。"},{"era":"LATIN ADVERTERE","en":"Ad- 'to, toward' plus vertere produced advertere 'to turn toward, to direct one's attention to'. Its past participle adversus also gave English adverse.","cn":"ad-「朝向」加 vertere 构成 advertere「转向、把注意力引向」。它的过去分词 adversus 还给了英语 adverse。"},{"era":"OLD FRENCH AVERTIR","en":"Old French avertir 'to warn, to notify' carried the word toward English, with the stem avertiss-. The d in the English spelling is restored from Latin, not taken from French.","cn":"古法语 avertir「警告、通知」把这个词带向英语，词干为 avertiss-。英语拼写里的 d 是从拉丁语回补的，并非来自法语。"},{"era":"EARLY MODERN ENGLISH","en":"From the fifteenth century the verb meant 'to give notice to someone'. The noun advertisement in the seventeenth century still meant simply 'information, a notification'.","cn":"从十五世纪起，这个动词意为「通知某人」。十七世纪的名词 advertisement 仍然只表示「信息、通知」。"},{"era":"COMMERCIAL SENSE","en":"In the eighteenth century the noun shifted to a paid public notice recommending goods, and newspapers began to depend on these notices for income.","cn":"到十八世纪，这个名词转向「为推荐商品而付费的公开告示」，报纸也开始依靠这类告示获得收入。"},{"era":"MODERN ENGLISH","en":"The clipped form ad appeared in the nineteenth century. In the twentieth century the word also covered broadcast slots, posters and online placements.","cn":"缩略形式 ad 出现在十九世纪。到二十世纪，这个词也涵盖广播时段、海报与网络版位。"}]},"similar":{"note":{"en":"The first group shares the same Latin root or a very close spelling; the second group holds words that mean almost the same thing.","cn":"第一组同出拉丁词根或拼写极近；第二组是意思非常接近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advert","ipa":"/ˈædvɜːt/","tag":"clipped form","definition":"British informal for an advertisement; as a verb it means to refer to something. It is the same word shortened, not a different one.","definitionCN":"英式口语里指广告；作动词时表示「提及某事」。它是同一个词的缩短形式，不是另一个词。"},{"word":"advertising","ipa":"/ˈædvətaɪzɪŋ/","tag":"mass vs count","definition":"The activity or industry as a whole, not one item. One notice is an advertisement; the whole business is advertising.","definitionCN":"指整个活动或行业，不是单件东西。单则告示是可数的 advertisement，整个行当是不可数的 advertising。"},{"word":"advertise","ipa":"/ˈædvətaɪz/","tag":"other part of speech","definition":"The verb: to place or run a notice. The noun adds -ment, the verb does not.","definitionCN":"动词：登广告、投放广告。名词多一个 -ment 后缀，动词没有。"},{"word":"adverse","ipa":"/ədˈvɜːs/","tag":"same root, different sense","definition":"From the same Latin participle adversus 'turned against', but it means unfavourable or harmful, not a notice.","definitionCN":"同出拉丁分词 adversus「转过来对抗」，但意思是「不利的、有害的」，不是告示。"}]},{"heading":"NEAR MEANING","entries":[{"word":"notice","ipa":"/ˈnəʊtɪs/","tag":"plain announcement","definition":"A written or printed announcement put where people will see it; it needs no persuasion and no payment.","definitionCN":"贴在人能看到处的书面告示；不需要劝说，也不需要付费。"},{"word":"announcement","ipa":"/əˈnaʊnsmənt/","tag":"spoken or official","definition":"A statement making news public, often official and often spoken rather than printed.","definitionCN":"把消息公开的说法，常带官方性质，且多说出口而非印出来。"},{"word":"commercial","ipa":"/kəˈmɜːʃl/","tag":"broadcast only","definition":"A paid advertisement on radio or television; the word is limited to broadcast media.","definitionCN":"广播或电视上的付费广告；这个词限于广播电视媒介。"},{"word":"publicity","ipa":"/pʌbˈlɪsəti/","tag":"attention, not space","definition":"The attention a person or product gets, often unpaid and earned through news rather than bought as space.","definitionCN":"人或产品获得的关注，往往不付费，靠新闻赢得，而不是买下版位。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin pieces, real derived words and real fixed phrases.","cn":"正常联想：真实的拉丁语构件、真实的派生词与真实的固定搭配。"},"normal":[{"en":"ad- 'toward' plus vertere 'turn': the notice turns your eyes toward the seller.","cn":"ad-「朝向」加 vertere「转」：这则告示把你的眼睛转向卖家。"},{"en":"The family runs advertise, advertisement, advertising, advertiser and the clipped advert.","cn":"同族词包括 advertise、advertisement、advertising、advertiser，以及缩略的 advert。"},{"en":"The same turning root sits in divert 'turn aside', invert 'turn upside down' and convert 'turn together'.","cn":"同一个「转」的词根还在 divert「转向一边」、invert「上下翻转」与 convert「整体转变」里。"},{"en":"Fixed phrases mark the trade: place an advertisement, a full-page advertisement, a job advertisement.","cn":"固定搭配标出行业用法：刊登广告、整版广告、招聘广告。"},{"en":"The old meaning survives in the court phrase 'advertisement of title', a formal notification of a legal claim.","cn":"旧义还留在法律短语 advertisement of title 里，指对某项权利主张的正式通知。"}],"abstract":[{"en":"Picture a finger tapping a shoulder: first it turns the face, then it points at a shop window.","cn":"想象一根手指轻拍肩膀：先让那张脸转过来，再指向一扇橱窗。"},{"en":"The notice never carries the goods; it only carries the direction of your gaze.","cn":"告示从不装载货物，它只装载你目光的方向。"},{"en":"So an advertisement is a paid turn of the head, bought by the second or by the page.","cn":"所以一则广告就是一次付费的「转头」，按时段或按版面买下。"}]},"examples":[{"en":"The advertisement in the window was so plain that nobody stopped.","cn":"橱窗里那则广告太朴素，没人停下脚步。"},{"en":"They placed an advertisement for a night porter in the local paper.","cn":"他们在本地报纸上登了一则招夜班门房的广告。"},{"en":"Her shabby desk is an advertisement for the need to reorganize.","cn":"她那破旧的办公桌就是「必须重新整理」的活广告。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿德-沃台斯门特」——先是「阿德」把注意力拽过来，再把商品摆到门特（门口）→ 广告","word":"advertisement"},"root":"拉丁 advertere「转向、把注意力引向」= ad-（朝向）+ vertere「转」；名词后缀 -ment 表结果。同根还有 divert、invert、convert、adverse。","sensesIntro":{"en":"Eight senses trace one gesture: a notice turns your attention, then tells you something, and only in modern use does the telling become selling.","cn":"八个义项沿同一个动作展开：告示先把你的注意力转过来，再告诉你一件事；只是到了现代，这个「告诉」才变成「推销」。"},"semanticMap":{"core":{"en":"CORE IMAGE: turn the head → read the notice → want the goods.","cn":"核心意象：转头 → 读到告示 → 想要那件货。"},"chain":["TURN TOWARD","PUBLIC NOTICE","PAID NOTICE","GOODS FOR SALE","SINGLE ITEM","MEDIA SLOT"],"branches":[{"senses":"01 · 05","en":"TURN AND TELL: the earliest sense only informs; the modern sense informs in order to sell.","cn":"转向并告知：最早的意思只是告知，现代的意思则是为了卖而告知。"},{"senses":"02 · 08","en":"SHORT NOTICES: a classified line and a recruitment call both offer a slot rather than a product.","cn":"短告示：分类小条与招募公告提供的是一个位置，而不是一件商品。"},{"senses":"03 · 06","en":"ITEM AND CONTAINER: one finished film is countable, while the page it fills is bought as space.","cn":"成品与容器：一支拍好的片子可以数，而它占的那一页是作为版面买下的。"},{"senses":"04","en":"NON-COMMERCIAL PUSH: the same turning of attention works for a concert or a cause.","cn":"非商业推动：同一套「转移注意力」的做法也能用于音乐会或某项事业。"},{"senses":"07","en":"IRONIC FLIP: the object that turns heads now turns them toward a fault.","cn":"反讽翻转：那个吸引眼球的东西，现在把眼球转向一处毛病。"}]},"affixes":{"intro":{"en":"Advertisement is built from a Latin prefix, a Latin root and an English noun suffix, and each piece also builds other common words.","cn":"advertisement 由拉丁前缀、拉丁词根与英语名词后缀构成，每一部分都还能构成别的常用词。"},"latinIntro":{"en":"Latin vertere 'to turn' supplies the root; ad- 'toward' supplies the direction; -ment turns the verb into a countable result.","cn":"拉丁 vertere「转」提供词根；ad-「朝向」提供方向；-ment 把动词变成可数的结果。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix, 'to, toward')","meaning":"toward; also intensifying","meaningCN":"朝向；也可加强语气","example":"The prefix points the action at a target.","exampleCN":"这个前缀把动作指向一个目标。"},{"word":"vert / vers","structure":"vertere, versus (Latin root, 'turn')","meaning":"to turn","meaningCN":"转；转动","example":"The root appears in convert and reverse.","exampleCN":"这个词根出现在 convert 与 reverse 里。"},{"word":"-ment","structure":"-ment (noun suffix, from Latin -mentum)","meaning":"result or means of an action","meaningCN":"动作的结果或手段","example":"The suffix makes a countable thing out of a verb.","exampleCN":"这个后缀把动词变成一件可数的事物。"},{"word":"-ise","structure":"-ise (verb suffix, through French -iser)","meaning":"to make or to carry out","meaningCN":"使……；实行……","example":"American spelling prefers -ize in this family.","exampleCN":"这一词族的美式拼写更常用 -ize。"},{"word":"advertise","structure":"advertise (verb)","meaning":"to run or place a notice","meaningCN":"登广告；投放广告","example":"They advertise on the radio every morning.","exampleCN":"他们每天早上在电台投放广告。"},{"word":"advertisement","structure":"advertise + -ment","meaning":"one notice or one ad item","meaningCN":"一则告示或一件广告成品","example":"The advertisement fills the whole page.","exampleCN":"这则广告占满整页。"},{"word":"advertiser","structure":"advertise + -er (person who)","meaning":"the party that pays for the notice","meaningCN":"出钱登告示的一方","example":"The advertiser bought the back cover.","exampleCN":"广告主买下了封底。"},{"word":"advertising","structure":"advertise + -ing (activity or mass noun)","meaning":"the activity or industry","meaningCN":"广告活动；广告业","example":"Advertising pays for most of the site.","exampleCN":"这个网站的大部分开销由广告承担。"},{"word":"advert","structure":"advert (clipped noun)","meaning":"an ad, in British speech","meaningCN":"广告（英式口语）","example":"I saw your advert in the paper.","exampleCN":"我在报纸上看到你那则广告。"},{"word":"adverse","structure":"ad- + vers- (turned against)","meaning":"unfavourable, hostile","meaningCN":"不利的；敌对的","example":"The drug had adverse effects.","exampleCN":"这种药产生了不良反应。"},{"word":"divert","structure":"di- (apart) + vert- (turn)","meaning":"to turn aside","meaningCN":"使转向；转移","example":"Traffic was diverted around the bridge.","exampleCN":"车辆被引导绕过那座桥。"}],"latinEntries":[{"word":"vertere","structure":"vertere, verti, versum (verb, third conjugation)","meaning":"to turn, to turn around","meaningCN":"转；翻转"},{"word":"advertere","structure":"ad- + vertere","meaning":"to turn toward, to notice","meaningCN":"转向；注意到"},{"word":"adversus","structure":"past participle of advertere","meaning":"turned against; opposite","meaningCN":"转过来对抗的；相反的"}],"derivatives":[{"word":"advertise","pos":"v.","zh":"做广告；登广告"},{"word":"advertising","pos":"n.","zh":"广告业；广告活动"},{"word":"advertiser","pos":"n.","zh":"广告主"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"},{"word":"advertised","pos":"adj.","zh":"广告中公布的"}]}},{"word":"advertise","ipa_uk":"/ˈædvətaɪz/","ipa_us":"/ˈædvərtaɪz/","definition_zh":"做广告；登广告；宣传；公开告知","definition_en":"to make goods, services or an event known to the public, especially by paid notices","core_image":"把一块招牌举到人群上方，让原本只顾低头走路的人抬起头来","scene":"新店开业前，店主把横幅挂到街口最高处，又印了小卡片挨家送。They advertise the new bakery on every bus stop in the district.","sceneCN":"新店开业前，店主把横幅挂到街口最高处，又印小卡片挨家送；句中的这个词指「为推销而面向公众做宣传」（第 1 个义项：通过付费告示让商品或服务被人知道）。图中可辨识物件：横幅、街口、小卡片、公交站牌、抬头的人群。","pos":[{"tag":"vt.","zh":"为……做广告；宣传（商品、服务、活动）"},{"tag":"vi.","zh":"登广告；投放广告（从事广告活动）"}],"collocations":[{"phrase":"advertise a product","zh":"为某产品做广告"},{"phrase":"advertise a job","zh":"登广告招聘"},{"phrase":"advertise widely","zh":"广泛宣传"},{"phrase":"advertise on television","zh":"在电视上投放广告"},{"phrase":"heavily advertised","zh":"被大力宣传的"},{"phrase":"advertise for a tenant","zh":"登广告招租客"}],"forms":[{"label":"三单（he/she/it）","form":"advertises"},{"label":"过去式","form":"advertised"},{"label":"过去分词","form":"advertised"},{"label":"现在分词","form":"advertising"},{"label":"名词（一则广告）","form":"advertisement"},{"label":"名词（广告主）","form":"advertiser"}],"derivatives":[{"word":"advertisement","pos":"n.","zh":"广告；告示"},{"word":"advertising","pos":"n.","zh":"广告业；广告活动"},{"word":"advertiser","pos":"n.","zh":"广告主"},{"word":"advertised","pos":"adj.","zh":"广告中公布的"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"}],"senses":[{"no":"01","title":"Promote goods by paid notices","titleCN":"为商品做广告推销","definition":"to draw public attention to goods or services in order to sell them","definitionCN":"把商品或服务的注意力引到公众眼前，以便把它们卖出去","example":"They advertise the new bakery on every bus stop in the district.","exampleCN":"他们在本区每个公交站牌上为那家新面包店做广告。","why":"The Latin base means 'to turn toward': advertising turns a passer-by's attention toward a seller.","whyCN":"拉丁词干意为「转向」：做广告就是把路人的注意力转向某个卖家。"},{"no":"02","title":"Place a notice asking for something","titleCN":"登广告招聘或征求","definition":"to place a notice asking for workers, buyers or something lost","definitionCN":"刊登告示，招人、求购或寻找失物","example":"The hospital advertised for two night nurses.","exampleCN":"这家医院登广告招两名夜班护士。","why":"A want ad is the plainest form: the notice states a need instead of praising a product.","whyCN":"征求广告是最朴素的形式：告示只说出一个需求，而不夸赞某件商品。"},{"no":"03","title":"Give notice, in older usage","titleCN":"古义：正式通知某人","definition":"in earlier English, to inform someone of something or to give formal notice","definitionCN":"在早期英语中指通知某人某事，或发出正式告知","example":"The steward advertised the master of the ship's arrival.","exampleCN":"管事通知船长船只已经到达。","why":"Before it meant selling, the verb meant telling: the same turning of attention, without any goods.","whyCN":"在表示「卖」之前，这个动词表示「告诉」：同样是把注意力转过来，只是不涉及货物。"},{"no":"04","title":"Draw attention to oneself","titleCN":"自我吹嘘（含贬义）","definition":"to call attention to one's own abilities or deeds in a way others find boastful","definitionCN":"以让别人觉得自夸的方式强调自己的能力或作为","example":"He never misses a chance to advertise his own generosity.","exampleCN":"他从不放过任何吹嘘自己慷慨的机会。","why":"When the seller and the goods are the same person, the turning of attention becomes self-display.","whyCN":"当卖家与货物是同一个人时，「转移注意力」就变成了自我展示。"},{"no":"05","title":"Make a fact visible, of a thing","titleCN":"昭示：器物本身显示出某个事实","definition":"of an object or place, to make a fact obvious without any words","definitionCN":"指物件或地点本身把某个事实明显地显示出来，无需言语","example":"The cracked walls advertise the age of the building.","exampleCN":"开裂的墙面昭示着这栋楼的年岁。","why":"Here the notice is not printed at all: the thing itself calls attention to what it is.","whyCN":"这里的告示根本不是印出来的：事物本身在招引别人注意它是什么。"},{"no":"06","title":"Publicize a non-commercial event","titleCN":"为非商业活动做宣传","definition":"to publicize an event, cause or idea rather than a product","definitionCN":"宣传某个活动、事业或理念，而不是某件商品","example":"Volunteers advertised the free clinic in every village.","exampleCN":"志愿者在每个村子宣传那场免费诊疗活动。","why":"Nothing is for sale, yet the act is identical: eyes must be turned toward something worth attending.","whyCN":"这里没有东西要卖，动作却完全一样：得把目光转向某件值得参与的事。"},{"no":"07","title":"Carry on the business of advertising","titleCN":"从事广告业、投放广告","definition":"to engage in advertising as an activity, usually intransitive","definitionCN":"把做广告当作一项业务来做，通常不及物","example":"Small shops rarely advertise in national papers.","exampleCN":"小店很少在全国性报纸上投放广告。","why":"Without an object, the verb names the ongoing trade rather than one promoted thing.","whyCN":"不带宾语时，这个动词说的是持续的行业行为，而不是某一件被推销的东西。"},{"no":"08","title":"Make something publicly known","titleCN":"使某事为公众所知","definition":"to make a fact or intention known to the public, especially through the media","definitionCN":"让某个事实或意图为公众所知，尤其通过媒体","example":"The company advertised its intention to close the plant.","exampleCN":"公司公开表明了关厂的意图。","why":"This sense keeps the neutral core: what is turned toward the public is information, not merchandise.","whyCN":"这个义项保留了中性的核心：被转向公众的是信息，而不是商品。"}],"etymology":{"intro":{"en":"Advertise entered English through Old French, but its spelling was reshaped by the Latin verb behind the French word. The commercial meaning is a later narrowing.","cn":"advertise 经古法语进入英语，但拼写被法语词背后的拉丁动词重塑。商业义是后来才收窄出来的。"},"items":[{"era":"LATIN VERTERE","en":"Vertere 'to turn' is the root. Its participle versus gave several English words, including versus and verse, and it also works inside divert and invert.","cn":"vertere「转」是词根。它的分词 versus 给了英语好几个词，包括 versus 与 verse，也出现在 divert、invert 里。"},{"era":"LATIN ADVERTERE","en":"Ad- 'to' plus vertere gave advertere 'to turn toward, to direct attention to'. The participle adversus 'turned against' gave English adverse.","cn":"ad-「朝向」加 vertere 构成 advertere「转向、把注意力引向」。分词 adversus「转过来对抗」给了英语 adverse。"},{"era":"OLD FRENCH","en":"Old French avertir 'to warn, notify' supplied the verb with its stem avertiss-. English restored the d from Latin, so the spelling looks Latin while the shape looks French.","cn":"古法语 avertir「警告、通知」以词干 avertiss- 提供了这个动词。英语从拉丁语补回了 d，于是拼写像拉丁语，外形却像法语。"},{"era":"FIFTEENTH CENTURY","en":"The verb is recorded from the fifteenth century in the sense 'to give notice to a person'. The spelling advertize with d became standard in the seventeenth century.","cn":"这个动词自十五世纪有记录，意为「通知某人」。带 d 的拼写 advertize 在十七世纪成为标准。"},{"era":"EIGHTEENTH CENTURY","en":"The commercial sense 'to publish a notice of goods for sale' appears in the eighteenth century, as newspapers grew into a mass medium.","cn":"「刊登商品出售告示」的商业义出现在十八世纪，正当报纸发展为大众媒介。"},{"era":"MODERN ENGLISH","en":"The intransitive use 'to carry on advertising' belongs to the modern trade, and the derived nouns advertising and advertiser grew with it.","cn":"「从事广告活动」的不及物用法属于现代行业语，派生名词 advertising 与 advertiser 也随之成长。"}]},"similar":{"note":{"en":"Group one shares the same root or a near spelling; group two means much the same but with a different scope.","cn":"第一组共享词根或拼写相近；第二组意思相近，但覆盖面不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advertisement","ipa":"/ˌædvəˈtaɪsmənt/","tag":"noun form","definition":"The countable result: one notice. The verb takes an object; the noun names the object.","definitionCN":"可数的结果：一则告示。动词带宾语，名词则指那件东西。"},{"word":"advise","ipa":"/əˈvaɪz/","tag":"different root","definition":"From Latin ad- plus videre 'to see', meaning to give advice. It looks close but has no turning root.","definitionCN":"来自拉丁 ad- 加 videre「看」，意为给建议。外形接近，却没有「转」的词根。"},{"word":"adverse","ipa":"/ədˈvɜːs/","tag":"same root","definition":"Built on the participle adversus 'turned against'; it means hostile or unfavourable.","definitionCN":"由分词 adversus「转过来对抗」构成；意思是敌对的、不利的。"},{"word":"divert","ipa":"/daɪˈvɜːt/","tag":"same root","definition":"Dis- 'apart' plus vertere 'turn': to turn something aside, as traffic or funds.","definitionCN":"dis-「分开」加 vertere「转」：把某物转向一边，如车流或资金。"}]},{"heading":"NEAR MEANING","entries":[{"word":"promote","ipa":"/prəˈməʊt/","tag":"broader","definition":"To push something forward in public, which may include advertising but also sponsorship, events and personal selling.","definitionCN":"把某物在公众面前往前推，可包括广告，也包括赞助、活动与人员推销。"},{"word":"publicize","ipa":"/ˈpʌblɪsaɪz/","tag":"no payment implied","definition":"To make something widely known; payment is not part of the meaning.","definitionCN":"使某事广为人知；这个词本身不含付费的意思。"},{"word":"announce","ipa":"/əˈnaʊns/","tag":"one statement","definition":"To state something once, publicly and formally, without the idea of repeated promotion.","definitionCN":"公开、正式地宣布一次，不含反复推广的意思。"},{"word":"market","ipa":"/ˈmɑːkɪt/","tag":"wider strategy","definition":"To plan and carry out the whole selling effort, of which advertising is only one part.","definitionCN":"筹划并执行整个销售努力，广告只是其中一部分。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real derived words, with the Latin picture kept in view.","cn":"正常联想：真实的语素与真实的派生词，同时保留拉丁语的那幅画面。"},"normal":[{"en":"ad- 'toward' + vert- 'turn': advertising turns heads toward a seller.","cn":"ad-「朝向」加 vert-「转」：做广告就是把头转向卖家。"},{"en":"French avertir meant 'to warn'; English kept the warn-and-tell core and added the Latin d.","cn":"法语 avertir 意为「警告」；英语保留了「警告并告知」的核心，又加上了拉丁语的 d。"},{"en":"Fixed phrases show the object: advertise a product, advertise a job, advertise for a tenant.","cn":"固定搭配显示宾语：为产品做广告、登广告招聘、登广告招租客。"},{"en":"The participle adversus is the same piece that gives adverse, so 'turned against' and 'turned toward' are two directions of one root.","cn":"分词 adversus 也是构成 adverse 的那块材料，所以「转向对抗」与「转向」是同一词根的两个方向。"},{"en":"The derived chain is clean: advertise → advertisement → advertiser → advertising.","cn":"派生链条很清楚：advertise → advertisement → advertiser → advertising。"}],"abstract":[{"en":"Picture a spotlight on a turntable: advertising only rotates the beam, it does not build the shop.","cn":"想象转台上的一束聚光灯：广告只转动光束，并不建造那家店。"},{"en":"The same rotation serves a bakery, a job vacancy or a free clinic, because all three need eyes.","cn":"同一套转动可以服务面包店、招聘岗位或免费诊所，因为这三者都需要目光。"},{"en":"So the verb is a direction, not a product: it points attention and lets the thing speak for itself.","cn":"所以这个动词是一个方向，而不是一件产品：它指出注意力，让事物自己说话。"}]},"examples":[{"en":"The chain advertises its winter coats on billboards along the motorway.","cn":"这家连锁店在高速公路旁的广告牌上宣传它的冬季外套。"},{"en":"They advertised the vacant post in three trade journals.","cn":"他们在三份行业期刊上登广告招聘这个空缺职位。"},{"en":"The faded sign still advertises a hotel that closed years ago.","cn":"那块褪色的招牌仍在昭示一家多年前就关门的旅馆。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿德-歪台兹」——阿德把招牌歪着举向人群，头就都转过去了 → advertise 做广告","word":"advertise"},"root":"拉丁 advertere「转向、把注意力引向」= ad-（朝向）+ vertere「转」；经古法语 avertir 进入英语，d 由拉丁拼写回补。","sensesIntro":{"en":"Eight senses all perform one rotation: attention is turned toward something, whether goods, a vacancy, a fact or the speaker himself.","cn":"八个义项都在做同一个转动：把注意力转向某物，无论那是货物、空缺、事实，还是说话者自己。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand turns a face toward a target.","cn":"核心意象：一只手把一张脸转向某个目标。"},"chain":["CALL OUT","TURN EYES","GIVE NOTICE","SELL GOODS","BOAST","MAKE VISIBLE"],"branches":[{"senses":"01 · 08","en":"TURN AND TELL: selling and plain informing use the same rotation, one with goods and one with facts.","cn":"转向并告知：卖货与单纯告知用的是同一个转动，一个带货物，一个带事实。"},{"senses":"02 · 03","en":"NOTICE OF NEED: a want ad states a need, and the oldest use states a piece of news.","cn":"需求告示：征求广告说出一个需求，最古老的用法说出一条消息。"},{"senses":"04","en":"SELF-DISPLAY: when seller and goods coincide, rotation becomes boasting.","cn":"自我展示：当卖家与货物合一，转动就变成自夸。"},{"senses":"05","en":"WORDLESS SIGN: a cracked wall advertises its own age without any notice at all.","cn":"无字的信号：开裂的墙不用任何告示就昭示自己的年岁。"},{"senses":"06 · 07","en":"NO GOODS AT ALL: a cause or an ongoing trade keeps the rotation but drops the merchandise.","cn":"根本不卖货：某项事业或持续的业务保留了转动，却丢掉了商品。"}]},"affixes":{"intro":{"en":"This verb is a Latin prefix plus a Latin root plus a French verb ending, and all three pieces are productive in English.","cn":"这个动词由拉丁前缀、拉丁词根与法语动词词尾构成，三部分在英语里都还能产。"},"latinIntro":{"en":"Advertere 'turn toward' is ad- plus vertere 'turn'; the same vertere builds reverse, convert and divert.","cn":"advertere「转向」是 ad- 加 vertere「转」；同一个 vertere 还构成 reverse、convert 与 divert。"},"items":[{"word":"ad-","structure":"ad- (Latin prefix, 'to, toward')","meaning":"toward","meaningCN":"朝向","example":"The prefix aims the action at a target.","exampleCN":"这个前缀把动作对准一个目标。"},{"word":"vert / vers","structure":"vertere, versus (Latin root)","meaning":"to turn","meaningCN":"转","example":"Reverse and convert share this root.","exampleCN":"reverse 与 convert 共享这个词根。"},{"word":"-ise","structure":"-ise / -ize (verb suffix, French -iser)","meaning":"to do or to make","meaningCN":"做；使成为","example":"The suffix marks a verb of action.","exampleCN":"这个后缀标示一个动作动词。"},{"word":"advertise","structure":"advertise (base verb)","meaning":"to run a paid notice","meaningCN":"投放付费告示","example":"They advertise on every bus stop.","exampleCN":"他们在每个公交站牌上投放广告。"},{"word":"advertisement","structure":"advertise + -ment","meaning":"one notice","meaningCN":"一则告示","example":"The advertisement fills the page.","exampleCN":"这则广告占满整页。"},{"word":"advertiser","structure":"advertise + -er","meaning":"the paying party","meaningCN":"出钱的一方","example":"The advertiser chose the slot.","exampleCN":"广告主选定了时段。"},{"word":"advertising","structure":"advertise + -ing","meaning":"the activity or industry","meaningCN":"广告活动；广告业","example":"Advertising funds the newspaper.","exampleCN":"广告支撑着这家报纸。"},{"word":"advert","structure":"advert (clipped form)","meaning":"an ad","meaningCN":"广告（口语）","example":"I answered his advert.","exampleCN":"我回应了他那则广告。"},{"word":"adverse","structure":"ad- + vers- (turned against)","meaning":"hostile, unfavourable","meaningCN":"敌对的；不利的","example":"Adverse weather delayed the flight.","exampleCN":"恶劣天气延误了航班。"},{"word":"divert","structure":"di- (apart) + vert- (turn)","meaning":"to turn aside","meaningCN":"使转向","example":"The parade was diverted from the square.","exampleCN":"游行队伍被引导离开广场。"}],"latinEntries":[{"word":"vertere","structure":"vertere, verti, versum (verb, third conjugation)","meaning":"to turn","meaningCN":"转；翻转"},{"word":"advertere","structure":"ad- + vertere","meaning":"to turn toward, to attend to","meaningCN":"转向；留意"},{"word":"adversus","structure":"past participle of advertere","meaning":"turned against","meaningCN":"转过来对抗的"}],"derivatives":[{"word":"advertisement","pos":"n.","zh":"广告；告示"},{"word":"advertising","pos":"n.","zh":"广告业；广告活动"},{"word":"advertiser","pos":"n.","zh":"广告主"},{"word":"advertised","pos":"adj.","zh":"广告中公布的"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"}]}},{"word":"advertising","ipa_uk":"/ˈædvətaɪzɪŋ/","ipa_us":"/ˈædvərtaɪzɪŋ/","definition_zh":"广告业；广告活动；广告作品总称；广告学","definition_en":"the activity, industry or body of material that promotes goods and services through paid notices","core_image":"一条街上所有招牌、屏幕、车身同时发亮，汇成一片不断说话的声音","scene":"整条商业街的招牌、屏幕与车身同时亮起，同一句口号从各处涌来。Advertising pays for most of the free apps on your phone.","sceneCN":"整条街的招牌、屏幕与车身同时亮起，同一句口号从各处涌来；句中的这个词指「以付费告示推销商品的整体活动」（第 2 个义项：做广告这一行为及其行业）。图中可辨识物件：招牌、屏幕、车身贴、同一句口号、手机中的应用图标。","pos":[{"tag":"n.","zh":"广告业；广告活动（不可数）"},{"tag":"n.","zh":"广告作品的总称（不可数）"},{"tag":"v.-ing","zh":"做广告；投放广告（advertise 的现在分词）"}],"collocations":[{"phrase":"the advertising industry","zh":"广告业"},{"phrase":"an advertising campaign","zh":"一场广告宣传活动"},{"phrase":"advertising revenue","zh":"广告收入"},{"phrase":"advertising agency","zh":"广告代理公司"},{"phrase":"online advertising","zh":"网络广告"},{"phrase":"a career in advertising","zh":"广告业的职业"}],"forms":[{"label":"动词原形","form":"advertise"},{"label":"三单（he/she/it）","form":"advertises"},{"label":"过去式","form":"advertised"},{"label":"名词（一则广告）","form":"advertisement"},{"label":"名词（广告主）","form":"advertiser"},{"label":"复数（少见，指多种广告做法）","form":"advertisings"}],"derivatives":[{"word":"advertise","pos":"v.","zh":"做广告"},{"word":"advertisement","pos":"n.","zh":"广告；告示"},{"word":"advertiser","pos":"n.","zh":"广告主"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"},{"word":"ad-man","pos":"n.","zh":"（口语）广告人"}],"senses":[{"no":"01","title":"The industry as a whole","titleCN":"广告业（作为整体）","definition":"the business of producing and placing paid notices for clients","definitionCN":"为客户制作并投放付费告示的行当","example":"She has worked in advertising for twenty years.","exampleCN":"她在广告业干了二十年。","why":"The -ing form turns the verb into a mass noun, so the whole trade can be named without counting anything.","whyCN":"-ing 形式把动词变成不可数的集合名词，于是整个行当可以被命名而不必计数。"},{"no":"02","title":"The activity of promoting","titleCN":"做广告这一行为","definition":"the act of promoting goods or services through paid notices","definitionCN":"通过付费告示推销商品或服务的动作","example":"Advertising pays for most of the free apps on your phone.","exampleCN":"你手机上大多数免费应用由广告买单。","why":"Gerunds name actions; here the action is a repeated one carried on by many firms at once.","whyCN":"动名词命名的是动作；这里的动作由许多公司同时反复进行。"},{"no":"03","title":"Ad material in bulk","titleCN":"广告作品的总称","definition":"all the advertisements a firm or a period produces, taken together","definitionCN":"某个公司或某个时期产出的全部广告，合在一起看","example":"The museum show traces a century of British advertising.","exampleCN":"这场博物馆展览梳理了英国一百年的广告作品。","why":"Once the activity has produced many objects, the same word can name the pile of objects.","whyCN":"一旦这项活动产出许多物件，同一个词就可以指那一堆物件。"},{"no":"04","title":"The academic subject","titleCN":"广告学（学科）","definition":"the study of how paid promotion works, taught as a university subject","definitionCN":"研究付费推广如何运作的学问，作为大学课程开设","example":"He teaches advertising and consumer psychology.","exampleCN":"他教广告学与消费者心理学。","why":"Any trade with a body of rules can become a field of study, and the mass noun simply moves into the classroom.","whyCN":"任何有一套规则的行当都能变成一门学问，这个集合名词就这样走进了课堂。"},{"no":"05","title":"The department or function","titleCN":"广告部门；广告职能","definition":"the unit inside a company that handles promotion","definitionCN":"公司内部负责推广工作的部门","example":"Send the draft to advertising before it goes out.","exampleCN":"稿子在发出前先送到广告部。","why":"A function inside a firm takes the name of its activity, as with marketing or accounting.","whyCN":"公司内部的一项职能常以它的活动命名，marketing、accounting 也是这样。"},{"no":"06","title":"Non-commercial publicity","titleCN":"公益或政治宣传","definition":"paid or organized promotion of a cause, a party or a public message","definitionCN":"为某项事业、某个政党或某条公共信息所做的付费或有组织的推广","example":"Political advertising dominates the final weeks of the race.","exampleCN":"政治宣传在选战最后几周占据主导。","why":"The machinery of paid attention does not care whether the thing sold is a soap or a candidate.","whyCN":"这套「买注意力」的机器并不在乎卖的是肥皂还是候选人。"},{"no":"07","title":"The craft or method","titleCN":"广告手法；投放策略","definition":"the techniques used to design and place promotional messages","definitionCN":"设计与投放推广信息所用的技巧","example":"Good advertising knows which half of the budget is wasted.","exampleCN":"高明的广告手法知道预算里哪一半是浪费的。","why":"The gerund can also name a skill, the way cooking names both the act and the craft.","whyCN":"动名词也能指一门手艺，就像 cooking 既指动作也指厨艺。"},{"no":"08","title":"The revenue model","titleCN":"广告收入模式","definition":"the system by which free content is funded by paid notices","definitionCN":"用付费告示支撑免费内容的盈利方式","example":"The paper moved from subscriptions to advertising.","exampleCN":"这家报纸从订阅制转向广告收入。","why":"This is the industry as a source of money rather than as a source of messages.","whyCN":"这是把广告业当作钱的来源，而不是信息的来源。"}],"etymology":{"intro":{"en":"Advertising is simply the -ing form of advertise, but it grew a life of its own once the trade became an industry in the nineteenth century.","cn":"advertising 本来只是 advertise 的 -ing 形式，但自从十九世纪这一行变成工业，它就长出了自己的生命。"},"items":[{"era":"LATIN VERTERE","en":"The root is Latin vertere 'to turn', the same base as versus, verse and divert.","cn":"词根是拉丁 vertere「转」，与 versus、verse、divert 同出一个词基。"},{"era":"LATIN ADVERTERE","en":"Advertere 'to turn toward' is ad- 'to' plus vertere. English took the idea of turning attention, not the Latin word itself.","cn":"advertere「转向」是 ad-「朝向」加 vertere。英语取走的是「转移注意力」这个意念，而不是拉丁词本身。"},{"era":"ENGLISH -ING NOUN","en":"The English suffix -ing turns a verb into a verbal noun. From the seventeenth century such nouns could also name an activity as a lasting trade.","cn":"英语后缀 -ing 把动词变成动名词。从十七世纪起，这类名词也能把一项活动命名为长期的行当。"},{"era":"NINETEENTH CENTURY","en":"With cheap newspapers and mass circulation, advertising became a recognized trade with agencies, rates and its own staff.","cn":"随着廉价报纸与大众发行，广告成为被承认的行当，有了代理公司、价目与自己的从业者。"},{"era":"TWENTIETH CENTURY","en":"Broadcast added radio and television slots, and the mass noun extended to cover political and public-service messages.","cn":"广播带来了电台与电视时段，这个集合名词也扩展到政治与公共服务信息。"},{"era":"DIGITAL ERA","en":"Online placement made advertising a funding model as much as a craft, and the word now also means the revenue side of a free service.","cn":"网络投放使广告既是一门手艺，也是一种融资模式，这个词现在也指免费服务的收入侧。"}]},"similar":{"note":{"en":"Group one contains forms of the same verb family; group two contains words close in meaning but different in grammar or scope.","cn":"第一组是同一动词族的各种形式；第二组意思接近，但语法性质或覆盖范围不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advertisement","ipa":"/ˌædvəˈtaɪsmənt/","tag":"countable","definition":"One single notice. Use it when you can say 'one', 'two', 'three'.","definitionCN":"一则单独的告示。能说「一则、两则、三则」时用它。"},{"word":"advertise","ipa":"/ˈædvətaɪz/","tag":"verb","definition":"The action, with a subject and usually an object: a firm advertises something.","definitionCN":"动作，带主语，通常还带宾语：某公司为某物做广告。"},{"word":"advertiser","ipa":"/ˈædvətaɪzə/","tag":"person or firm","definition":"The party that pays; it is a countable person or company, not an activity.","definitionCN":"出钱的一方；是可数的人或公司，不是一项活动。"},{"word":"advert","ipa":"/ˈædvɜːt/","tag":"clipped noun","definition":"British informal short form for one advertisement; it cannot mean the industry.","definitionCN":"英式口语里单则广告的缩略形式；不能指整个行业。"}]},{"heading":"NEAR MEANING","entries":[{"word":"marketing","ipa":"/ˈmɑːkɪtɪŋ/","tag":"wider field","definition":"The whole process from product design to pricing, distribution and promotion; advertising is one part of it.","definitionCN":"从产品设计到定价、渠道与推广的整个过程；广告只是其中一部分。"},{"word":"publicity","ipa":"/pʌbˈlɪsəti/","tag":"attention, often free","definition":"The attention itself, which may be earned through news rather than bought.","definitionCN":"指注意力本身，可能靠新闻赢得，而不是买来的。"},{"word":"promotion","ipa":"/prəˈməʊʃən/","tag":"includes discounts","definition":"Any push to increase sales, including price cuts and gifts, not only paid notices.","definitionCN":"任何推动销量的做法，包括降价与赠品，不只是付费告示。"},{"word":"branding","ipa":"/ˈbrændɪŋ/","tag":"identity, not placement","definition":"The work of giving a product a name, look and personality, rather than buying space to announce it.","definitionCN":"给产品名字、外观与性格的工作，而不是买版面去宣告它。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffix behaviour, real compounds and real industry phrases.","cn":"正常联想：真实的后缀行为、真实的复合词与真实的行业说法。"},"normal":[{"en":"-ing turns the verb into a mass noun, just as cooking names both an act and a trade.","cn":"-ing 把动词变成不可数名词，正如 cooking 既指动作也指行业。"},{"en":"The family is a ladder: advertise → advertising → advertiser → advertisement.","cn":"这一族是一把梯子：advertise → advertising → advertiser → advertisement。"},{"en":"Fixed phrases name the business: advertising industry, advertising revenue, advertising agency.","cn":"固定搭配命名这门生意：广告业、广告收入、广告代理公司。"},{"en":"American English also uses the spelling adverting in very old texts, but modern usage keeps advertising.","cn":"极古的文本里偶见 adverting 的写法，现代用法则固定为 advertising。"},{"en":"The phrase 'a career in advertising' shows the mass noun naming a whole profession.","cn":"短语 a career in advertising 表明这个集合名词可以指一整个职业领域。"}],"abstract":[{"en":"Picture a city at night where every window speaks at once; that chorus is advertising.","cn":"想象一座夜里的城市，每扇窗都在同时说话；那片合唱就是广告。"},{"en":"The word never points to one voice, only to the noise as a whole.","cn":"这个词从不指向某一个声音，只指向整片喧响。"},{"en":"So it is countable only in the rare case when you want to count kinds of noise.","cn":"所以它只有在极少见地要数「几种喧响」时才可数。"}]},"examples":[{"en":"Advertising revenue fell sharply when the magazine lost its readers.","cn":"杂志失去读者后，广告收入急剧下滑。"},{"en":"He wrote his thesis on advertising and children's food choices.","cn":"他的论文写的是广告与儿童的食物选择。"},{"en":"The agency has been in advertising since the days of hand-painted signs.","cn":"这家代理公司从手绘招牌的年代起就在做广告。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿德-歪台静」——阿德把招牌歪着举起来，街道一下就安静了，只剩广告在说话 → advertising 广告业","word":"advertising"},"root":"advertise 的 -ing 形式；advertise 出自拉丁 advertere「转向、把注意力引向」= ad- + vertere「转」。","sensesIntro":{"en":"Eight senses show one mass noun spreading from an act to a trade, a body of work, a subject, a department, a method and finally a way of earning money.","cn":"八个义项显示同一个集合名词如何从动作扩散到行业、作品总体、学科、部门、方法，最后到一种赚钱方式。"},"semanticMap":{"core":{"en":"CORE IMAGE: one verb's action, thickened into a whole climate of messages.","cn":"核心意象：一个动词的动作，浓成一片信息气候。"},"chain":["TURN ATTENTION","PUBLIC NOTICE","MASS MESSAGES","TRADE","CRAFT","REVENUE"],"branches":[{"senses":"01 · 05","en":"TRADE AND DESK: the whole industry and the office inside a firm are the same activity seen from outside and inside.","cn":"行业与部门：整个行当与公司里的那间办公室，是同一活动的内外两个视角。"},{"senses":"02 · 03","en":"ACT AND PILE: the doing and the accumulated material are one mass noun used two ways.","cn":"动作与堆积：做的过程与积下的材料，是同一个集合名词的两种用法。"},{"senses":"04","en":"CLASSROOM: a trade with rules becomes a subject to study.","cn":"课堂：有规则的行当变成一门可研究的学问。"},{"senses":"06","en":"OTHER CAUSES: a party or a public message hires the same machinery.","cn":"别的事业：政党或公共信息租用同一套机器。"},{"senses":"07 · 08","en":"METHOD AND MONEY: the craft of placing messages and the income that placement generates.","cn":"方法与金钱：投放信息的手艺，以及投放带来的收入。"}]},"affixes":{"intro":{"en":"Advertising is built from the verb advertise plus the noun-forming suffix -ing, and the verb itself splits into a Latin prefix and a Latin root.","cn":"advertising 由动词 advertise 加名词化后缀 -ing 构成，而这个动词本身又可分为拉丁前缀与拉丁词根。"},"latinIntro":{"en":"Advertere 'to turn toward' supplies the meaning; the English suffix -ing supplies the grammar of a mass noun.","cn":"advertere「转向」提供意义；英语后缀 -ing 提供集合名词的语法身份。"},"items":[{"word":"-ing","structure":"-ing (verbal noun suffix)","meaning":"the act, or the activity as a whole","meaningCN":"动作，或作为整体的活动","example":"The suffix makes a mass noun from a verb.","exampleCN":"这个后缀把动词变成不可数名词。"},{"word":"ad-","structure":"ad- (Latin prefix, 'toward')","meaning":"toward","meaningCN":"朝向","example":"The prefix directs the action.","exampleCN":"这个前缀给动作定方向。"},{"word":"vert","structure":"vertere (Latin root, 'turn')","meaning":"to turn","meaningCN":"转","example":"The root also builds convert.","exampleCN":"这个词根还构成 convert。"},{"word":"advertise","structure":"advertise (base verb)","meaning":"to promote by paid notice","meaningCN":"以付费告示推销","example":"Firms advertise to reach buyers.","exampleCN":"公司做广告以触达买家。"},{"word":"advertising","structure":"advertise + -ing","meaning":"the activity or industry","meaningCN":"广告活动；广告业","example":"Advertising funds free services.","exampleCN":"广告为免费服务提供资金。"},{"word":"advertisement","structure":"advertise + -ment","meaning":"one notice","meaningCN":"一则告示","example":"The advertisement ran for a week.","exampleCN":"这则广告投放了一周。"},{"word":"advertiser","structure":"advertise + -er","meaning":"the paying party","meaningCN":"出钱的一方","example":"Advertisers want measurable reach.","exampleCN":"广告主要求可衡量的触达。"},{"word":"advert","structure":"advert (clipped)","meaning":"a single ad","meaningCN":"单则广告","example":"He answered an advert for a flat.","exampleCN":"他回应了一则租房广告。"},{"word":"adverse","structure":"ad- + vers-","meaning":"turned against","meaningCN":"转向对抗的","example":"Adverse publicity hurt sales.","exampleCN":"负面报道损害了销量。"}],"latinEntries":[{"word":"vertere","structure":"vertere, verti, versum (verb)","meaning":"to turn","meaningCN":"转"},{"word":"advertere","structure":"ad- + vertere","meaning":"to turn toward","meaningCN":"转向"},{"word":"versus","structure":"past participle of vertere","meaning":"turned; a line in turning","meaningCN":"转过的；转向的一行"}],"derivatives":[{"word":"advertise","pos":"v.","zh":"做广告"},{"word":"advertisement","pos":"n.","zh":"广告；告示"},{"word":"advertiser","pos":"n.","zh":"广告主"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"},{"word":"ad-man","pos":"n.","zh":"（口语）广告人"}]}},{"word":"advertiser","ipa_uk":"/ˈædvətaɪzə/","ipa_us":"/ˈædvərtaɪzər/","definition_zh":"广告主；登广告的人；投放广告的企业","definition_en":"the person or firm that pays for and places a public notice promoting something","core_image":"一间办公室里的人把支票和一张海报一起递出去，买下别人的目光","scene":"会议室里，市场部把钱和一张海报一起推到桌上，买下整条街的目光。The advertiser asked for a full page opposite the crossword.","sceneCN":"会议室里，市场部把钱和一张海报一起推上桌，买下整条街的目光；句中的这个词指「出钱投放广告的一方」（第 1 个义项：付费让告示出现在媒体上的人或企业）。图中可辨识物件：会议桌、支票、海报、版面样张、字幕格。","pos":[{"tag":"n.","zh":"广告主；出钱登广告的人或企业（可数）"},{"tag":"n.","zh":"登分类广告的人（卖房、招人、寻物）"}],"collocations":[{"phrase":"a major advertiser","zh":"大广告主"},{"phrase":"the advertiser's budget","zh":"广告主的预算"},{"phrase":"attract advertisers","zh":"吸引广告主"},{"phrase":"advertiser-funded","zh":"由广告主出资的"},{"phrase":"a national advertiser","zh":"全国性广告主"},{"phrase":"advertiser demand","zh":"广告主需求"}],"forms":[{"label":"复数","form":"advertisers"},{"label":"动词（做广告）","form":"advertise"},{"label":"名词（广告活动；广告业）","form":"advertising"},{"label":"名词（一则广告）","form":"advertisement"},{"label":"形容词（由广告主出资的）","form":"advertiser-funded"}],"derivatives":[{"word":"advertise","pos":"v.","zh":"做广告"},{"word":"advertising","pos":"n.","zh":"广告业；广告活动"},{"word":"advertisement","pos":"n.","zh":"广告；告示"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"},{"word":"advertised","pos":"adj.","zh":"在广告中公布的"}],"senses":[{"no":"01","title":"The party that pays for the notice","titleCN":"出钱投放广告的一方","definition":"a person or firm that pays to have a promotional notice placed in a medium","definitionCN":"出钱让推销告示出现在媒体上的人或企业","example":"The advertiser asked for a full page opposite the crossword.","exampleCN":"广告主要求在填字游戏对面买一整版。","why":"The -er suffix marks the doer; here the deed is paying for attention, so the doer is the buyer of space.","whyCN":"-er 后缀标示动作的发出者；这里的动作是「花钱买注意力」，所以发出者就是买版面的人。"},{"no":"02","title":"The media buyer acting for a firm","titleCN":"替公司买版面的媒介执行者","definition":"the marketing staff member who negotiates and buys space or time on behalf of a company","definitionCN":"代表公司谈判并购买版面或时段的营销人员","example":"As the advertiser's agent, she books all the radio slots.","exampleCN":"作为广告主的代理，她预订了所有电台时段。","why":"The payer can act through an agent, and the agent still speaks with the payer's name on the contract.","whyCN":"出钱方可以委托代理人行事，而合同上写的仍是出钱方的名字。"},{"no":"03","title":"One who places a classified line","titleCN":"登分类小广告的人","definition":"a private person who pays for a short notice to sell, let or find something","definitionCN":"花钱登一条短告示，用来出售、出租或寻找某物的私人","example":"The advertiser withdrew the notice after the bike was sold.","exampleCN":"自行车卖掉后，登广告的人撤下了那则告示。","why":"A single line in the classified column makes an ordinary person an advertiser for a week.","whyCN":"分类版上的一行字，就能让一个普通人在一周内成为广告主。"},{"no":"04","title":"The party recruiting","titleCN":"登广告招人的一方","definition":"an employer or organization that advertises a vacancy or a call for volunteers","definitionCN":"登广告发布空缺职位或招募志愿者的雇主或机构","example":"The advertiser offered a salary well above the local average.","exampleCN":"招募方开出的薪水远高于当地平均。","why":"A vacancy notice is still a paid notice, so the employer takes the same name as a soap seller.","whyCN":"招聘告示仍是付费告示，所以雇主与卖肥皂的人共用同一个称呼。"},{"no":"05","title":"Anyone who advertises, informally","titleCN":"口语泛指：做广告的人","definition":"in loose speech, any person or group that promotes something in public","definitionCN":"口语中宽泛地指任何公开宣传某事的人或团体","example":"Every advertiser in town wanted a place on that wall.","exampleCN":"镇上每个做广告的人都想在那面墙上占一个位置。","why":"Loose speech drops the payment condition and keeps only the act of promoting.","whyCN":"口语丢掉了「付费」这个条件，只保留了「宣传」这个动作。"},{"no":"06","title":"The medium's client","titleCN":"媒体眼中的广告客户","definition":"seen from the media side, the customer who buys its space or time","definitionCN":"从媒体一侧看，购买其版面或时段的客户","example":"The station lost its biggest advertiser in the spring.","exampleCN":"这家电台在春天失去了最大的广告客户。","why":"The relation has two ends: the firm is the seller of goods, but the client of the newspaper.","whyCN":"这层关系有两端：这家公司在卖货，却是报纸的客户。"},{"no":"07","title":"A promoter of an idea","titleCN":"理念的宣传者","definition":"a group that pays to spread a cause or a public message rather than a product","definitionCN":"付费传播某项事业或公共信息、而非商品的团体","example":"The health charity became the largest advertiser on the bus network.","exampleCN":"那家健康慈善机构成了公交网络上最大的广告主。","why":"If a cause can buy attention, the buyer of that attention is an advertiser just the same.","whyCN":"如果一项事业也能买注意力，那么买这份注意力的人同样就是广告主。"},{"no":"08","title":"The sponsor behind a message","titleCN":"广告赞助商","definition":"the backer whose money carries a message, credited at the end of it","definitionCN":"出钱承载某条信息、并在信息末尾被署名的一方","example":"The advertiser's name appears in the last frame of the film.","exampleCN":"广告主的名字出现在影片最后一帧。","why":"Sponsorship is payment for attention with the name made visible, which is the advertiser's defining wish.","whyCN":"赞助就是花钱买注意力并把名字露出来，这正是广告主最根本的诉求。"}],"etymology":{"intro":{"en":"Advertiser is a plain English derivative: the verb plus the agent suffix. Its meaning narrowed as the verb narrowed.","cn":"advertiser 是一个朴素的英语派生词：动词加施事后缀。它的词义随着动词一起收窄。"},"items":[{"era":"LATIN VERTERE","en":"Latin vertere 'to turn' is the distant root, also behind versus and divert.","cn":"拉丁 vertere「转」是更远的词根，也藏在 versus 与 divert 背后。"},{"era":"LATIN ADVERTERE","en":"Ad- 'toward' plus vertere gave advertere 'to turn toward'. The idea reached English through the French verb avertir.","cn":"ad-「朝向」加 vertere 构成 advertere「转向」。这个意念经法语动词 avertir 传到英语。"},{"era":"ENGLISH AGENT SUFFIX","en":"The suffix -er forms nouns for the doer of a verb, as in teacher and buyer. Attached to advertise it yields advertiser.","cn":"后缀 -er 为动词的施事造名词，如 teacher 与 buyer。加到 advertise 上就得到 advertiser。"},{"era":"SIXTEENTH CENTURY","en":"The earliest recorded use names a person who gives notice, matching the then-current meaning of the verb.","cn":"最早有记录的用法指「发出通知的人」，与当时动词的意思一致。"},{"era":"EIGHTEENTH CENTURY","en":"When advertise came to mean publishing a notice of goods, advertiser came to mean the party paying for that notice.","cn":"当 advertise 变成「刊登商品告示」，advertiser 也随之变成「为那则告示付钱的一方」。"},{"era":"MODERN ENGLISH","en":"In the modern trade the word usually means the client of a medium or agency, and it appears in compounds such as advertiser-funded.","cn":"在现代行业里，这个词通常指媒体或代理公司的客户，并出现在 advertiser-funded 这类复合词中。"}]},"similar":{"note":{"en":"Group one is built from the same verb; group two names neighbouring roles in the same trade.","cn":"第一组由同一个动词构成；第二组是同一行业里相邻的角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"advertising","ipa":"/ˈædvətaɪzɪŋ/","tag":"activity","definition":"The activity or industry; it has no doer and cannot be counted as a person.","definitionCN":"指活动或行业；它没有施事者，也不能当作一个人来数。"},{"word":"advertisement","ipa":"/ˌædvəˈtaɪsmənt/","tag":"the thing","definition":"The notice itself, not the party that pays for it.","definitionCN":"指告示本身，而不是为它付钱的一方。"},{"word":"advertise","ipa":"/ˈædvətaɪz/","tag":"verb","definition":"The action; the -er noun adds a person who performs it.","definitionCN":"动作；加 -er 后指执行这个动作的人。"},{"word":"adviser","ipa":"/əˈvaɪzə/","tag":"different root","definition":"One who gives advice, from Latin videre 'to see'; the spelling differs by a single letter and the meaning is far apart.","definitionCN":"给建议的人，出自拉丁 videre「看」；拼写只差一个字母，意思相去甚远。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sponsor","ipa":"/ˈspɒnsə/","tag":"pays for association","definition":"A backer who pays to be linked with an event or programme, often without a standalone notice.","definitionCN":"出钱与某活动或节目建立关联的赞助者，往往没有独立的告示。"},{"word":"client","ipa":"/ˈklaɪənt/","tag":"agency's view","definition":"The advertiser as seen by the agency that serves it, one step further from the medium.","definitionCN":"从为其服务的代理公司角度看，广告主就是客户，比媒体的视角又远一层。"},{"word":"marketer","ipa":"/ˈmɑːkɪtə/","tag":"wider role","definition":"The person who plans the whole selling effort, of which placing notices is one task.","definitionCN":"筹划整个销售努力的人，投放告示只是其中一项任务。"},{"word":"publisher","ipa":"/ˈpʌblɪʃə/","tag":"opposite side","definition":"The owner of the medium that sells the space; the advertiser is its customer, not its peer.","definitionCN":"出售版面的媒体所有者；广告主是它的客户，而不是同类。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffix function, real compounds and real roles in the trade.","cn":"正常联想：真实的后缀功能、真实的复合词与行业中的真实角色。"},"normal":[{"en":"advertise + -er: the -er marks the one who pays for the notice.","cn":"advertise 加 -er：-er 标示出为告示付钱的那一方。"},{"en":"The family ladder is advertise → advertiser → advertisement → advertising.","cn":"这一族的梯子是 advertise → advertiser → advertisement → advertising。"},{"en":"Fixed phrases show the role: a major advertiser, the advertiser's budget, attract advertisers.","cn":"固定搭配显示角色：大广告主、广告主的预算、吸引广告主。"},{"en":"Advertiser-funded marks the model where the payer, not the reader, covers the cost.","cn":"advertiser-funded 标示那种由出钱方而非读者承担成本的模式。"},{"en":"Do not mix it with adviser: one pays for space, the other gives advice.","cn":"别把它和 adviser 混起来：一个买版面，一个给建议。"}],"abstract":[{"en":"Picture a hand writing a cheque and, in the same motion, pointing at a poster.","cn":"想象一只手在写支票，同一个动作里又指向一张海报。"},{"en":"The advertiser never appears in the message as a person, only as the name at the edge of it.","cn":"广告主从不在信息里作为一个人出现，只在信息的边缘留下名字。"},{"en":"So the word marks the edge where money meets attention.","cn":"所以这个词标出的正是金钱与注意力相接的那条边。"}]},"examples":[{"en":"The magazine's advertisers demanded a cheaper rate for the winter issues.","cn":"这家杂志的广告主要求冬季几期降价。"},{"en":"As the biggest advertiser in the region, the brewery could choose its slots.","cn":"作为本区最大的广告主，那家啤酒厂可以挑时段。"},{"en":"Each advertiser receives a monthly report on how many people saw the notice.","cn":"每位广告主每月都会收到一份报告，说明有多少人看到了那则告示。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「阿德-歪台泽」——阿德歪着身子把台子上的钱推出去，买下别人的目光 → advertiser 广告主","word":"advertiser"},"root":"advertise + -er（施事后缀）；advertise 出自拉丁 advertere「转向、把注意力引向」= ad- + vertere「转」。","sensesIntro":{"en":"Eight senses keep one role: the party whose money turns attention. The role shifts only in who fills it — a firm, an agent, a private seller, an employer, a cause or a sponsor.","cn":"八个义项守住同一个角色：出钱把注意力转过来的那一方。变的只是谁来担任——企业、代理人、私人卖家、雇主、某项事业或赞助商。"},"semanticMap":{"core":{"en":"CORE IMAGE: money leaves one hand and attention arrives from many eyes.","cn":"核心意象：钱从一只手出去，注意力从许多双眼睛回来。"},"chain":["PAY","BUY SPACE","REACH BUYERS","CLIENT","MESSAGE","SPONSOR"],"branches":[{"senses":"01 · 06","en":"TWO SIDES OF ONE CONTRACT: the buyer of space is the customer of the medium.","cn":"同一份合同的两面：买版面的人就是媒体的客户。"},{"senses":"02","en":"DELEGATED PURSE: an agent spends the firm's money and signs in the firm's name.","cn":"受托的钱包：代理人花公司的钱，用公司的名义签字。"},{"senses":"03 · 04","en":"SMALL AND LARGE PAYERS: one line in the classifieds or a salary advertisement both buy a slot.","cn":"小额与大额付钱者：分类栏里的一行字和一则薪资广告，买的都是同一个位置。"},{"senses":"05","en":"LOOSE SPEECH: drop the payment and only the promoting remains.","cn":"口语宽用：去掉付费，只剩下宣传。"},{"senses":"07 · 08","en":"CAUSE AND NAME: a charity buys attention for an idea, and a sponsor buys the visibility of its own name.","cn":"事业与名字：慈善机构为理念买注意力，赞助商为自己的名字买曝光。"}]},"affixes":{"intro":{"en":"Advertiser adds a common English agent suffix to a Latin-derived verb, so the word reads as 'the one who advertises'.","cn":"advertiser 给一个拉丁来源的动词加上常见英语施事后缀，于是整个词读作「做广告的那个人」。"},"latinIntro":{"en":"The Latin base is advertere 'to turn toward' (ad- plus vertere); the suffix -er is native English word-building.","cn":"拉丁词基是 advertere「转向」（ad- 加 vertere）；后缀 -er 则是英语本土的构词手段。"},"items":[{"word":"-er","structure":"-er (agent noun suffix)","meaning":"the person or firm that does something","meaningCN":"做某事的人或公司","example":"The suffix turns the verb into a role.","exampleCN":"这个后缀把动词变成一个角色。"},{"word":"ad-","structure":"ad- (Latin prefix, 'toward')","meaning":"toward","meaningCN":"朝向","example":"The prefix aims the action.","exampleCN":"这个前缀给动作定向。"},{"word":"vert","structure":"vertere (Latin root, 'turn')","meaning":"to turn","meaningCN":"转","example":"Convert and divert carry it too.","exampleCN":"convert 与 divert 也带着它。"},{"word":"advertise","structure":"advertise (base verb)","meaning":"to pay for public attention","meaningCN":"花钱买公众注意力","example":"They advertise to reach buyers.","exampleCN":"他们做广告以触达买家。"},{"word":"advertiser","structure":"advertise + -er","meaning":"the party that pays","meaningCN":"出钱的一方","example":"The advertiser approved the artwork.","exampleCN":"广告主通过了这版画面。"},{"word":"advertising","structure":"advertise + -ing","meaning":"the activity","meaningCN":"活动；行业","example":"Advertising pays for the service.","exampleCN":"广告为这项服务提供资金。"},{"word":"advertisement","structure":"advertise + -ment","meaning":"one notice","meaningCN":"一则告示","example":"The advertisement ran on page five.","exampleCN":"这则广告登在第五版。"},{"word":"advert","structure":"advert (clipped)","meaning":"a single ad","meaningCN":"单则广告","example":"The advert brought ten calls.","exampleCN":"那则广告带来十个电话。"},{"word":"adverse","structure":"ad- + vers-","meaning":"turned against","meaningCN":"转向对抗的","example":"Adverse reviews followed the launch.","exampleCN":"发布之后出现了负面评论。"}],"latinEntries":[{"word":"advertere","structure":"ad- + vertere","meaning":"to turn toward","meaningCN":"转向"},{"word":"vertere","structure":"vertere, verti, versum (verb)","meaning":"to turn","meaningCN":"转"},{"word":"adversus","structure":"past participle of advertere","meaning":"turned against","meaningCN":"转过来对抗的"}],"derivatives":[{"word":"advertise","pos":"v.","zh":"做广告"},{"word":"advertising","pos":"n.","zh":"广告业；广告活动"},{"word":"advertisement","pos":"n.","zh":"广告；告示"},{"word":"advert","pos":"n.","zh":"（英式口语）广告"},{"word":"advertised","pos":"adj.","zh":"在广告中公布的"}]}},{"word":"promotion","ipa_uk":"/prəˈməʊʃən/","ipa_us":"/prəˈmoʊʃən/","definition_zh":"晋升；促销；推广；提倡；升级","definition_en":"the act of moving someone or something forward, whether in rank, in sales or in public acceptance","core_image":"一只手把站在后排的人往前推一步，推到灯下；同一只手又把商品往前推，推到顾客手边","scene":"货架端头的折扣牌被推到最显眼处，仓储里的存货被搬到顾客手边。The promotion cut every price by a third for the weekend.","sceneCN":"货架端头的折扣牌被推到最显眼处，仓库里的存货被搬到顾客手边；句中的这个词指「为拉动销量而设的优惠活动」（第 2 个义项：以降价、赠品等方式在短期内推动销量的做法）。图中可辨识物件：货架端头、折扣牌、堆叠的存货、价签、伸出的手。","pos":[{"tag":"n.","zh":"晋升；提拔（可数）"},{"tag":"n.","zh":"促销活动；优惠活动（可数，商业用语）"},{"tag":"n.","zh":"推广；提倡；促进（不可数）"}],"collocations":[{"phrase":"win a promotion","zh":"获得晋升"},{"phrase":"a sales promotion","zh":"促销活动"},{"phrase":"a promotion campaign","zh":"推广活动"},{"phrase":"health promotion","zh":"健康促进"},{"phrase":"a promotion offer","zh":"优惠活动"},{"phrase":"chances of promotion","zh":"晋升机会"}],"forms":[{"label":"复数","form":"promotions"},{"label":"动词（推动；晋升；促销）","form":"promote"},{"label":"形容词（促销的；推广的）","form":"promotional"},{"label":"名词（推动者；发起人）","form":"promoter"},{"label":"形容词（被提升的）","form":"promoted"}],"derivatives":[{"word":"promote","pos":"v.","zh":"推动；晋升；推广"},{"word":"promoter","pos":"n.","zh":"推动者；主办者"},{"word":"promotional","pos":"adj.","zh":"促销的；推广的"},{"word":"promoted","pos":"adj.","zh":"被提升的"},{"word":"promotable","pos":"adj.","zh":"有晋升潜力的"}],"senses":[{"no":"01","title":"A move to a higher rank","titleCN":"晋升、提拔","definition":"a move to a higher position or rank at work","definitionCN":"在工作上被移到更高的职位或级别","example":"She was given a promotion after the audit.","exampleCN":"审计结束后她得到了晋升。","why":"Pro- 'forward' plus movere 'to move' gives 'a moving forward', and a career ladder is climbed one step at a time.","whyCN":"pro-「向前」加 movere「移动」构成「往前移」，而职业阶梯正是一步一步往上走的。"},{"no":"02","title":"A special offer to raise sales","titleCN":"促销活动","definition":"a special offer, such as a discount or a gift, designed to raise sales quickly","definitionCN":"以降价或赠品等方式在短期内快速拉动销量的特殊优惠","example":"The store ran a two-for-one promotion on coffee.","exampleCN":"这家店做了咖啡买一送一的促销。","why":"The same forward push is applied to goods: they are moved toward the buyer's hand rather than a person toward a higher desk.","whyCN":"同一个「往前推」用在货物上：被推向顾客手边的是商品，而不是人被推向更高的职位。"},{"no":"03","title":"Publicity to make something accepted","titleCN":"推广、宣传","definition":"organized publicity intended to make a product, event or idea accepted","definitionCN":"为使产品、活动或理念被接受而组织起来的推广宣传","example":"The film's promotion included interviews in six cities.","exampleCN":"这部电影的推广包括在六个城市做访谈。","why":"Moving a thing forward in public is the same verb, with reputation standing in for rank.","whyCN":"在公众面前把某物往前推仍是同一个动词，只是「级别」换成了「名声」。"},{"no":"04","title":"Active support for a cause","titleCN":"对某项事业的提倡与支持","definition":"active support for a cause, habit or practice","definitionCN":"对某项事业、习惯或做法的积极支持","example":"The programme is a promotion of healthier eating in schools.","exampleCN":"这个项目是对校园健康饮食的提倡。","why":"To promote a cause is to push it forward until other people take it up.","whyCN":"提倡一项事业，就是把它往前推，直到别人也接受它。"},{"no":"05","title":"The discounted item itself","titleCN":"促销品（英式用法）","definition":"in British usage, a product sold at a reduced price or offered as an inducement","definitionCN":"英式用法中指降价出售或作为诱因提供的产品","example":"The supermarket's promotions were stacked by the entrance.","exampleCN":"超市的促销品堆在入口旁。","why":"The abstract push turns concrete: the thing used to push sales takes the name of the push.","whyCN":"抽象的「推」变具体了：被用来推动销量的那件东西，直接借用了「推」这个名字。"},{"no":"06","title":"The prospect of rising","titleCN":"晋升机会","definition":"the possibility of being moved to a higher rank, rather than the move itself","definitionCN":"被提到更高职位的可能性，而不是那次调动本身","example":"There is little promotion in a flat organization.","exampleCN":"在扁平的组织里几乎没有晋升机会。","why":"An uncountable reading names the prospect instead of the finished event.","whyCN":"不可数的读法指的是「有这种可能」，而不是已经完成的那个事件。"},{"no":"07","title":"A team moving up a division","titleCN":"球队升级","definition":"the movement of a sports team into a higher division","definitionCN":"运动队被提升到更高一级联赛","example":"The club celebrated its promotion to the first division.","exampleCN":"俱乐部庆祝球队升入甲级。","why":"A league is a ladder too, and a team climbs it by exactly the same forward step.","whyCN":"联赛也是一把梯子，球队往上爬走的是完全同一个「向前一步」。"},{"no":"08","title":"Advancing a condition or process","titleCN":"促进、增进（健康等）","definition":"the advancement of a condition or process, as in health promotion","definitionCN":"推动某种状态或过程向前，如健康促进","example":"Health promotion focuses on prevention rather than treatment.","exampleCN":"健康促进重在预防而不是治疗。","why":"What is pushed forward is now an abstract good, a state of health rather than a person or a product.","whyCN":"这里被往前推的是一个抽象的好东西，是健康状况，而不是一个人或一件商品。"}],"etymology":{"intro":{"en":"Promotion is the noun of Latin promovere 'to move forward'. Rank came first, sales came much later.","cn":"promotion 是拉丁 promovere「向前移动」的名词形式。先有的是职位义，卖货义要晚得多。"},"items":[{"era":"LATIN MOVERE","en":"Movere meant 'to move'. Its participle motus gives English motive and motion, and it works inside remove, emotion and commotion.","cn":"movere 意为「移动」。它的分词 motus 给了英语 motive 与 motion，也藏在 remove、emotion、commotion 里。"},{"era":"LATIN PROMOVERE","en":"Pro- 'forward, forth' plus movere produced promovere 'to move forward, to advance, to bring to notice'.","cn":"pro-「向前、往外」加 movere 构成 promovere「向前移、推进、使被注意」。"},{"era":"LATIN PROMOTIO","en":"The action noun promotio named the act of advancing. English took both the noun and the verb, the verb through French.","cn":"动作名词 promotio 指「推进」这个动作。英语把名词和动词都借了进来，动词是经法语来的。"},{"era":"FOURTEENTH CENTURY","en":"The earliest English sense is advancement in rank or dignity, first in church and university usage.","cn":"英语最早的意思是职位或地位的提升，最初用于教会与大学。"},{"era":"NINETEENTH CENTURY","en":"American trade writing applied the word to efforts that push goods toward buyers, and sales promotion became a fixed term.","cn":"十九世纪的美国商业写作把这个词用于「把商品推向买家」的努力，sales promotion 成了固定说法。"},{"era":"MODERN ENGLISH","en":"The twentieth century added large-scale publicity and health promotion, and the word now covers any forward push.","cn":"二十世纪又添上了大规模宣传与健康促进，这个词如今涵盖任何向前的推动。"}]},"similar":{"note":{"en":"Group one shares the moving-forward root; group two names neighbouring commercial actions.","cn":"第一组共享「向前移动」的词根；第二组是相邻的商业动作。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"promote","ipa":"/prəˈməʊt/","tag":"verb form","definition":"The verb: to move someone or something forward. The noun adds -ion.","definitionCN":"动词：把人或物往前推。名词多一个 -ion。"},{"word":"promoter","ipa":"/prəˈməʊtə/","tag":"person","definition":"The person who pushes a project or a fight; a countable role, not the act.","definitionCN":"推动某个项目或赛事的人；是可数角色，不是动作本身。"},{"word":"promotional","ipa":"/prəˈməʊʃənl/","tag":"adjective","definition":"The adjective describing material or offers used for promotion.","definitionCN":"形容词，描述用于推广的材料或优惠。"},{"word":"promontory","ipa":"/prəˈmɒntəri/","tag":"different root","definition":"A headland, from mons 'mountain'; it looks like promotion but has no movere inside.","definitionCN":"海角，出自 mons「山」；外形像 promotion，里面却没有 movere。"}]},{"heading":"NEAR MEANING","entries":[{"word":"advertisement","ipa":"/ˌædvəˈtaɪsmənt/","tag":"one notice","definition":"A single paid notice; promotion is the wider effort that may contain many notices and discounts.","definitionCN":"单则付费告示；promotion 是更宽的努力，可包含许多告示与折扣。"},{"word":"advancement","ipa":"/ədˈvɑːnsmənt/","tag":"career only","definition":"Progress in rank or skill, usually without the commercial sense of selling goods.","definitionCN":"职位或技能上的进步，通常不含推销商品的商业义。"},{"word":"campaign","ipa":"/kæmˈpeɪn/","tag":"organized series","definition":"A planned series of actions over a period; promotion can be a single offer or a whole strategy.","definitionCN":"一段时期内计划好的一连串行动；promotion 可以只是单次优惠，也可以是一整套策略。"},{"word":"publicity","ipa":"/pʌbˈlɪsəti/","tag":"attention itself","definition":"The attention gained, often unpaid; promotion is the deliberate effort to gain it.","definitionCN":"获得的关注，往往不付费；promotion 则是刻意去争取这份关注的努力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Latin pieces and real derived words.","cn":"正常联想：真实的拉丁语构件与真实的派生词。"},"normal":[{"en":"pro- 'forward' + mot- 'move': promotion is a move forward.","cn":"pro-「向前」加 mot-「移动」：promotion 就是一次向前移。"},{"en":"The family runs promote, promotion, promoter, promotional.","cn":"同族词包括 promote、promotion、promoter、promotional。"},{"en":"Fixed phrases split the senses: win a promotion, a sales promotion, health promotion.","cn":"固定搭配把义项分开：获得晋升、促销活动、健康促进。"},{"en":"The same mot- root sits in motion, motive, emotion and remove.","cn":"同一个 mot- 词根还在 motion、motive、emotion 与 remove 里。"},{"en":"A league table uses the word literally: promotion to a higher division.","cn":"联赛积分榜把这个词用得很实在：升入更高一级。"}],"abstract":[{"en":"Picture a hand on someone's back, pushing gently: that push is the whole word.","cn":"想象一只手放在某人背上轻轻往前推：这一推就是整个词的意思。"},{"en":"The push can act on a person (rank), a product (sales) or an idea (publicity).","cn":"这一推可以作用在人（级别）、作用于商品（销量）或作用于理念（宣传）。"},{"en":"Nothing moves by itself; promotion always needs a pushing hand.","cn":"没有东西会自己往前移；promotion 永远需要一只推动的手。"}]},"examples":[{"en":"He earned his promotion by rebuilding the entire accounts system.","cn":"他靠重建整套账务系统赢得了晋升。"},{"en":"The bookshop's winter promotion gives a free novel with every three bought.","cn":"这家书店的冬季促销是买三本送一本小说。"},{"en":"The agency handles promotion for the city's film festival.","cn":"这家代理公司负责这座城市电影节的推广。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「普若-摩申」——普若（向前）一摩，人就升上去了，货也推到手边 → promotion 晋升、促销","word":"promotion"},"root":"拉丁 promovere「向前移动、推进」= pro-（向前）+ movere「移动」；动作名词 promotio。","sensesIntro":{"en":"Eight senses are one push forward: up a career ladder, toward a buyer's hand, into public acceptance, into a league above, or into a better condition.","cn":"八个义项都是同一个「往前推」：沿职业阶梯往上、推向顾客的手边、推进公众的接受、推进更高一级的联赛，或者推向更好的状态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand pushes something one step forward into the light.","cn":"核心意象：一只手把某物往前推一步，推进光里。"},"chain":["MOVE FORWARD","STEP UP","HIGHER RANK","PUSH GOODS","SPREAD WORD","BETTER STATE"],"branches":[{"senses":"01 · 06","en":"LADDER: the finished move up and the mere prospect of it are the same step seen as event and as chance.","cn":"阶梯：已经完成的上升与仅仅存在的上升可能，是同一步的「事件」与「机会」两面。"},{"senses":"02 · 05","en":"GOODS: the offer pushes sales, and the discounted item takes the name of the push itself.","cn":"货物：优惠动作推动销量，而被降价的那件东西直接借用了这个动作的名字。"},{"senses":"03","en":"PUBLICITY: reputation is pushed forward instead of a person or a product.","cn":"名声：被往前推的是声誉，而不是一个人或一件商品。"},{"senses":"04 · 08","en":"CAUSE AND CONDITION: a practice or a state of health is pushed until others take it up.","cn":"事业与状态：一种做法或一种健康状况被推到别人也接受为止。"},{"senses":"07","en":"LEAGUE: a division table is a ladder in plain visible form.","cn":"联赛：分级表就是一把看得见的梯子。"}]},"affixes":{"intro":{"en":"Promotion is a Latin prefix, a Latin root and a Latin noun ending, all three of which build other English words.","cn":"promotion 由拉丁前缀、拉丁词根与拉丁名词词尾构成，三部分都还能构成别的英语词。"},"latinIntro":{"en":"Promovere 'to move forward' is pro- plus movere; the same movere gives motion, motive, remove and emotion.","cn":"promovere「向前移」是 pro- 加 movere；同一个 movere 还给了 motion、motive、remove 与 emotion。"},"items":[{"word":"pro-","structure":"pro- (Latin prefix, 'forward, forth')","meaning":"forward; in front","meaningCN":"向前；在前","example":"The prefix gives the direction of the push.","exampleCN":"这个前缀给出推动的方向。"},{"word":"mov / mot","structure":"movere, motus (Latin root, 'move')","meaning":"to move","meaningCN":"移动","example":"Motion and motive share this root.","exampleCN":"motion 与 motive 共享这个词根。"},{"word":"-tion","structure":"-tion (Latin noun suffix, -tio)","meaning":"the act or result of an action","meaningCN":"动作或动作的结果","example":"The suffix makes an action noun.","exampleCN":"这个后缀造出动作名词。"},{"word":"promote","structure":"promote (base verb)","meaning":"to push forward","meaningCN":"向前推进","example":"They promote local farmers.","exampleCN":"他们推广本地农产品。"},{"word":"promotion","structure":"promote + -ion","meaning":"the act or result of pushing forward","meaningCN":"推进的动作或结果","example":"The promotion lifted sales by half.","exampleCN":"这次促销把销量提高了一半。"},{"word":"promoter","structure":"promote + -er","meaning":"one who pushes a project","meaningCN":"推动某个项目的人","example":"The promoter booked the hall.","exampleCN":"主办者订下了会堂。"},{"word":"promotional","structure":"promotion + -al","meaning":"serving to push sales","meaningCN":"用于推动销量的","example":"They printed promotional leaflets.","exampleCN":"他们印了宣传单。"},{"word":"motive","structure":"mot- + -ive","meaning":"a reason that moves a person","meaningCN":"推动一个人的理由","example":"Profit was not his only motive.","exampleCN":"利润并非他唯一的动机。"},{"word":"emotion","structure":"e- (out) + mot- (move) + -ion","meaning":"a feeling that moves one outward","meaningCN":"把人向外推动的情绪","example":"The speech stirred strong emotion.","exampleCN":"那场演讲激起了强烈情绪。"},{"word":"remove","structure":"re- (back) + movere (move)","meaning":"to move something back or away","meaningCN":"把某物移开","example":"They removed the old sign.","exampleCN":"他们拆掉了旧招牌。"}],"latinEntries":[{"word":"movere","structure":"movere, movi, motum (verb, second conjugation)","meaning":"to move","meaningCN":"移动"},{"word":"promovere","structure":"pro- + movere","meaning":"to move forward, advance","meaningCN":"向前移；推进"},{"word":"promotio","structure":"noun of action from promotus","meaning":"an advancing","meaningCN":"推进；提升"}],"derivatives":[{"word":"promote","pos":"v.","zh":"推动；晋升；推广"},{"word":"promoter","pos":"n.","zh":"推动者；主办者"},{"word":"promotional","pos":"adj.","zh":"促销的；推广的"},{"word":"promoted","pos":"adj.","zh":"被提升的"},{"word":"promotable","pos":"adj.","zh":"可晋升的"}]}},{"word":"promotional","ipa_uk":"/prəˈməʊʃənl/","ipa_us":"/prəˈməʊʃənl/","definition_zh":"促销的；推广宣传用的；优惠的；宣传性的","definition_en":"relating to an effort that pushes a product, event or brand toward the public","core_image":"一只贴着价签的手把商品塞进顾客掌心，掌心上还印着店名","scene":"店员把印着店名的小样塞进顾客掌心，掌心还留着价签的折痕。The promotional copy cost nothing but carried the logo on every page.","sceneCN":"店员把印着店名的小样塞进顾客掌心，掌心还留着价签的折痕；句中的这个词指「为推广而制作的」（第 2 个义项：用于宣传目的的材料或活动，而非日常售卖用品）。图中可辨识物件：小样、掌心、价签折痕、每页上的标志、柜台。","pos":[{"tag":"adj.","zh":"促销的；推广宣传用的（多作定语）"},{"tag":"adj.","zh":"职位晋升的（较少用）"}],"collocations":[{"phrase":"promotional material","zh":"宣传材料"},{"phrase":"a promotional offer","zh":"优惠促销"},{"phrase":"promotional copy","zh":"赠阅本；宣传用文案"},{"phrase":"promotional event","zh":"推广活动"},{"phrase":"at a promotional price","zh":"以促销价"},{"phrase":"promotional campaign","zh":"推广宣传活动"}],"forms":[{"label":"比较级","form":"more promotional"},{"label":"最高级","form":"most promotional"},{"label":"名词（促销；晋升）","form":"promotion"},{"label":"动词（推动；晋升）","form":"promote"},{"label":"副词（以推广的方式）","form":"promotionally"}],"derivatives":[{"word":"promotion","pos":"n.","zh":"晋升；促销；推广"},{"word":"promote","pos":"v.","zh":"推动；晋升；推广"},{"word":"promoter","pos":"n.","zh":"推动者；主办者"},{"word":"promotionally","pos":"adv.","zh":"以推广的方式"},{"word":"unpromoted","pos":"adj.","zh":"未获晋升的"}],"senses":[{"no":"01","title":"Relating to a sales offer","titleCN":"促销的","definition":"relating to a special offer meant to raise sales quickly","definitionCN":"与旨在快速拉动销量的特殊优惠有关的","example":"The promotional price lasts until Sunday.","exampleCN":"这个促销价持续到周日。","why":"The adjective simply attaches the noun idea of a forward push to whatever it describes.","whyCN":"这个形容词只是把「往前推」这一名词概念贴到它所修饰的东西上。"},{"no":"02","title":"Made for advertising a product or event","titleCN":"推广宣传用的","definition":"made or used for advertising a product, event or brand","definitionCN":"为宣传某产品、活动或品牌而制作或使用的","example":"The promotional copy cost nothing but carried the logo on every page.","exampleCN":"这本赠阅本不花钱，但每页都带着标志。","why":"Here the adjective marks purpose: the object exists in order to push something else into view.","whyCN":"这里这个形容词标的是「用途」：这件东西存在，是为了把别的东西推到人眼前。"},{"no":"03","title":"Offered at a reduced price","titleCN":"促销价的、优惠的","definition":"offered at a lower price for a limited period as part of such an offer","definitionCN":"作为此类活动的一部分，在限定时期内以较低价格提供","example":"Members buy the second ticket at the promotional rate.","exampleCN":"会员可以按促销价买第二张票。","why":"A lower number is the cheapest kind of push: the distance to a decision shrinks.","whyCN":"把数字压低是最便宜的一种「推」：到「决定买」的距离被缩短了。"},{"no":"04","title":"Sounding like an advertisement","titleCN":"宣传腔的（含贬义）","definition":"done mainly to win approval, in a tone that sounds like advertising","definitionCN":"主要为赢得赞许而做，语气听起来像广告","example":"His promotional remarks about the plan convinced nobody.","exampleCN":"他对这个计划那些宣传腔的说法没说服任何人。","why":"When the push is visible in the speech itself, the adjective turns into a criticism.","whyCN":"当「推」的动作在话语里露了出来，这个形容词就变成了批评。"},{"no":"05","title":"Given away free to be talked about","titleCN":"免费赠送以作宣传的","definition":"given away free so that people will try the thing and talk about it","definitionCN":"免费送出，好让人试用并谈论它","example":"Bags of promotional coffee were handed out at the station.","exampleCN":"车站派发了成袋的宣传用咖啡。","why":"A free sample buys a trial; the cost is moved from the buyer to the seller.","whyCN":"免费小样买到一次试用；成本从买家一侧移到了卖家一侧。"},{"no":"06","title":"Relating to a rise in rank","titleCN":"与职位晋升有关的（少见）","definition":"relating to a rise in rank or position, a rarer use","definitionCN":"与职位或级别的提升有关的，较少见的用法","example":"The promotional ladder in this firm is unusually short.","exampleCN":"这家公司的晋升阶梯短得出奇。","why":"The oldest sense of the noun survives in the adjective, though the sales sense now dominates.","whyCN":"名词最古老的那个义项在这个形容词里活了下来，尽管卖货义如今占主导。"},{"no":"07","title":"Belonging to a fixed offer period","titleCN":"促销期内的、限时的","definition":"belonging to a fixed window during which the offer runs","definitionCN":"属于优惠活动的固定时间窗内的","example":"Sales rose sharply in the promotional weeks.","exampleCN":"在促销的那几周里销量猛增。","why":"A push has to stop, or buyers learn to wait; the adjective marks those bounded weeks.","whyCN":"推的动作必须停止，否则买家会学会等待；这个形容词标出的正是那几周有边界的时段。"},{"no":"08","title":"Built to make a brand familiar","titleCN":"品牌推广用的","definition":"designed to build recognition of a brand rather than to sell one item that day","definitionCN":"为建立品牌认知而设计，而不是为了当天卖出某件商品","example":"They rented a promotional stand at the trade fair.","exampleCN":"他们在交易会上租了一个品牌推广展位。","why":"The object pushed here is a name, so the adjective serves recognition rather than an immediate sale.","whyCN":"这里被推的是「一个名字」，所以这个形容词服务的是认知度，而不是当场成交。"}],"etymology":{"intro":{"en":"Promotional is promotion plus the English adjective suffix -al. Its commercial sense is only about two centuries old.","cn":"promotional 是 promotion 加英语形容词后缀 -al。它的商业义只有大约两百年的历史。"},"items":[{"era":"LATIN MOVERE","en":"Movere 'to move' is the base, also behind motion, motive and emotion.","cn":"movere「移动」是词基，也藏在 motion、motive 与 emotion 背后。"},{"era":"LATIN PROMOVERE","en":"Pro- 'forward' plus movere gave promovere 'to move forward, to advance'.","cn":"pro-「向前」加 movere 构成 promovere「向前移、推进」。"},{"era":"LATIN PROMOTIO","en":"The action noun promotio reached English as promotion, first meaning advancement in rank.","cn":"动作名词 promotio 以 promotion 进入英语，最初指职位的提升。"},{"era":"ENGLISH -AL","en":"The suffix -al, from Latin -alis, turns a noun into an adjective meaning 'relating to'.","cn":"后缀 -al 出自拉丁 -alis，把名词变成意为「与……有关的」形容词。"},{"era":"NINETEENTH CENTURY","en":"As sales promotion became a trade term, the adjective promotional was applied to leaflets, prices and events that push goods.","cn":"随着 sales promotion 成为行业术语，形容词 promotional 被用于推动商品的那些传单、价格与活动。"},{"era":"MODERN ENGLISH","en":"The twentieth century extended the adjective to brand building, free samples and any material made for publicity.","cn":"二十世纪把这个形容词扩展到品牌建设、免费小样，以及任何为宣传而制作的材料。"}]},"similar":{"note":{"en":"Group one differs only in ending from words built on the same root; group two marks other kinds of commercial adjective.","cn":"第一组只是词尾不同，词根相同；第二组是其他类型的商业形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"promotion","ipa":"/prəˈməʊʃən/","tag":"noun","definition":"The noun: the event or offer itself. The adjective describes something that serves that event.","definitionCN":"名词：指那件事或那项优惠本身。形容词则描述为这件事服务的东西。"},{"word":"promoted","ipa":"/prəˈməʊtɪd/","tag":"past participle","definition":"The passive form: someone or something that has been raised, not something that serves promotion.","definitionCN":"被动形式：已被提升的人或物，而不是为推广服务的东西。"},{"word":"promoter","ipa":"/prəˈməʊtə/","tag":"person","definition":"The person who pushes a project; it is a noun, so it cannot stand before another noun as a modifier of purpose.","definitionCN":"推动项目的人；是名词，不能像形容词那样放在另一个名词前表用途。"},{"word":"promontory","ipa":"/prəˈmɒntəri/","tag":"different root","definition":"A headland, from Latin mons 'mountain'. Only the opening letters resemble this family.","definitionCN":"海角，出自拉丁 mons「山」。只有开头几个字母与这一族相像。"}]},{"heading":"NEAR MEANING","entries":[{"word":"advertising","ipa":"/ˈædvətaɪzɪŋ/","tag":"medium-based","definition":"Relating to paid notices in media; promotional can also cover discounts, samples and stands that are not notices.","definitionCN":"指媒体上的付费告示；promotional 还可涵盖折扣、小样与展位，这些都不是告示。"},{"word":"marketing","ipa":"/ˈmɑːkɪtɪŋ/","tag":"wider","definition":"Relating to the whole selling strategy, including pricing and distribution as well as promotion.","definitionCN":"指整个销售策略，除推广外还包括定价与渠道。"},{"word":"publicity","ipa":"/pʌbˈlɪsəti/","tag":"attention","definition":"The attention gained; it often comes free, whereas promotional material is deliberately produced and paid for.","definitionCN":"指获得的关注，往往免费；而 promotional 材料是特意制作并付钱的。"},{"word":"complimentary","ipa":"/kəmplɪˈmentəri/","tag":"free, not necessarily promotional","definition":"Given free as a courtesy; a free item is promotional only when it is meant to push sales or a brand.","definitionCN":"出于礼遇免费给出；只有当免费品意在推动销量或品牌时才算 promotional。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real noun stem plus a real adjective suffix.","cn":"正常联想：真实的名词词干加真实的形容词后缀。"},"normal":[{"en":"promotion + -al: the -al says 'relating to', so the word means 'relating to a push'.","cn":"promotion 加 -al：-al 表示「与……有关」，所以整个词意为「与推动有关的」。"},{"en":"Fixed phrases show the purpose: promotional material, a promotional offer, a promotional event.","cn":"固定搭配显示用途：宣传材料、优惠促销、推广活动。"},{"en":"The noun ladder runs promote → promotion → promotional.","cn":"名词阶梯是 promote → promotion → promotional。"},{"en":"The same -al suffix builds national, personal and seasonal from nouns.","cn":"同一个 -al 后缀能把 national、personal、seasonal 从名词造出来。"},{"en":"A free book with a logo on every page is promotional; the same book bought in a shop is not.","cn":"每页都印标志的赠书是 promotional；在店里买到的同一本书则不是。"}],"abstract":[{"en":"Picture a hand pushing a gift into yours; the push is the adjective's whole meaning.","cn":"想象一只手把礼物推进你手里；这一推就是这个形容词的全部意思。"},{"en":"The adjective never describes the seller's effort directly, only the object that carries it.","cn":"这个形容词从不直接描述卖家的努力，只描述承载那份努力的东西。"},{"en":"So promotional always answers one question: what is this object pushing?","cn":"所以 promotional 永远在回答一个问题：这件东西在推什么？"}]},"examples":[{"en":"The publisher sent promotional copies to two hundred schools.","cn":"出版社向两百所学校寄送了赠阅本。"},{"en":"Tickets bought with a promotional code cannot be refunded.","cn":"用促销码购买的票不能退。"},{"en":"Her speech sounded promotional rather than analytical.","cn":"她的话听起来像宣传，而不像分析。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「普若-摩申-诺」——普若把货往前一摩，再挂个「诺」字牌，就成了宣传用的 → promotional 促销的","word":"promotional"},"root":"promotion + -al（形容词后缀）；promotion 出自拉丁 promovere「向前推进」= pro- + movere「移动」。","sensesIntro":{"en":"Eight senses apply one adjective to different carriers of a push: a price, a leaflet, a sample, a stand, a stretch of weeks or a tone of voice.","cn":"八个义项把同一个形容词贴到不同的「推动载体」上：一个价格、一张传单、一份小样、一个展位、一段周数，或者一种语气。"},"semanticMap":{"core":{"en":"CORE IMAGE: a gift pushed into an open hand, with the giver's name printed on it.","cn":"核心意象：一份礼物被推进张开的手，礼物上印着给出者的名字。"},"chain":["PUSH FORWARD","SELL","CUT PRICE","GIVE AWAY","ADVERTISE","RAISE RANK"],"branches":[{"senses":"01 · 03","en":"PRICE PUSH: a low price is the cheapest way to shorten the distance to a decision.","cn":"价格推动：低价是缩短「到决定」距离的最便宜办法。"},{"senses":"02 · 08","en":"PURPOSE: material made to advertise a thing differs from material made to make a name familiar.","cn":"用途：为宣传某物而做的材料，与为让一个名字被记住而做的材料，并不相同。"},{"senses":"04","en":"VISIBLE PUSH: when the effort shows through the words, the adjective becomes criticism.","cn":"露出的推：当努力从话语里透出来，这个形容词就成了批评。"},{"senses":"05","en":"FREE SAMPLE: the seller pays so the buyer will try.","cn":"免费小样：卖家出钱，好让买家试一试。"},{"senses":"06 · 07","en":"OLD LADDER AND SHORT WINDOW: a rank step survives as a rare use, while a bounded offer period is the modern default.","cn":"旧梯子与短窗口：职级上的那一阶作为罕见用法留存，而有边界的优惠期则是现代的常态。"}]},"affixes":{"intro":{"en":"The word is a noun stem plus the adjective suffix -al; both the stem and the suffix are productive.","cn":"这个词是名词词干加形容词后缀 -al；词干与后缀都还能产。"},"latinIntro":{"en":"The stem goes back to Latin promovere 'to move forward', built on movere 'to move'.","cn":"词干上溯到拉丁 promovere「向前推进」，由 movere「移动」构成。"},"items":[{"word":"-al","structure":"-al (adjective suffix, Latin -alis)","meaning":"relating to","meaningCN":"与……有关的","example":"The suffix makes an adjective from a noun.","exampleCN":"这个后缀把名词变成形容词。"},{"word":"pro-","structure":"pro- (Latin prefix, 'forward')","meaning":"forward","meaningCN":"向前","example":"The prefix marks direction.","exampleCN":"这个前缀标示方向。"},{"word":"mov / mot","structure":"movere, motus (Latin root)","meaning":"to move","meaningCN":"移动","example":"Motive and motion carry it.","exampleCN":"motive 与 motion 都带着它。"},{"word":"promote","structure":"promote (base verb)","meaning":"to push forward","meaningCN":"向前推","example":"They promote the new line.","exampleCN":"他们推广新系列。"},{"word":"promotion","structure":"promote + -ion","meaning":"a forward push","meaningCN":"一次向前推","example":"The promotion ends on Sunday.","exampleCN":"促销周日结束。"},{"word":"promotional","structure":"promotion + -al","meaning":"serving a forward push","meaningCN":"服务于推动的","example":"They handed out promotional bags.","exampleCN":"他们派发了宣传袋。"},{"word":"promoter","structure":"promote + -er","meaning":"one who pushes","meaningCN":"推动者","example":"The promoter took the risk.","exampleCN":"主办者承担了风险。"},{"word":"promotionally","structure":"promotional + -ly","meaning":"in a promotional way","meaningCN":"以推广的方式","example":"The book was promotionally priced.","exampleCN":"这本书定的是推广价。"},{"word":"motion","structure":"mot- + -ion","meaning":"movement","meaningCN":"运动","example":"The motion of the ship made her ill.","exampleCN":"船的晃动让她难受。"}],"latinEntries":[{"word":"movere","structure":"movere, movi, motum (verb)","meaning":"to move","meaningCN":"移动"},{"word":"promovere","structure":"pro- + movere","meaning":"to move forward","meaningCN":"向前推进"},{"word":"promotio","structure":"noun of action from promotus","meaning":"a moving forward","meaningCN":"向前移动"}],"derivatives":[{"word":"promotion","pos":"n.","zh":"晋升；促销；推广"},{"word":"promote","pos":"v.","zh":"推动；晋升；推广"},{"word":"promoter","pos":"n.","zh":"推动者；主办者"},{"word":"promotionally","pos":"adv.","zh":"以推广的方式"},{"word":"unpromoted","pos":"adj.","zh":"未获晋升的"}]}},{"word":"campaign","ipa_uk":"/kæmˈpeɪn/","ipa_us":"/kæmˈpeɪn/","definition_zh":"战役；竞选活动；宣传活动；运动","definition_en":"an organized series of actions over a period, aimed at one result, from battles to votes to sales","core_image":"一支队伍在开阔的原野上扎营，按同一份计划连续作战，直到目标达成","scene":"海报在各个街口铺开，志愿者按名单逐户敲门，同一天里所有声音说同一句话。The campaign knocked on ten thousand doors before the vote.","sceneCN":"海报在各街口铺开，志愿者按名单逐户敲门，同一天里所有声音都说同一句话；句中的这个词指「为赢得选票而有组织地展开的一连串行动」（第 2 个义项：候选人或有组织拉票的整套活动）。图中可辨识物件：街口海报、敲门的志愿者、名单、同一句口号、投票箱。","pos":[{"tag":"n.","zh":"战役；运动；竞选活动；宣传活动（可数）"},{"tag":"vi.","zh":"参加竞选；开展运动（campaign for/against）"}],"collocations":[{"phrase":"launch a campaign","zh":"发起一场运动"},{"phrase":"an election campaign","zh":"竞选活动"},{"phrase":"an advertising campaign","zh":"广告宣传活动"},{"phrase":"a campaign against smoking","zh":"反吸烟运动"},{"phrase":"on the campaign trail","zh":"在巡回拉票途中"},{"phrase":"a campaign manager","zh":"竞选经理"}],"forms":[{"label":"复数","form":"campaigns"},{"label":"三单（he/she/it）","form":"campaigns"},{"label":"过去式","form":"campaigned"},{"label":"过去分词","form":"campaigned"},{"label":"现在分词","form":"campaigning"},{"label":"名词（运动参与者）","form":"campaigner"}],"derivatives":[{"word":"campaigner","pos":"n.","zh":"运动参与者；倡导者"},{"word":"campaigning","pos":"n.","zh":"开展运动"},{"word":"camp","pos":"n.","zh":"营地（同出野外驻扎之意）"},{"word":"campus","pos":"n.","zh":"校园（同出「开阔场地」之意）"},{"word":"champagne","pos":"n.","zh":"香槟（同出「开阔乡野」地名）"}],"senses":[{"no":"01","title":"A series of military operations","titleCN":"战役","definition":"a series of military operations planned to achieve one aim in a theatre of war","definitionCN":"为在某个战区达成一个目标而计划的一连串军事行动","example":"The general opened the spring campaign with a river crossing.","exampleCN":"将军以一次渡河开启了春季战役。","why":"The word began in the open country: armies left their camps and fought through one season in the field. See field and camp for the same picture.","whyCN":"这个词起于开阔的原野：军队拔营，在一个季节里于野外连续作战。field 与 camp 共享同一幅画面。"},{"no":"02","title":"An organized effort to win votes","titleCN":"竞选活动","definition":"the organized effort by a candidate or party to win support and votes","definitionCN":"候选人或有组织地为赢得支持与选票而展开的整套努力","example":"The campaign knocked on ten thousand doors before the vote.","exampleCN":"投票前这场竞选活动敲了一万户人家的门。","why":"An election is a war fought by schedule, so the military word moved over with its plan, its timetable and its target.","whyCN":"选举是一场按日程打的仗，于是这个军事词连同它的计划、时间表与目标一起搬了过来。"},{"no":"03","title":"A planned set of advertisements","titleCN":"广告宣传活动","definition":"a planned set of advertisements carrying one message over one period","definitionCN":"在一段时期内传递同一信息的成套广告","example":"The launch campaign ran on buses and radio for six weeks.","exampleCN":"上市宣传在公交与电台上持续了六周。","why":"Advertising borrowed the word because a launch also needs coordinated timing, repeated blows and one target.","whyCN":"广告业借走这个词，是因为产品上市同样需要协调的时间、反复的出击和一个目标。"},{"no":"04","title":"A public effort to change behaviour","titleCN":"公益倡导运动","definition":"an organized public effort to change behaviour or policy","definitionCN":"为改变行为或政策而组织的公众努力","example":"The road-safety campaign cut accidents by a fifth.","exampleCN":"这场道路安全运动把事故减少了五分之一。","why":"The target is now a habit rather than a hill; the campaign still advances step by step.","whyCN":"目标现在是一个习惯而不是一座山头，运动仍然一步一步推进。"},{"no":"05","title":"Any connected series of actions","titleCN":"有计划的一连串行动","definition":"any connected series of actions aimed at one result","definitionCN":"任何为达成一个结果而连成一串的行动","example":"The campaign of letters finally won the case.","exampleCN":"那场接连写信的行动最终赢下了这个案子。","why":"Strip away the army and the ballot and what remains is the shape: many acts, one aim, a fixed period.","whyCN":"把军队和选票都拿掉，剩下的就是那个形状：许多动作、一个目标、一段固定时期。"},{"no":"06","title":"A public health drive","titleCN":"疾病防治运动","definition":"an organized public health effort against a disease","definitionCN":"为对抗某种疾病而组织的公共卫生努力","example":"The vaccination campaign reached every village in the district.","exampleCN":"这场疫苗接种运动覆盖了区内每个村子。","why":"Here the enemy is a disease, and the campaign is a coordinated advance against it.","whyCN":"这里敌人是疾病，运动就是针对它的一次协同推进。"},{"no":"07","title":"The organization behind the effort","titleCN":"竞选团队；运动组织","definition":"the staff, volunteers and offices that carry out the effort","definitionCN":"执行这场努力的职员、志愿者与办公机构","example":"The campaign moved its headquarters downtown.","exampleCN":"竞选团队把总部搬到了市中心。","why":"Metonymy: the plan's name is given to the people who execute the plan.","whyCN":"这是借代：计划的名字被给了执行这项计划的那群人。"},{"no":"08","title":"A long determined struggle","titleCN":"长期抗争","definition":"a long, determined struggle against a problem or an injustice","definitionCN":"针对某个问题或不公的长期而坚决的抗争","example":"The campaign against illiteracy lasted thirty years.","exampleCN":"扫盲运动持续了三十年。","why":"When the aim cannot be reached in one season, the campaign becomes a standing war.","whyCN":"当一个目标无法在一个季节里达成，运动就变成一场持久的战争。"}],"etymology":{"intro":{"en":"Campaign is a field word before it is a war word: its Latin base is campus 'field', which also gives camp and campus.","cn":"campaign 先是一个「田野」的词，然后才是「战争」的词：它的拉丁词基是 campus「田野」，也给了 camp 与 campus。"},"items":[{"era":"LATIN CAMPUS","en":"Campus meant 'field, open land, plain'. English borrowed it directly as campus, the open ground of a school.","cn":"campus 意为「田野、开阔地、平原」。英语直接借用为 campus，指学校那片开阔场地。"},{"era":"LATE LATIN CAMPANIA","en":"Campania named open country, from campus. Italian campagna and Old French campagne both mean 'countryside'.","cn":"晚期拉丁 campania 指开阔的乡野，由 campus 而来。意大利语 campagna 与古法语 campagne 都表示「乡间」。"},{"era":"MILITARY SENSE","en":"From the sixteenth century a campaign was the army's operations in the field during one season, as opposed to staying in winter quarters.","cn":"从十六世纪起，campaign 指军队在一个季节内于野外的作战，与留在冬营相对。"},{"era":"POLITICAL SENSE","en":"American usage of the nineteenth century applied the word to the organized drive for votes, complete with a timetable and a target.","cn":"十九世纪的美国用法把这个词用于有组织地争取选票的活动，同样带时间表与目标。"},{"era":"COMMERCIAL SENSE","en":"The twentieth century added the advertising campaign, in which repeated messages replace repeated battles.","cn":"二十世纪又添上了广告宣传活动——在这里，反复的信息取代了反复的战斗。"},{"era":"MODERN ENGLISH","en":"The word now covers any coordinated push, from a health drive to a letter-writing effort, and the verb campaign keeps the military frame.","cn":"这个词如今涵盖任何协同推进，从卫生运动到写信行动；动词 campaign 仍保留军事框架。"}]},"similar":{"note":{"en":"Group one is built on the same field root; group two is close in meaning but narrower or wider.","cn":"第一组建立在同一个「田野」词根上；第二组意思接近，但更窄或更宽。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"camp","ipa":"/kæmp/","tag":"same root","definition":"A place where an army or travellers stay in tents or huts; the root is the same field, but there is no plan or target.","definitionCN":"军队或旅人搭帐篷居住的地方；词根是同一片田野，但没有计划与目标。"},{"word":"campus","ipa":"/ˈkæmpəs/","tag":"same root","definition":"The grounds of a school or university, literally the open field; it is a place, not an effort.","definitionCN":"学校或大学的地面，字面就是开阔的田野；它是地点，不是一项努力。"},{"word":"campaigner","ipa":"/kæmˈpeɪnə/","tag":"person","definition":"A person who takes part in a campaign; the -er suffix adds a doer to the noun.","definitionCN":"参与某项运动的人；-er 后缀给名词添了一个施事者。"},{"word":"champagne","ipa":"/ʃæmˈpeɪn/","tag":"same field word, different path","definition":"The sparkling wine is named after a region of open country; it shares the field root but has nothing to do with battles.","definitionCN":"这种起泡酒得名于一片开阔乡野的产区；它共享「田野」词根，但与战斗毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"promotion","ipa":"/prəˈməʊʃən/","tag":"single push","definition":"One offer or one act of publicity; a campaign is the coordinated series that may contain many promotions.","definitionCN":"单次优惠或单次宣传；campaign 是可能包含许多这类动作的协同系列。"},{"word":"drive","ipa":"/draɪv/","tag":"fundraising or enrolment","definition":"An organized effort to raise money or recruits, often shorter and more focused than a campaign.","definitionCN":"为筹款或招募而组织的努力，通常比 campaign 更短、更集中。"},{"word":"movement","ipa":"/ˈmuːvmənt/","tag":"longer and social","definition":"A broad, long-lasting grouping of people with a shared aim; it outlives any single campaign.","definitionCN":"有共同目标的广泛而持久的人群联合；它比任何单场运动都活得更久。"},{"word":"operation","ipa":"/ˌɒpəˈreɪʃn/","tag":"single action","definition":"One planned military or medical action; a campaign is the series that contains several operations.","definitionCN":"单次计划好的军事或医疗行动；campaign 是包含若干次行动的那个系列。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real field root and its real English relatives.","cn":"正常联想：真实的「田野」词根与它真实的英语亲属。"},"normal":[{"en":"campus 'field' → campagne 'countryside' → campaign: armies fight in the open country.","cn":"campus「田野」→ campagne「乡间」→ campaign：军队在开阔乡野作战。"},{"en":"Camp, campus and campaign are three relatives of one field word.","cn":"camp、campus 与 campaign 是同一个「田野」词的三个亲属。"},{"en":"Fixed phrases mark the type: an election campaign, an advertising campaign, a campaign against smoking.","cn":"固定搭配标出类型：竞选活动、广告宣传活动、反吸烟运动。"},{"en":"The verb keeps the military frame: to campaign for a seat is to take the field for it.","cn":"动词保留军事框架：为某个席位 campaign，就是为它走上战场。"},{"en":"The word carries a schedule: a campaign has a start, a target and an end.","cn":"这个词自带日程：一场运动有开始、有目标、有结束。"}],"abstract":[{"en":"Picture a tent pitched in a wide field, and the same tent moved forward each morning.","cn":"想象一顶帐篷扎在开阔原野上，每天早上又往前挪一段。"},{"en":"Every sense keeps three things: one aim, many repeated acts, a fixed stretch of time.","cn":"每个义项都保留三样东西：一个目标、许多重复的动作、一段固定时间。"},{"en":"Change the enemy from an army to a rival, a disease or a habit, and the shape does not change.","cn":"把敌人从军队换成对手、疾病或习惯，那个形状都不变。"}]},"examples":[{"en":"The party spent more on its campaign than on its entire policy office.","cn":"这个政党在竞选上的花费超过了它整个政策部门。"},{"en":"A campaign of posters and radio spots brought the new bank six thousand customers.","cn":"一场海报加电台广告的宣传为新银行带来六千名客户。"},{"en":"She has campaigned for cleaner air since she was a student.","cn":"她从学生时代起就为更清洁的空气奔走。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「坎-佩恩」——队伍在坎上扎营，佩着恩令连打一季 → campaign 战役、竞选活动","word":"campaign"},"root":"拉丁 campus「田野、开阔地」→ 晚期拉丁 campania「乡野」→ 法语 campagne；原指军队在野外一季的作战。","sensesIntro":{"en":"Eight senses share one shape: a coordinated series of repeated acts, aimed at one result, run over a fixed period, whether the enemy is an army, a rival, a disease or a habit.","cn":"八个义项共享同一个形状：在一段固定时期内，为达成一个结果而协同展开的一连串重复行动；敌人无论是军队、对手、疾病还是习惯，形状不变。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tent in open country, moved forward each morning until the aim is taken.","cn":"核心意象：开阔原野上的一顶帐篷，每天早上往前挪一段，直到拿下目标。"},"chain":["OPEN FIELD","ARMY TAKES THE FIELD","SERIES OF BATTLES","ORGANIZED PUSH","PUBLIC CAUSE","LONG STRUGGLE"],"branches":[{"senses":"01","en":"THE ORIGINAL: one season of fighting in the field.","cn":"原初义：在野外打一个季节的仗。"},{"senses":"02 · 07","en":"VOTES: a scheduled war for seats, and the staff who fight it take the plan's name.","cn":"选票：为席位按日程打的仗，执行的人则借用了计划的名字。"},{"senses":"03 · 05","en":"MESSAGES AND LETTERS: repeated ads or repeated letters keep the same timetable and target.","cn":"信息与信件：反复投放的广告或反复寄出的信，保留同样的时间表与目标。"},{"senses":"04 · 08","en":"CAUSES: a habit or an injustice can be fought for one season or for thirty years.","cn":"事业：一个习惯或一种不公，可以打一季，也可以打三十年。"},{"senses":"06","en":"DISEASE: the enemy is a pathogen, and the advance is vaccination.","cn":"疾病：敌人是病原体，推进的方式是接种。"}]},"affixes":{"intro":{"en":"Campaign is built on a Latin word for field, and the same base gives several English place words.","cn":"campaign 建立在拉丁语表示「田野」的词上，同一个词基还给了英语好几个地点词。"},"latinIntro":{"en":"Campus 'field' is the Latin base; Late Latin campania 'open country' passed through Italian and French into English.","cn":"拉丁词基是 campus「田野」；晚期拉丁 campania「开阔乡野」经意大利语与法语进入英语。"},"items":[{"word":"camp","structure":"camp (English, from Latin campus via French)","meaning":"a field where troops stay","meaningCN":"部队驻扎的场地","example":"The camp stood beside the river.","exampleCN":"营地立在河边。"},{"word":"campus","structure":"campus (Latin, 'field')","meaning":"the open ground of a school","meaningCN":"学校的开阔场地","example":"The library sits at the centre of the campus.","exampleCN":"图书馆位于校园中心。"},{"word":"campaign","structure":"campagne (French, from Italian campagna)","meaning":"a season of operations in the field","meaningCN":"在野外一季的作战","example":"The campaign lasted one summer.","exampleCN":"这场战役持续了一个夏天。"},{"word":"campaigner","structure":"campaign + -er","meaning":"one who takes part in a campaign","meaningCN":"参与运动的人","example":"Campaigners gathered outside the hall.","exampleCN":"运动参与者聚集在会堂外。"},{"word":"campaigning","structure":"campaign + -ing","meaning":"the activity of running a campaign","meaningCN":"开展运动的活动","example":"Campaigning continued through the winter.","exampleCN":"运动在整个冬天持续进行。"},{"word":"champagne","structure":"Champagne (region name from campania)","meaning":"sparkling wine from the open-country region","meaningCN":"产自那片开阔乡野地区的起泡酒","example":"They opened a bottle of champagne.","exampleCN":"他们开了一瓶香槟。"},{"word":"campestral","structure":"campester (Latin, 'of fields') + -al","meaning":"relating to open fields","meaningCN":"与开阔田野有关的","example":"The campestral landscape stretched for miles.","exampleCN":"田野风光绵延数英里。"},{"word":"decamp","structure":"de- (away) + camp","meaning":"to leave a camp secretly","meaningCN":"秘密拔营离开","example":"The travellers decamped before dawn.","exampleCN":"旅人在天亮前悄悄拔营。"}],"latinEntries":[{"word":"campus","structure":"campus, campi (noun, second declension)","meaning":"field, open plain","meaningCN":"田野；开阔平原"},{"word":"campania","structure":"Late Latin campania","meaning":"open country","meaningCN":"开阔的乡野"},{"word":"campester","structure":"campester (adjective from campus)","meaning":"of the fields","meaningCN":"田野的"}],"derivatives":[{"word":"campaigner","pos":"n.","zh":"运动参与者；倡导者"},{"word":"campaigning","pos":"n.","zh":"开展运动"},{"word":"camp","pos":"n.","zh":"营地"},{"word":"campus","pos":"n.","zh":"校园"},{"word":"decamp","pos":"v.","zh":"秘密拔营；突然离开"}]}},{"word":"brand","ipa_uk":"/brænd/","ipa_us":"/brænd/","definition_zh":"品牌；商标；烙印；火把；类型","definition_en":"a name or sign that marks goods as belonging to one maker, and the reputation that name carries","core_image":"烧红的铁印按在皮张上，留下一个永不磨掉的记号，谁的东西一看就知","scene":"牧场主把烧红的铁印按在皮张上，留下一个谁都认得的记号。Every brand in the shop window began as a mark burned into a crate.","sceneCN":"牧场主把烧红的铁印按在皮张上，留下一个谁都认得的记号；句中的这个词指「标明货物属于某个制造者的名称或标识」（第 1 个义项：用来区分出品方的商标品牌）。图中可辨识物件：烧红的铁印、皮张、烙痕、木箱、橱窗价签。","pos":[{"tag":"n.","zh":"品牌；商标（可数）"},{"tag":"n.","zh":"烙印；火印（牲畜或货物上的标记）"},{"tag":"n.","zh":"火把；燃烧的木块（古义）"},{"tag":"vt.","zh":"给……打烙印；给……贴上标签"}],"collocations":[{"phrase":"brand loyalty","zh":"品牌忠诚度"},{"phrase":"brand awareness","zh":"品牌知名度"},{"phrase":"a leading brand","zh":"领先品牌"},{"phrase":"own-brand goods","zh":"自有品牌商品"},{"phrase":"build a brand","zh":"打造品牌"},{"phrase":"brand identity","zh":"品牌识别"}],"forms":[{"label":"复数","form":"brands"},{"label":"三单（he/she/it）","form":"brands"},{"label":"过去式","form":"branded"},{"label":"过去分词","form":"branded"},{"label":"现在分词","form":"branding"},{"label":"名词（品牌塑造；烙印）","form":"branding"}],"derivatives":[{"word":"branding","pos":"n.","zh":"品牌塑造；打烙印"},{"word":"branded","pos":"adj.","zh":"有品牌的；带烙印的"},{"word":"unbranded","pos":"adj.","zh":"无品牌的"},{"word":"rebrand","pos":"v.","zh":"重塑品牌"},{"word":"brander","pos":"n.","zh":"打烙印的人或工具"},{"word":"firebrand","pos":"n.","zh":"火把；煽动者"}],"senses":[{"no":"01","title":"A name or sign that identifies a maker","titleCN":"商标品牌","definition":"a name, sign or design that identifies a maker's goods and sets them apart from rivals","definitionCN":"标示某制造者的货物、并把它与竞争对手区分开来的名称、标识或图案","example":"Every brand in the shop window began as a mark burned into a crate.","exampleCN":"橱窗里的每个品牌，最初都是木箱上烙下的一个记号。","why":"The commercial brand is a burned mark moved onto packaging: one sign says who made this and who did not.","whyCN":"商业品牌就是把烙痕移到包装上：一个记号说明这是谁做的、那不是谁做的。"},{"no":"02","title":"The reputation a name carries","titleCN":"品牌声誉与形象","definition":"the image, trust and expectations that a name carries in buyers' minds","definitionCN":"某个名字在买家心里携带的形象、信任与预期","example":"The brand survived the recall because customers trusted the name.","exampleCN":"因为顾客信任这个名字，这个品牌挺过了召回事件。","why":"A mark on goods became a mark in memory: the sign now lives in the buyer's head, not on the crate.","whyCN":"货物上的记号变成了记忆里的记号：这个标识现在活在买家脑中，而不在木箱上。"},{"no":"03","title":"A mark burned with a hot iron","titleCN":"烙印、火印","definition":"a mark burned onto an animal's hide or a crate with a hot iron to show ownership","definitionCN":"用烧红的铁器烙在牲畜皮张或木箱上、表示所有权的记号","example":"The rancher's brand was a circle with two bars.","exampleCN":"那位牧场主的烙印是一个带两道横杠的圆。","why":"This is the literal origin, and it explains the whole family: the mark is permanent and it names an owner.","whyCN":"这是字面的本义，也解释了整个词族：烙痕不可磨灭，而且它点名了一个所有者。"},{"no":"04","title":"A burning piece of wood","titleCN":"火把；燃烧的木块（古义）","definition":"a piece of burning wood used for light, the oldest recorded sense","definitionCN":"用于照明的燃烧木块，这是有记录的最古老义项","example":"In old poetry a brand was carried through the dark streets.","exampleCN":"在古老的诗里，人们举着火把穿过黑暗的街道。","why":"Fire is the oldest meaning; the mark is called a brand because it is made with fire.","whyCN":"火是最古老的意思；那个记号之所以叫 brand，正因为它是由火做出来的。"},{"no":"05","title":"A particular kind or type","titleCN":"（某一种）类型","definition":"a particular kind of something, as in a new brand of humour","definitionCN":"某事物的某一种，如一种新的幽默方式","example":"He has a brand of humour that nobody else can copy.","exampleCN":"他有一种别人学不来的幽默。","why":"Once a mark separates one maker's goods, the mark itself comes to name a distinct kind.","whyCN":"一旦记号把某个制造者的货物区分出来，这个记号本身就开始命名一个独特的种类。"},{"no":"06","title":"A mark of shame","titleCN":"污名、耻辱的印记","definition":"a mark of disgrace attached to a person or a group","definitionCN":"附着在某人或某群体身上的耻辱标记","example":"The brand of cowardice followed him for years.","exampleCN":"怯懦的污名跟了他许多年。","why":"A burned mark on a criminal was meant to be seen and remembered, and that public visibility became stigma.","whyCN":"烙在罪犯身上的记号本就是要被看见、被记住的，这种公开可见性就变成了污名。"},{"no":"07","title":"The goods sold under one name","titleCN":"同一品牌下的商品","definition":"the products sold under one name, considered as a line","definitionCN":"以同一个名字出售的系列产品","example":"The chain now sells only its own brand.","exampleCN":"这家连锁店现在只卖自己的品牌。","why":"Metonymy again: the name that marks a line of goods comes to stand for the goods themselves.","whyCN":"这又是借代：标示一系列货物的名字，最后代指这些货物本身。"},{"no":"08","title":"A producer's own label","titleCN":"制造商品牌（与零售自有品牌相对）","definition":"a producer's own name on goods, as opposed to a retailer's own label","definitionCN":"商品上标注的制造者自己的名字，与零售商的自有标签相对","example":"National brands cost more than the store's own label.","exampleCN":"全国性品牌比商店自有品牌贵。","why":"The distinction is about who signs the mark: the factory that made it, or the shop that sells it.","whyCN":"区别在于谁在记号上署名：是做它的工厂，还是卖它的商店。"}],"etymology":{"intro":{"en":"Brand is a Germanic word for fire and burning wood. Its commercial sense is a modern extension of the ownership mark.","cn":"brand 是一个日耳曼语的「火与燃烧的木块」词。它的商业义是「所有权记号」这个用法的现代延伸。"},"items":[{"era":"OLD ENGLISH BRAND","en":"Old English brand meant 'fire, flame' and 'a burning piece of wood, a torch'. The same word named the fire and the thing that carries it.","cn":"古英语 brand 指「火、火焰」以及「燃烧的木块、火把」。同一个词既命名火，也命名载火之物。"},{"era":"PROTO-GERMANIC *BRANDAZ","en":"The recorded ancestor is *brandaz 'a burning, a firebrand', related to the verb *brinnan 'to burn'. German Brand and Dutch brand continue it.","cn":"有记录的祖形是 *brandaz「燃烧物、火把」，与动词 *brinnan「燃烧」相关。德语 Brand 与荷兰语 brand 都是它的延续。"},{"era":"DEEPER ORIGIN","en":"It is generally considered related to a reconstructed Proto-Indo-European root for 'to heat, to burn'. The reconstruction is accepted in standard references but the exact path is not demonstrated.","cn":"一般认为它与一个重构的原始印欧语「加热、烧」词根相关。通行词源资料接受这条线索，但确切路径未被证明。"},{"era":"MEDIEVAL MARKING","en":"By the medieval period the word named the mark burned on livestock and, in some places, on criminals. The mark was permanent, public and it named an owner.","cn":"到中世纪，这个词指烙在牲畜身上的记号，有些地方也烙在罪犯身上。这个记号永久、公开，而且点名了所有者。"},{"era":"SEVENTEENTH TO NINETEENTH CENTURIES","en":"The mark moved from hides to crates and barrels, then to manufactured goods, and the word came to mean a maker's identifying sign.","cn":"这个记号从皮张移到木箱与木桶，再移到制成品，词义随之变为「制造者的识别标记」。"},{"era":"MODERN ENGLISH","en":"The twentieth century added the reputation sense and the whole industry of brand building; advertising made a name itself into a saleable asset.","cn":"二十世纪添上了「声誉」义与整套品牌塑造行业；广告让一个名字本身成了可出售的资产。"}]},"similar":{"note":{"en":"Group one is built on the same fire word or looks very close; group two names neighbouring commercial ideas.","cn":"第一组建立在同一个「火」的词上，或外形极近；第二组是相邻的商业概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"branding","ipa":"/ˈbrændɪŋ/","tag":"activity","definition":"The work of creating a brand, or the act of burning a mark; it is the -ing noun of the same verb.","definitionCN":"塑造品牌的工作，或打烙印的动作；它是同一个动词的 -ing 名词。"},{"word":"branded","ipa":"/ˈbrændɪd/","tag":"adjective","definition":"Carrying a brand or having been burned with a mark; the participle describes goods, not the name itself.","definitionCN":"带有品牌或已被烙上记号的；这个分词描述货物，而不是名字本身。"},{"word":"brant","ipa":"/brænt/","tag":"different word","definition":"A northern goose, or a steep bank; it looks like brand minus a letter but has no fire in it.","definitionCN":"一种北方鹅，或陡岸；看起来像少了字母的 brand，里面却没有火。"},{"word":"braid","ipa":"/breɪd/","tag":"near spelling","definition":"To weave hair or cords together; the vowel is different and the meaning has nothing to do with marks.","definitionCN":"把头发或绳索编在一起；元音不同，意思与记号无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"trademark","ipa":"/ˈtreɪdmɑːk/","tag":"legal sign","definition":"The registered legal sign a firm owns; a brand is the wider commercial identity built around such a sign.","definitionCN":"企业拥有的注册法律标识；brand 是围绕这个标识建立起来的更宽的商业身份。"},{"word":"label","ipa":"/ˈleɪbl/","tag":"attached tag","definition":"A tag or printed name attached to an item; it can be changed, while a brand lives on the product's identity.","definitionCN":"附在物品上的标签或印名，可以更换；而 brand 活在产品身份里。"},{"word":"logo","ipa":"/ˈləʊɡəʊ/","tag":"visual mark only","definition":"The graphic symbol of a brand; it is only one visible piece of what the brand means.","definitionCN":"品牌的图形符号；它只是品牌含义中可见的一块。"},{"word":"make","ipa":"/meɪk/","tag":"maker's name","definition":"The producer's name as printed on goods, especially in older trade usage; it names the maker, not the reputation.","definitionCN":"印在货物上的生产者名字，尤用于较早的行业语；它点名制造者，而不含声誉。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Germanic relatives and real commercial compounds.","cn":"正常联想：真实的日耳曼语亲属与真实的商业复合词。"},"normal":[{"en":"Fire first, mark second, name third: a brand is a mark made by burning.","cn":"先是火，再是记号，最后是名字：brand 就是用火烧出来的记号。"},{"en":"German Brand and Dutch brand are the same word in the neighbours' languages.","cn":"德语 Brand 与荷兰语 brand 就是邻语言里的同一个词。"},{"en":"Fixed phrases show the trade: brand loyalty, brand awareness, a leading brand.","cn":"固定搭配显示行业用法：品牌忠诚度、品牌知名度、领先品牌。"},{"en":"A firebrand is still a burning stick, and also a person who stirs people up.","cn":"firebrand 至今既指燃烧的木棒，也指煽动人心的人。"},{"en":"The verb and noun pair is regular: to brand goods, to carry a brand.","cn":"动词与名词配对很规整：给货物打品牌，带着一个品牌。"}],"abstract":[{"en":"Picture a red iron ring pressed on a crate: the mark outlives the crate.","cn":"想象一枚烧红的铁环按在木箱上：记号比木箱活得久。"},{"en":"The mark answers two questions at once: whose is this, and whose is it not.","cn":"这个记号同时回答两个问题：这是谁的，以及这不是谁的。"},{"en":"Modern branding only moved the iron from the crate to the buyer's memory.","cn":"现代的品牌塑造，只是把那块铁从木箱移到了买家的记忆里。"}]},"examples":[{"en":"The company's brand is recognized by nine out of ten shoppers.","cn":"十个购物者里有九个认得出这家公司的品牌。"},{"en":"The calves are branded in spring and counted in autumn.","cn":"牛犊在春天打烙印，秋天点数。"},{"en":"He has a brand of dry humour that surprises new colleagues.","cn":"他有一种冷面幽默，总让新同事意外。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「布兰得」——布上烙个疤（兰得），谁都认得这是谁的货 → brand 品牌、烙印","word":"brand"},"root":"古英语 brand「火、火焰；燃烧的木块」，与动词「燃烧」同族；德语 Brand、荷兰语 brand 同源。更深词根为重构形式，属一般认为的关联。","sensesIntro":{"en":"Eight senses run from fire to ownership to name to reputation: a burning stick, the mark it makes, the owner it names, the sign on goods, the kind it distinguishes, the shame it can inflict, the goods it covers and the maker behind it.","cn":"八个义项从火一路走到所有权、名字与声誉：燃烧的木棒、它留下的记号、记号点名的所有者、货物上的标识、它区分的种类、它能造成的耻辱、它覆盖的商品，以及它背后的制造者。"},"semanticMap":{"core":{"en":"CORE IMAGE: fire leaves a permanent mark that answers 'whose is this'.","cn":"核心意象：火留下一个永久的记号，回答「这是谁的」。"},"chain":["BURNING WOOD","FIRE MARK","OWNER'S MARK","NAME AND SIGN","REPUTATION","PRODUCT LINE"],"branches":[{"senses":"01 · 08","en":"WHO SIGNS: the producer's name on goods versus the retailer's own label is the same question asked of different signers.","cn":"谁署名：货物上的制造者名字与零售商自有标签，是向不同署名者问的同一个问题。"},{"senses":"02","en":"MARK IN MEMORY: the sign leaves the crate and settles in the buyer's expectations.","cn":"记忆中的记号：标识离开木箱，落进买家的预期里。"},{"senses":"03 · 06","en":"VISIBLE MARK: a permanent public mark can prove ownership or inflict shame.","cn":"可见的记号：永久公开的记号既能证明所有权，也能施加耻辱。"},{"senses":"04","en":"FIRE ITSELF: the oldest sense is the burning stick, before it marks anything.","cn":"火本身：最古老的意思就是那根燃烧的木棒，在它标记任何东西之前。"},{"senses":"05 · 07","en":"KIND AND GOODS: a mark that separates one maker comes to name a kind, then the goods under that name.","cn":"种类与货物：区分制造者的记号先命名一个种类，再代指那个名字下的货物。"}]},"affixes":{"intro":{"en":"Brand is a short Germanic root that builds compounds and derivatives freely in English.","cn":"brand 是一个短小的日耳曼词根，在英语里能自由构成复合词与派生词。"},"latinIntro":{"en":"There is no Latin cognate of this Germanic root; Latin marks ownership with nota or stigma, which are different words and not relatives. The nearest relatives are Germanic: German Brand, Dutch brand, Swedish brand.","cn":"这个日耳曼词根在拉丁语里没有同源词；拉丁语用 nota 或 stigma 表示标记，那是另外的词，并非亲属。最近的亲属是日耳曼语：德语 Brand、荷兰语 brand、瑞典语 brand。"},"items":[{"word":"brand","structure":"brand (base noun and verb)","meaning":"a mark made by burning; to mark with fire","meaningCN":"烧出的记号；用火打记号","example":"They brand the crates before shipping.","exampleCN":"发货前他们在木箱上打烙印。"},{"word":"branding","structure":"brand + -ing","meaning":"the act of marking, or the work of building a brand","meaningCN":"打烙印的动作，或塑造品牌的工作","example":"Branding took most of the marketing budget.","exampleCN":"品牌塑造占去了大部分营销预算。"},{"word":"branded","structure":"brand + -ed","meaning":"marked or carrying a brand","meaningCN":"打了烙印的；带品牌的","example":"Branded goods cost more than loose ones.","exampleCN":"有品牌的货物比散装贵。"},{"word":"unbranded","structure":"un- (not) + brand + -ed","meaning":"sold without a maker's name","meaningCN":"不带制造者名字出售的","example":"Unbranded rice sells in plain sacks.","exampleCN":"无品牌大米装在素麻袋里卖。"},{"word":"rebrand","structure":"re- (again) + brand","meaning":"to give a new name or image","meaningCN":"重新命名或重塑形象","example":"The airline rebranded after the merger.","exampleCN":"合并后航空公司重塑了品牌。"},{"word":"brander","structure":"brand + -er","meaning":"a person or tool that brands","meaningCN":"打烙印的人或工具","example":"The brander heated the iron in the fire.","exampleCN":"打烙印的人在火里烧热铁印。"},{"word":"firebrand","structure":"fire + brand","meaning":"a burning stick; also a person who stirs others up","meaningCN":"燃烧的木棒；也指煽动他人的人","example":"The young firebrand demanded immediate reform.","exampleCN":"那位年轻煽动者要求立即改革。"},{"word":"brand name","structure":"brand + name","meaning":"the name under which goods are sold","meaningCN":"货物出售时使用的名字","example":"The brand name appears on every label.","exampleCN":"每个标签上都有品牌名。"},{"word":"brand-new","structure":"brand + new (from the idea of fresh from the fire)","meaning":"completely new","meaningCN":"全新的","example":"The shop opened with brand-new fittings.","exampleCN":"这家店带着全新设备开业。"}],"latinEntries":[],"derivatives":[{"word":"branding","pos":"n.","zh":"品牌塑造；打烙印"},{"word":"branded","pos":"adj.","zh":"有品牌的；带烙印的"},{"word":"unbranded","pos":"adj.","zh":"无品牌的"},{"word":"rebrand","pos":"v.","zh":"重塑品牌"},{"word":"brander","pos":"n.","zh":"打烙印的人或工具"},{"word":"firebrand","pos":"n.","zh":"火把；煽动者"}]}},{"word":"branding","ipa_uk":"/ˈbrændɪŋ/","ipa_us":"/ˈbrændɪŋ/","definition_zh":"品牌塑造；品牌设计；打烙印；污名化","definition_en":"the work of giving goods a name, look and identity, or the act of burning an ownership mark","core_image":"同一块烧红的铁印，一边烙在木箱上标记归属，一边烙进人心里成为形象","scene":"同一枚铁印，牧场主用来烙木箱，市场部用来烙进人的记忆。The branding on the box told every buyer where the coffee came from.","sceneCN":"同一枚铁印，牧场主用来烙木箱，市场部用来烙进人的记忆；句中的这个词指「打在货物上的品牌标识」（第 6 个义项：作为标记总称的烙印与品牌印记）。图中可辨识物件：烧红的铁印、木箱、咖啡袋、标签、记忆里的同一图案。","pos":[{"tag":"n.","zh":"品牌塑造；品牌建设（不可数）"},{"tag":"n.","zh":"打烙印（给牲畜或货物烙印的动作）"},{"tag":"v.-ing","zh":"打烙印；塑造品牌（brand 的现在分词）"}],"collocations":[{"phrase":"branding strategy","zh":"品牌策略"},{"phrase":"corporate branding","zh":"企业品牌塑造"},{"phrase":"product branding","zh":"产品品牌化"},{"phrase":"rebranding exercise","zh":"品牌重塑项目"},{"phrase":"personal branding","zh":"个人品牌塑造"},{"phrase":"cattle branding","zh":"给牛打烙印"}],"forms":[{"label":"动词原形","form":"brand"},{"label":"三单（he/she/it）","form":"brands"},{"label":"过去式","form":"branded"},{"label":"过去分词","form":"branded"},{"label":"名词（品牌；烙印）","form":"brand"},{"label":"名词（打烙印的人或工具）","form":"brander"}],"derivatives":[{"word":"brand","pos":"n./v.","zh":"品牌；烙印"},{"word":"branded","pos":"adj.","zh":"带品牌的；已烙印的"},{"word":"unbranded","pos":"adj.","zh":"无品牌的"},{"word":"rebranding","pos":"n.","zh":"品牌重塑"},{"word":"brander","pos":"n.","zh":"打烙印的人或工具"}],"senses":[{"no":"01","title":"The work of building a brand","titleCN":"品牌塑造","definition":"the whole effort of giving goods or a company a recognizable name, look and personality","definitionCN":"为货物或公司建立可识别的名称、外观与性格的整套努力","example":"Most of the launch budget went into branding, not into the product.","exampleCN":"上市预算的大部分花在品牌塑造上，而不是产品本身。","why":"The -ing noun names an ongoing activity, and this activity is the modern heir of the ownership mark: both make a thing recognizable.","whyCN":"这个 -ing 名词命名一项持续的活动，而这项活动正是「所有权记号」的现代继承者：两者都让某物变得可被认出。"},{"no":"02","title":"The act of burning a mark","titleCN":"打烙印的动作","definition":"the act of pressing a hot iron onto an animal or a crate to leave an ownership mark","definitionCN":"把烧红的铁器按在牲畜或木箱上，留下所有权记号的动作","example":"Branding takes place in early spring, before the flies return.","exampleCN":"打烙印在早春进行，赶在苍蝇回来之前。","why":"This is the literal sense: the suffix -ing simply names the action of the base verb.","whyCN":"这是字面义：后缀 -ing 只是把基础动词的动作名词化。"},{"no":"03","title":"The design of the visual identity","titleCN":"品牌设计（标识与视觉系统）","definition":"the design work that produces a name's visual system, from the mark to the colours and type","definitionCN":"为一个名字产出视觉系统的工作，从图形标识到配色与字体","example":"The branding uses one green and one typeface everywhere.","exampleCN":"这套品牌设计处处只用一种绿色和一种字体。","why":"A burned mark had one shape and one colour; a modern identity multiplies that mark into a whole system.","whyCN":"烙痕只有一种形状、一种颜色；现代的品牌识别把这个记号扩展成一整套系统。"},{"no":"04","title":"Claiming a place in the market","titleCN":"品牌定位","definition":"the work of fixing where a brand sits in buyers' minds compared with rivals","definitionCN":"确定一个品牌相对竞争对手在买家心中所占据位置的工作","example":"Its branding aims at older buyers who distrust trends.","exampleCN":"它的品牌定位瞄准不信任潮流的中老年买家。","why":"A mark tells you whose a thing is; positioning tells you what kind of thing it is, and for whom.","whyCN":"记号告诉你这是谁的；定位则告诉你这是怎样的一类东西、为谁而做。"},{"no":"05","title":"Turning a product into a named brand","titleCN":"品牌化（把商品变成品牌）","definition":"the process of turning a plain product into one sold under a recognized name","definitionCN":"把一件普通商品变成以可识别名字出售的产品的过程","example":"Salt is the textbook case of successful branding.","exampleCN":"食盐是成功品牌化的教科书案例。","why":"When a commodity that nobody could tell apart gets a mark, the mark itself becomes the difference.","whyCN":"当一种谁也分不出的日用品被加上记号，这个记号本身就成了差别。"},{"no":"06","title":"The mark itself, in bulk","titleCN":"印记总称：烙印与品牌标识","definition":"the marks themselves, taken together, on hides, crates or packaging","definitionCN":"烙印或包装上的那些记号，合在一起看","example":"The branding on the box told every buyer where the coffee came from.","exampleCN":"箱子上的印记告诉每个买家这咖啡来自哪里。","why":"As with other -ing nouns, the activity also names the set of things it produces.","whyCN":"和其他 -ing 名词一样，这项活动也兼指它产出的一整套东西。"},{"no":"07","title":"Attaching a stigma","titleCN":"污名化","definition":"the act of fixing a lasting negative label on a person or group","definitionCN":"把持久的负面标签固定在某人或某群体身上的行为","example":"The branding of these patients as difficult delayed their care.","exampleCN":"把这些病人污名化为「难缠」，延误了他们的治疗。","why":"A burned mark on a person was public and permanent; the modern word keeps both properties and drops the iron.","whyCN":"烙在人身上的记号又公开又永久；现代这个词保留了这两点，只是把铁拿掉了。"},{"no":"08","title":"Brand management as a function","titleCN":"品牌管理（企业职能）","definition":"the function inside a company that guards consistency of the name and its assets","definitionCN":"公司内部守护名字及其资产之一致性的职能","example":"Branding reports to the marketing director in most firms.","exampleCN":"多数公司里品牌管理向营销总监汇报。","why":"Any recurring activity becomes a desk with a budget, and the -ing noun names that desk too.","whyCN":"任何反复进行的活动都会变成一张带预算的办公桌，这个 -ing 名词也用来命名那张桌子。"}],"etymology":{"intro":{"en":"Branding is brand plus -ing. Its fire sense is medieval, its marketing sense is a twentieth-century extension.","cn":"branding 是 brand 加 -ing。火与烙印的用法是中世纪的，营销义是二十世纪的延伸。"},"items":[{"era":"OLD ENGLISH BRAND","en":"Old English brand meant 'fire, flame; a burning piece of wood'. The Germanic relatives are German Brand and Dutch brand.","cn":"古英语 brand 指「火、火焰；燃烧的木块」。日耳曼语亲属是德语 Brand 与荷兰语 brand。"},{"era":"MEDIEVAL MARKING","en":"The verb brand is recorded in the medieval period for pressing a hot iron onto animals, and later onto goods, to show ownership.","cn":"动词 brand 在中世纪有记录，指用烧红的铁器烙在牲畜身上，后来也烙在货物上，以示所有权。"},{"era":"ENGLISH -ING","en":"The suffix -ing forms action nouns and also mass nouns for what an activity produces, as with clothing or flooring.","cn":"后缀 -ing 既能造动作名词，也能指该活动的产出物，如 clothing 或 flooring。"},{"era":"NINETEENTH CENTURY","en":"As makers began stamping names and pictures on packaging, the mark moved from crates to printed labels.","cn":"当制造者开始在包装上印名字与图案，记号就从木箱移到了印刷标签上。"},{"era":"TWENTIETH CENTURY","en":"Advertising agencies took over the work of building a name, and branding became the term for designing and managing identity.","cn":"广告代理公司接手了建立名字的工作，branding 成了设计与经营识别系统的术语。"},{"era":"MODERN ENGLISH","en":"The word now covers visual design, positioning, reputation management and also the figurative stigma sense.","cn":"这个词如今涵盖视觉设计、定位、声誉管理，也包括比喻性的污名化用法。"}]},"similar":{"note":{"en":"Group one shares the fire root; group two names neighbouring marketing activities.","cn":"第一组共享「火」的词根；第二组是相邻的营销活动。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"brand","ipa":"/brænd/","tag":"noun and verb","definition":"The thing or the action itself; branding is the ongoing work or the set of marks.","definitionCN":"指那个东西或那个动作本身；branding 指持续的工作或那套记号。"},{"word":"branded","ipa":"/ˈbrændɪd/","tag":"participle","definition":"Describes something already marked or supplied with a brand name.","definitionCN":"描述已打上记号或已具备品牌的某物。"},{"word":"brander","ipa":"/ˈbrændə/","tag":"tool or person","definition":"The person who burns the mark, or the iron used; a countable noun of agency.","definitionCN":"打烙印的人，或所用的铁印；是可数的施事名词。"},{"word":"braiding","ipa":"/ˈbreɪdɪŋ/","tag":"near spelling","definition":"Weaving strands together; it looks close in spelling but shares no root and no idea.","definitionCN":"把细股编在一起；拼写接近，但既不共享词根也不共享意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"marketing","ipa":"/ˈmɑːkɪtɪŋ/","tag":"wider","definition":"The whole commercial discipline of product, price, place and promotion; branding is one part of it.","definitionCN":"产品、价格、渠道与推广的整套商业学科；品牌塑造只是其中一部分。"},{"word":"advertising","ipa":"/ˈædvətaɪzɪŋ/","tag":"paid messages","definition":"Buying and placing messages; branding builds the identity those messages refer to.","definitionCN":"购买并投放信息；品牌塑造则建立信息所指向的那个身份。"},{"word":"identity design","ipa":"/aɪˈdentəti dɪˈzaɪn/","tag":"visual only","definition":"The visual part alone, marks, colours and type; branding also includes positioning and behaviour.","definitionCN":"仅指视觉部分——标识、配色与字体；品牌塑造还包括定位与行为。"},{"word":"labelling","ipa":"/ˈleɪblɪŋ/","tag":"attaching tags","definition":"Fixing a descriptive tag to a product; it is a narrower mechanical act than building a name.","definitionCN":"给产品贴上说明标签；比建立一个名字要窄，也更机械。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real fire root plus a real suffix with two jobs.","cn":"正常联想：真实的「火」词根，加一个承担两种功能的后缀。"},"normal":[{"en":"brand + -ing: the -ing says either 'the action' or 'the whole set of marks'.","cn":"brand 加 -ing：-ing 要么表示「这个动作」，要么表示「整套记号」。"},{"en":"Fixed phrases show both worlds: cattle branding and corporate branding.","cn":"固定搭配显示两个世界：给牛打烙印，与企业品牌塑造。"},{"en":"The mark answers 'whose'; positioning answers 'for whom' — branding does both.","cn":"记号回答「这是谁的」，定位回答「为谁而做」——品牌塑造两件事都做。"},{"en":"The verb ladder is brand → branded → branding → rebranding.","cn":"动词阶梯是 brand → branded → branding → rebranding。"},{"en":"German Brand and Dutch brand are the same fire word next door.","cn":"德语 Brand 与荷兰语 brand 就是隔壁语言里的同一个「火」词。"}],"abstract":[{"en":"Picture one iron stamp used twice: once on wood, once on memory.","cn":"想象同一枚铁印用了两次：一次印在木头上，一次印在记忆里。"},{"en":"Every sense is a permanent mark that separates one thing from another.","cn":"每个义项都是一个永久记号，把一物与另一物分开。"},{"en":"The iron is gone; the permanence and the public visibility remain.","cn":"铁已经不在，永久性与公开可见性却留了下来。"}]},"examples":[{"en":"The rebranding cost more than the factory that makes the product.","cn":"这次品牌重塑的花费超过了生产该产品的工厂。"},{"en":"Cattle branding is regulated in most ranching states.","cn":"多数牧业州对给牛打烙印有专门规定。"},{"en":"The branding of welfare claimants as lazy shaped public opinion for a decade.","cn":"把福利领取者污名化为懒惰，左右了公众舆论十年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「布兰丁」——布上烙个钉（丁），记号就在布上定了型 → branding 品牌塑造、打烙印","word":"branding"},"root":"brand「火；燃烧的木块」+ -ing（动作或产出名词后缀）；brand 属日耳曼语族，拉丁语无同源词。","sensesIntro":{"en":"Eight senses divide one idea between action and result: burning a mark, the mark itself, the design of the mark, its place in the mind, the naming of a product, the stigma a mark can inflict, and the desk that manages it all.","cn":"八个义项把同一个想法分给动作与结果两端：烧出记号、记号本身、记号的设计、它在心里的位置、把产品命名、记号能造成的污名，以及管理这一切的那张办公桌。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hot iron, two surfaces — wood and memory.","cn":"核心意象：一枚烧红的铁印，两个表面——木头与记忆。"},"chain":["FIRE","MARK","NAME","IDENTITY","POSITION","MANAGEMENT"],"branches":[{"senses":"01 · 08","en":"WORK AND DESK: the effort of building a brand and the department that guards it are the same activity at two scales.","cn":"工作与部门：塑造品牌的努力与守护它的部门，是同一活动在两个尺度上。"},{"senses":"02 · 06","en":"ACT AND MARKS: burning the iron names the action, and the whole set of marks names the result.","cn":"动作与记号：烧铁的动作命名了过程，整套记号命名了结果。"},{"senses":"03","en":"DESIGN: one burned shape grows into a full visual system.","cn":"设计：一个烧出的形状长成一整套视觉系统。"},{"senses":"04 · 05","en":"POSITION AND COMMODITY: a mark says whose it is, then says what kind of thing it is and for whom.","cn":"定位与商品：记号先说这是谁的，再说这是怎样的一类东西、为谁而做。"},{"senses":"07","en":"STIGMA: the public permanent mark returns as a label on a person.","cn":"污名：那个公开而永久的记号，作为标签回到了人身上。"}]},"affixes":{"intro":{"en":"Branding is one Germanic root plus one English suffix, and the suffix does double duty for action and product.","cn":"branding 是一个日耳曼词根加一个英语后缀，而这个后缀同时承担动作与产出的双重功能。"},"latinIntro":{"en":"This Germanic root has no Latin cognate. Latin expresses a mark with nota or stigma, which are unrelated words. The Germanic relatives are German Brand, Dutch brand and Swedish brand.","cn":"这个日耳曼词根没有拉丁同源词。拉丁语用 nota 或 stigma 表示标记，那是无关的词。日耳曼亲属是德语 Brand、荷兰语 brand、瑞典语 brand。"},"items":[{"word":"-ing","structure":"-ing (action and product suffix)","meaning":"the act, or the material result","meaningCN":"动作，或动作的产出物","example":"The suffix names both the work and its output.","exampleCN":"这个后缀同时命名工作与产出。"},{"word":"brand","structure":"brand (base noun and verb)","meaning":"a burned mark; to burn a mark","meaningCN":"烙痕；打烙印","example":"They brand every crate before shipping.","exampleCN":"发货前他们给每个木箱打烙印。"},{"word":"branding","structure":"brand + -ing","meaning":"the work or the marks","meaningCN":"这项工作或那套记号","example":"Branding filled the whole launch budget.","exampleCN":"品牌塑造占满了上市预算。"},{"word":"branded","structure":"brand + -ed","meaning":"marked or carrying a name","meaningCN":"已打记号的；带名字的","example":"The branded sacks sold faster.","exampleCN":"带品牌的麻袋卖得更快。"},{"word":"unbranded","structure":"un- + brand + -ed","meaning":"without a maker's mark","meaningCN":"没有制造者标记的","example":"Unbranded flour is cheaper.","exampleCN":"无品牌面粉更便宜。"},{"word":"rebranding","structure":"re- + brand + -ing","meaning":"the work of replacing an identity","meaningCN":"替换品牌身份的工作","example":"The rebranding kept the old colours.","exampleCN":"这次品牌重塑保留了旧配色。"},{"word":"brander","structure":"brand + -er","meaning":"the person or iron that marks","meaningCN":"打烙印的人或铁印","example":"The brander worked quickly.","exampleCN":"打烙印的人动作很快。"},{"word":"firebrand","structure":"fire + brand","meaning":"a burning stick; a agitator","meaningCN":"燃烧的木棒；煽动者","example":"The firebrand left the meeting early.","exampleCN":"那位煽动者早早离会。"},{"word":"brand name","structure":"brand + name","meaning":"the selling name of goods","meaningCN":"货物的出售名称","example":"The brand name became a common noun.","exampleCN":"这个品牌名变成了普通名词。"}],"latinEntries":[],"derivatives":[{"word":"brand","pos":"n./v.","zh":"品牌；烙印"},{"word":"branded","pos":"adj.","zh":"带品牌的；已烙印的"},{"word":"unbranded","pos":"adj.","zh":"无品牌的"},{"word":"rebranding","pos":"n.","zh":"品牌重塑"},{"word":"brander","pos":"n.","zh":"打烙印的人或工具"}]}},{"word":"brand awareness","ipa_uk":"/ˈbrænd əˈweənəs/","ipa_us":"/ˈbrænd əˈwernəs/","definition_zh":"品牌知名度；品牌认知度","definition_en":"the extent to which buyers know that a brand exists and can recognize or recall it","core_image":"一排货架前，顾客还没走近就先用手指向其中一个盒子，因为他早就认得那个名字","scene":"货架前，顾客还没走近就用手指向其中一个盒子，因为他早就认得那个名字。Brand awareness rose sharply after the stadium took the company's name.","sceneCN":"货架前，顾客还没走近就用手指向其中一个盒子，因为他早就认得那个名字；句中的这个短语指「买家对某品牌存在与识别的知晓程度」（第 1 个义项：能认出该品牌、且知道它存在的那部分人群比例）。图中可辨识物件：货架、指向的手指、盒子、体育场冠名牌、调查问卷。","pos":[{"tag":"n.","zh":"品牌知名度（不可数）"},{"tag":"n.","zh":"品牌认知度；品牌知晓（营销术语，不可数）"}],"collocations":[{"phrase":"raise brand awareness","zh":"提升品牌知名度"},{"phrase":"measure brand awareness","zh":"测量品牌知名度"},{"phrase":"brand awareness campaign","zh":"品牌认知宣传活动"},{"phrase":"low brand awareness","zh":"知名度偏低"},{"phrase":"aided brand awareness","zh":"提示后品牌知名度"},{"phrase":"top-of-mind awareness","zh":"最先想到的品牌"}],"forms":[{"label":"复数（少见，指多次测量结果）","form":"brand awareness levels"},{"label":"组成名词（品牌）","form":"brand"},{"label":"组成形容词（知晓的）","form":"aware"},{"label":"相关名词（知名度测量）","form":"awareness measurement"},{"label":"相关说法（品牌识别）","form":"brand recognition"}],"derivatives":[{"word":"brand","pos":"n./v.","zh":"品牌；打烙印"},{"word":"aware","pos":"adj.","zh":"知道的；察觉的"},{"word":"awareness","pos":"n.","zh":"意识；知晓"},{"word":"branded","pos":"adj.","zh":"带品牌的"},{"word":"unaware","pos":"adj.","zh":"不知道的"}],"senses":[{"no":"01","title":"Buyers know the brand exists","titleCN":"品牌知名度：知道它存在","definition":"the share of buyers who know that a brand exists and can recognize it","definitionCN":"知道某品牌存在并能认出它的买家所占的比例","example":"Brand awareness rose sharply after the stadium took the company's name.","exampleCN":"体育场冠上公司名字后，品牌知名度大幅上升。","why":"Awareness is a state of knowing, and a brand's first task is to be known at all before it can be preferred.","whyCN":"awareness 是「知道」的状态，而一个品牌的第一件事，是在被偏好之前先被人知道。"},{"no":"02","title":"Buyers know what the brand does","titleCN":"品牌认知：知道它是做什么的","definition":"the level of understanding buyers have about what the brand sells or stands for","definitionCN":"买家对该品牌卖什么、代表什么的理解程度","example":"Awareness was high, but few knew the brand made tools rather than toys.","exampleCN":"知名度很高，但很少有人知道这个品牌做的是工具而不是玩具。","why":"Knowing a name is not knowing a meaning; the second step fills the name with content.","whyCN":"知道一个名字不等于知道它的含义；第二步是往这个名字里填内容。"},{"no":"03","title":"The brand comes to mind unprompted","titleCN":"无提示回想","definition":"the state in which buyers name the brand themselves when a product category is mentioned","definitionCN":"当提到某个品类时，买家自己就能说出该品牌的状态","example":"Top-of-mind awareness is what every launch really wants.","exampleCN":"无提示的第一联想，才是每次上市真正想要的。","why":"This is awareness at its strongest: no cue is needed, so the name sits at the front of memory.","whyCN":"这是最强程度的知晓：不需要任何提示，名字就坐在记忆最前面。"},{"no":"04","title":"The brand is recognized when shown","titleCN":"提示识别","definition":"the state in which buyers recognize the brand once its name or logo is shown","definitionCN":"一旦看到名字或标识，买家就能认出该品牌的状态","example":"Aided awareness was ninety per cent, unaided only twelve.","exampleCN":"提示后的识别率是九成，无提示的只有一成二。","why":"Recognition is the weaker form: a cue does half the work, and the memory only has to agree.","whyCN":"识别是较弱的一种：提示做了一半的活，记忆只需点头。"},{"no":"05","title":"The brand is recalled at the moment of buying","titleCN":"购买时的品牌想起","definition":"the state in which the brand occurs to a buyer while choosing in a shop or a feed","definitionCN":"买家在店里或信息流里挑选时想到该品牌的状态","example":"Awareness without availability does not survive the walk down the aisle.","exampleCN":"只有知名度而买不到，走不到货架尽头就消失了。","why":"Memory must fire at the moment of choice, or the name is known and useless.","whyCN":"记忆必须在选择的瞬间被点亮，否则这个名字虽被知道却毫无用处。"},{"no":"06","title":"Awareness produced by advertising","titleCN":"广告带来的知晓度","definition":"the level of knowing that paid messages have created in a population","definitionCN":"付费信息在一群人身上造出的知晓程度","example":"The campaign lifted awareness among teenagers by a third.","exampleCN":"这场宣传把青少年中的知晓度提高了三分之一。","why":"Advertising buys attention, and awareness is the residue that attention leaves behind.","whyCN":"广告买注意力，而知晓度就是注意力留下的残留物。"},{"no":"07","title":"A measured marketing figure","titleCN":"调研指标：可量化的知名度","definition":"a numeric indicator reported in market research, usually as a percentage of a group","definitionCN":"市场调研中汇报的数值指标，通常以某人群的百分比表示","example":"The report tracks awareness quarterly against three rivals.","exampleCN":"这份报告每季度追踪与三家对手相比的知名度。","why":"Once a state of mind is worth money, it gets counted, and the counted thing takes the name of the state.","whyCN":"一旦某种心理状态值钱，它就会被计数，而被计数的那个东西就借用了这种状态的名字。"},{"no":"08","title":"The reach of exposure","titleCN":"品牌曝光度","definition":"the size of the audience that has been exposed to the brand's messages","definitionCN":"接触过该品牌信息的人群规模","example":"Awareness of that size needs exposure of a size nobody budgeted for.","exampleCN":"这样大的曝光度需要同样大的投放量，而没人为此做过预算。","why":"This is the input side: exposure measures who saw the message, awareness measures who kept it.","whyCN":"这是输入一侧：曝光度衡量谁看到了信息，知晓度衡量谁把信息留了下来。"}],"etymology":{"intro":{"en":"The phrase joins a Germanic noun for a burned mark with an Old English adjective for being watchful. Both halves are old; the marketing use is recent.","cn":"这个短语把日耳曼语里表示烙痕的名词，与古英语里表示「警觉、知道」的形容词连在一起。两半都很古老，营销用法却很新。"},"items":[{"era":"OLD ENGLISH BRAND","en":"Brand meant 'fire, a burning piece of wood', then 'an ownership mark burned onto animals and goods'.","cn":"brand 先指「火、燃烧的木块」，再指「烙在牲畜与货物上表示所有权的记号」。"},{"era":"OLD ENGLISH GEWÆR","en":"Aware goes back to Old English gewær 'watchful, vigilant'. The same Germanic stock gives German gewahr 'aware'.","cn":"aware 上溯到古英语 gewær「警觉的、留神的」。同一日耳曼词源给了德语 gewahr「知晓的」。"},{"era":"DEEPER ORIGIN","en":"It is generally considered related to a reconstructed root meaning 'to perceive, to watch out for'. The reconstruction is standard, though the exact path is not demonstrated.","cn":"一般认为它与一个重构的「察觉、提防」词根相关。这一重构是通行说法，但确切路径未被证明。"},{"era":"NINETEENTH CENTURY","en":"The noun awareness is recorded in the nineteenth century, formed from aware plus -ness, meaning simply the state of knowing.","cn":"名词 awareness 在十九世纪有记录，由 aware 加 -ness 构成，只表示「知道的状态」。"},{"era":"MID-TWENTIETH CENTURY","en":"Market research borrowed the word to measure whether buyers could name or recognize a brand, and split it into aided and unaided recall.","cn":"市场调研借走这个词，用来衡量买家能否说出或认出某个品牌，并把它分成提示回想与无提示回想。"},{"era":"DIGITAL ERA","en":"Online advertising turned awareness into a continuous number, reported daily alongside clicks and impressions.","cn":"网络广告把知晓度变成一个连续更新的数字，与点击和曝光一起按日汇报。"}]},"similar":{"note":{"en":"Group one contains phrases built on the same two words; group two contains neighbouring marketing measures.","cn":"第一组由同样两个词构成；第二组是相邻的营销指标。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"brand recognition","ipa":"/ˈbrænd ˌrekəɡˈnɪʃn/","tag":"one half of awareness","definition":"The ability to identify a brand when it is shown; it is the aided half, not the whole measure.","definitionCN":"看到品牌标识时能认出来的能力；它只是提示的那一半，不是全部指标。"},{"word":"brand recall","ipa":"/ˈbrænd ˈriːkɔːl/","tag":"the other half","definition":"The ability to name a brand from memory without a cue; it is the harder and usually lower figure.","definitionCN":"在没有提示时凭记忆说出品牌的能力；它更难，数值通常更低。"},{"word":"brand image","ipa":"/ˈbrænd ˈɪmɪdʒ/","tag":"meaning, not knowing","definition":"What buyers think the brand is like; awareness only asks whether they know it at all.","definitionCN":"买家认为这个品牌是什么样子；awareness 只问他们是否知道它。"},{"word":"brand loyalty","ipa":"/ˈbrænd ˈlɔɪəlti/","tag":"behaviour, not knowing","definition":"The habit of buying the same brand repeatedly; knowing a name does not imply buying it.","definitionCN":"反复购买同一品牌的习惯；知道一个名字并不等于会买它。"}]},{"heading":"NEAR MEANING","entries":[{"word":"visibility","ipa":"/ˌvɪzəˈbɪləti/","tag":"exposure","definition":"How often a brand is seen, which is the input; awareness is what remains in the mind afterwards.","definitionCN":"品牌被看见的频率，属于输入；awareness 是事后留在脑子里的东西。"},{"word":"familiarity","ipa":"/fəˌmɪliˈærəti/","tag":"feeling of knowing","definition":"A sense that a name is known and safe, often weaker and vaguer than measured awareness.","definitionCN":"觉得这个名字熟悉、安全的感觉，往往比被测量的知晓度更弱、更模糊。"},{"word":"publicity","ipa":"/pʌbˈlɪsəti/","tag":"attention","definition":"Attention gained, often unpaid; awareness is the knowledge that this attention leaves behind.","definitionCN":"获得的关注，往往不付费；awareness 是这份关注留下的知识。"},{"word":"reach","ipa":"/riːtʃ/","tag":"audience count","definition":"The number of different people exposed to a message; it counts exposure, not memory.","definitionCN":"接触到某条信息的不同人数；它数的是曝光，不是记忆。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real words joined, and real research phrases.","cn":"正常联想：两个真实的词拼在一起，加上真实的研究说法。"},"normal":[{"en":"brand 'burned mark' + aware 'watchful': a mark people have noticed.","cn":"brand「烙痕」加 aware「留神的」：一个被人注意到的记号。"},{"en":"Awareness splits into two halves in research: recognition with a cue, recall without one.","cn":"在调研里，知晓度分成两半：有提示的识别，无提示的回想。"},{"en":"Fixed phrases show the trade: raise brand awareness, a brand awareness campaign, top-of-mind awareness.","cn":"固定搭配显示行业说法：提升知名度、品牌认知宣传活动、最先想到的品牌。"},{"en":"aware + -ness gives the plain noun awareness, the state of knowing.","cn":"aware 加 -ness 得到朴素名词 awareness，即「知道的状态」。"},{"en":"The old word gewær survives in the German gewahr, still meaning aware.","cn":"古老的 gewær 还活在德语 gewahr 里，仍表示「知晓的」。"}],"abstract":[{"en":"Picture a finger rising before the shopper reaches the shelf: that finger is awareness.","cn":"想象顾客还没走到货架，手指就先抬了起来：那根手指就是知晓度。"},{"en":"Knowing a name and knowing what it means are two different depths of the same water.","cn":"知道一个名字与知道它的含义，是同一片水的两个深度。"},{"en":"Exposure is what enters the eye; awareness is what stays after the eye moves on.","cn":"曝光是进入眼睛的东西；知晓度是目光移开之后留下的东西。"}]},"examples":[{"en":"The company spent two years buying brand awareness before it sold a single unit.","cn":"这家公司先花两年买知名度，才卖出第一件产品。"},{"en":"Brand awareness among rural buyers is still under a fifth.","cn":"农村买家中的品牌知名度仍不足五分之一。"},{"en":"They measured brand awareness before and after the sponsorship.","cn":"他们测量了赞助前后的品牌知名度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「布兰德-阿威尔尼斯」——布上烙的记号（布兰德）被人「阿威尔」地看在眼里 → 品牌知名度","word":"brand awareness"},"root":"brand（日耳曼语「火、烙痕」）+ awareness（aware「警觉的、知晓的」+ -ness），合指「一个记号被人知道的程度」。","sensesIntro":{"en":"Eight senses climb a ladder of knowing: that the brand exists, what it means, that it comes to mind alone, that it is recognized when shown, that it is recalled at the shelf, that advertising produced it, that it can be counted, and that it depends on exposure.","cn":"八个义项沿着「知道」的梯子往上：知道它存在、知道它意味着什么、不用提示就想到、看见时认得出、在货架前想得起、由广告造出、可以被计数，以及它取决于曝光。"},"semanticMap":{"core":{"en":"CORE IMAGE: a finger rising toward a shelf before the shopper even arrives.","cn":"核心意象：顾客还没走到，手指就先指向货架。"},"chain":["SEE","RECOGNIZE","RECALL","UNDERSTAND","CONSIDER","MEASURE"],"branches":[{"senses":"01 · 04","en":"TWO STRENGTHS OF KNOWING: recognizing with a cue is easier than knowing without one.","cn":"两种强度的知道：有提示时认出来，比没有提示时知道要容易。"},{"senses":"02","en":"CONTENT: a known name still has to be filled with meaning.","cn":"内容：被知道的名字仍须填进含义。"},{"senses":"03 · 05","en":"FIRE AT THE RIGHT MOMENT: coming to mind unprompted and coming to mind at the shelf are the same spark, one earlier and one later.","cn":"在对的时刻点亮：不用提示就想到，与在货架前想到，是同一个火花，一个更早一个更晚。"},{"senses":"06 · 08","en":"INPUT: advertising buys exposure, and exposure is the raw material of knowing.","cn":"输入：广告买到曝光，而曝光是「知道」的原料。"},{"senses":"07","en":"NUMBER: once knowing is valuable, it is counted and becomes a figure.","cn":"数字：一旦「知道」值钱，它就被计数，变成一个数值。"}]},"affixes":{"intro":{"en":"This phrase is two whole words joined: a Germanic noun with no Latin cognate, and an Old English adjective plus a native suffix.","cn":"这个短语由两个完整的词拼成：一个没有拉丁同源词的日耳曼名词，和一个古英语形容词加本土后缀。"},"latinIntro":{"en":"Neither half has a Latin source. Brand is Germanic; aware goes back to Old English gewær. Latin expresses the same ideas as nota for a mark and cognoscere for knowing, but these are different words, not relatives.","cn":"两半都没有拉丁来源。brand 属日耳曼语；aware 上溯古英语 gewær。拉丁语用 nota 表示记号、用 cognoscere 表示知道，但那是不同的词，并非亲属。"},"items":[{"word":"brand","structure":"brand (Germanic noun)","meaning":"a burned ownership mark","meaningCN":"烧出的所有权记号","example":"The brand was cut into every crate.","exampleCN":"每个木箱上都刻着那个记号。"},{"word":"aware","structure":"aware (from Old English gewær, 'watchful')","meaning":"knowing that something exists","meaningCN":"知道某物存在","example":"Few buyers were aware of the second brand.","exampleCN":"很少有买家知道第二个品牌。"},{"word":"-ness","structure":"-ness (native noun suffix)","meaning":"the state of being","meaningCN":"处于某种状态","example":"The suffix turns an adjective into a state.","exampleCN":"这个后缀把形容词变成一种状态。"},{"word":"awareness","structure":"aware + -ness","meaning":"the state of knowing","meaningCN":"知道的状态","example":"Awareness of the recall spread quickly.","exampleCN":"召回的消息很快为人所知。"},{"word":"unaware","structure":"un- (not) + aware","meaning":"not knowing","meaningCN":"不知道的","example":"Half the buyers were unaware of the offer.","exampleCN":"一半买家不知道有这个优惠。"},{"word":"brand awareness","structure":"brand + awareness","meaning":"how widely a brand is known","meaningCN":"品牌被知道的程度","example":"Brand awareness doubled in a year.","exampleCN":"品牌知名度一年内翻倍。"},{"word":"recognition","structure":"re- + cognoscere (to know) + -tion","meaning":"identifying something known","meaningCN":"认出已知之物","example":"Recognition needs only a glance at the label.","exampleCN":"认出只需瞥一眼标签。"},{"word":"recall","structure":"re- + call","meaning":"bringing a name back to mind","meaningCN":"把名字唤回脑中","example":"Recall is harder than recognition.","exampleCN":"回想比识别更难。"}],"latinEntries":[{"word":"nota","structure":"nota, notae (noun, first declension)","meaning":"a mark, a sign","meaningCN":"记号；标记"},{"word":"cognoscere","structure":"cognoscere, cognovi, cognitum (verb)","meaning":"to come to know","meaningCN":"获知；认识"},{"word":"agnoscere","structure":"ad- + (g)noscere","meaning":"to recognize","meaningCN":"认出"}],"derivatives":[{"word":"brand","pos":"n./v.","zh":"品牌；打烙印"},{"word":"aware","pos":"adj.","zh":"知道的；察觉的"},{"word":"awareness","pos":"n.","zh":"意识；知晓"},{"word":"unaware","pos":"adj.","zh":"不知道的"},{"word":"branded","pos":"adj.","zh":"带品牌的"}]}},{"word":"consumer behavior","ipa_uk":"/kənˈsjuːmə bɪˈheɪvjə/","ipa_us":"/kənˈsuːmər bɪˈheɪvjər/","definition_zh":"消费者行为；消费行为","definition_en":"the way people search for, choose, buy, use and dispose of goods and services","core_image":"一个人从盯着一件东西看，到把它放进篮子，用到它见底，再把它丢进回收箱，整个过程连成一条线","scene":"一个人先盯着货架看，再把东西放进篮子，用到底，最后丢进回收箱，全程连成一条线。Consumer behavior changed once the shop began delivering within an hour.","sceneCN":"一个人先盯着货架看，再把东西放进篮子，用到底，最后丢进回收箱，全程连成一条线；句中的这个短语指「人们选购与使用商品服务的整套行为」（第 1 个义项：从产生需求到用后处置的行为总称）。图中可辨识物件：货架、购物篮、见底的瓶子、回收箱、配送箱。","pos":[{"tag":"n.","zh":"消费者行为（不可数；学术与商业用语）"},{"tag":"n.","zh":"某类消费者的行为模式（可作可数，指若干种模式）"}],"collocations":[{"phrase":"consumer behaviour research","zh":"消费者行为研究"},{"phrase":"change consumer behaviour","zh":"改变消费者行为"},{"phrase":"consumer behaviour patterns","zh":"消费者行为模式"},{"phrase":"a theory of consumer behaviour","zh":"消费者行为理论"},{"phrase":"online consumer behaviour","zh":"线上消费行为"},{"phrase":"consumer behaviour analyst","zh":"消费者行为分析师"}],"forms":[{"label":"英式拼写","form":"consumer behaviour"},{"label":"相关形容词","form":"consumer-behavioural"},{"label":"组成名词（消费者）","form":"consumer"},{"label":"组成动词（表现；运转）","form":"behave"},{"label":"相关名词（行为）","form":"behaviour"}],"derivatives":[{"word":"consumer","pos":"n.","zh":"消费者"},{"word":"consume","pos":"v.","zh":"消耗；消费"},{"word":"behave","pos":"v.","zh":"表现；举止"},{"word":"behaviour","pos":"n.","zh":"行为；举止（英式拼写）"},{"word":"behavioural","pos":"adj.","zh":"行为的"},{"word":"consumption","pos":"n.","zh":"消费；消耗"}],"senses":[{"no":"01","title":"The whole set of buying and using acts","titleCN":"消费者行为：选购与使用的行为总称","definition":"the whole range of acts by which people obtain and use goods and services","definitionCN":"人们取得并使用商品与服务的全部行为","example":"Consumer behavior changed once the shop began delivering within an hour.","exampleCN":"商店开始一小时内送达之后，消费者行为就变了。","why":"Two words combine: the one who uses things up, and the way he conducts himself. Together they cover every act around goods.","whyCN":"两个词合起来：一个「把东西用掉的人」，加上「他举止行事的方式」。合起来就涵盖围绕货物的一切行为。"},{"no":"02","title":"The decision process","titleCN":"消费决策过程","definition":"the sequence from recognising a need to searching, comparing, buying and evaluating afterwards","definitionCN":"从意识到需求，到搜寻、比较、购买以及事后评价的序列","example":"Her thesis maps consumer behavior from first search to final review.","exampleCN":"她的论文描出从最初搜索到最终评价的消费者行为全过程。","why":"Behaviour is not one act but a chain, and research usually slices the chain into ordered stages.","whyCN":"行为不是一个动作，而是一条链，研究通常把这条链切成有顺序的几个阶段。"},{"no":"03","title":"The purchase act itself","titleCN":"购买行为","definition":"the moment and manner of actually paying for goods","definitionCN":"实际为商品付款的时刻与方式","example":"Impulse buying is the part of consumer behavior that shops try hardest to shape.","exampleCN":"冲动购买是商店最用力去塑造的那部分消费者行为。","why":"This is the narrowest slice: money changes hands, and everything before it becomes preparation.","whyCN":"这是最窄的一片：钱在此刻易手，此前的一切都成了准备。"},{"no":"04","title":"How goods are used after purchase","titleCN":"使用行为","definition":"the ways people employ a product after they own it","definitionCN":"人们拥有某产品之后使用它的方式","example":"Consumer behavior after purchase decides whether the app is opened twice or daily.","exampleCN":"购买后的使用行为决定了这个应用是一周开两次还是每天开。","why":"Ownership is not the end of the story; the value of a product is realised in use.","whyCN":"拥有并不是故事的终点；产品的价值是在使用中兑现的。"},{"no":"05","title":"What happens when the product is finished","titleCN":"处置行为","definition":"the ways people discard, recycle, resell or give away what they no longer want","definitionCN":"人们丢弃、回收、转卖或赠送不再需要之物的方式","example":"Researchers now treat disposal as part of consumer behavior, not as waste management.","exampleCN":"研究者如今把处置视为消费者行为的一部分，而不是废弃物管理。","why":"The chain does not stop at use: the object still has to leave the household, and leaving is also behaviour.","whyCN":"这条链并不止于使用：物件终究要离开家庭，而「离开」也是一种行为。"},{"no":"06","title":"Repeated habits of choice","titleCN":"消费习惯","definition":"stable patterns of repeated choice that a buyer follows without much thought","definitionCN":"买家不太费力就重复遵循的稳定选择模式","example":"Weekly consumer behavior is mostly habit, not calculation.","exampleCN":"每周的消费者行为多半是习惯，而不是计算。","why":"A chain run many times becomes a groove, and the groove is what brands compete to occupy.","whyCN":"一条链跑过许多次就磨出一道槽，而这槽正是各品牌争夺要占的位置。"},{"no":"07","title":"The behaviour of a group","titleCN":"群体消费行为","definition":"the shared patterns of a defined group of buyers, such as a region or an age band","definitionCN":"某一界定人群的共同模式，如某个地区或某个年龄段","example":"Rural consumer behavior differs sharply from urban in this category.","exampleCN":"在这个品类里，农村的群体消费行为与城市差别很大。","why":"Individual acts are noisy; counted together they form a pattern that can be described and predicted.","whyCN":"单个行为很嘈杂；合起来计数就形成一种可描述、可预测的模式。"},{"no":"08","title":"The academic field","titleCN":"消费者行为学","definition":"the study of how buyers behave, taught and researched as a discipline","definitionCN":"研究买家如何行动的学科，作为一门课程与研究领域","example":"Consumer behavior draws on psychology, economics and anthropology.","exampleCN":"消费者行为学借用了心理学、经济学与人类学。","why":"Any patterned human activity with its own methods becomes a field, and the noun moves into the syllabus.","whyCN":"任何有自身方法的有规律人类活动都会成为一门学问，这个名词也就走进了课程表。"}],"etymology":{"intro":{"en":"The phrase joins a Latin verb for using things up with an Old English verb for conducting oneself. The academic use is mid-twentieth century.","cn":"这个短语把拉丁语「把东西用尽」的动词，与古英语「持身行事」的动词连在一起。学术用法是二十世纪中叶的事。"},"items":[{"era":"LATIN EMERE","en":"Emere meant 'to buy'. With the prefix sub- it formed sumere 'to take up', literally 'to take under oneself'.","cn":"emere 意为「买」。加前缀 sub- 构成 sumere「取用」，字面是「拿到自己身下」。"},{"era":"LATIN CONSUMERE","en":"Com- 'thoroughly' plus sumere gave consumere 'to take up wholly, to use up, to waste'. Its participle is consumptus.","cn":"com-「彻底」加 sumere 构成 consumere「整个取用、耗尽、浪费」。其分词是 consumptus。"},{"era":"CONSUMER","en":"The English noun consumer first named one who wastes or squanders; from the eighteenth century it named the buyer who uses goods, and economics fixed that sense.","cn":"英语名词 consumer 最初指「挥霍者」；从十八世纪起指使用货物的买家，经济学固定了这一义。"},{"era":"OLD ENGLISH BEHAVE","en":"Behave is be- plus have, originally 'to have or hold oneself in a certain way', later 'to conduct oneself'. The noun behaviour adds -our.","cn":"behave 是 be- 加 have，原义「以某种方式持守自己」，后来指「举止行事」。名词 behaviour 加了 -our。"},{"era":"SIXTEENTH CENTURY","en":"The noun behaviour is recorded in the sixteenth century for conduct, and later for the observable actions of animals and systems.","cn":"名词 behaviour 在十六世纪有记录，指举止，后来也指动物与系统可观察的动作。"},{"era":"MID-TWENTIETH CENTURY","en":"After the war, marketing and psychology joined the two words into consumer behavior, a field with journals, models and experiments.","cn":"战后营销学与心理学把这两个词合成 consumer behavior，形成一个拥有期刊、模型与实验的领域。"}]},"similar":{"note":{"en":"Group one swaps one half of the phrase; group two names neighbouring studies or behaviours.","cn":"第一组替换短语的一半；第二组是相邻的研究或行为。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"consumer behaviour","ipa":"/kənˈsjuːmə bɪˈheɪvjə/","tag":"British spelling","definition":"The same phrase in British spelling, with -our instead of -or. The meaning is identical.","definitionCN":"同一个短语的英式拼写，用 -our 而不是 -or。意思完全相同。"},{"word":"customer behavior","ipa":"/ˈkʌstəmə bɪˈheɪvjə/","tag":"narrower actor","definition":"The behaviour of people who already buy from a particular seller; consumer covers users of goods in general.","definitionCN":"已经向某个卖家购买的人的行为；consumer 泛指商品的使用者。"},{"word":"buying behavior","ipa":"/ˈbaɪɪŋ bɪˈheɪvjə/","tag":"one stage only","definition":"Only the purchase stage, leaving out search, use and disposal.","definitionCN":"只指购买这一段，不含搜寻、使用与处置。"},{"word":"consumption","ipa":"/kənˈsʌmpʃn/","tag":"the quantity","definition":"The amount used, an economic total rather than the way people act.","definitionCN":"被使用的数量，是经济总量，而不是人们行动的方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"marketing research","ipa":"/ˈmɑːkɪtɪŋ rɪˈsɜːtʃ/","tag":"the method","definition":"The practice of collecting data about buyers; consumer behavior is what that data tries to explain.","definitionCN":"收集买家数据的做法；消费者行为则是这些数据试图解释的对象。"},{"word":"psychology","ipa":"/saɪˈkɒlədʒi/","tag":"the discipline","definition":"The study of mind and behaviour in general; consumer behavior applies it to buying.","definitionCN":"研究心智与行为的一般学科；消费者行为把它应用于购买。"},{"word":"demand","ipa":"/dɪˈmɑːnd/","tag":"aggregate result","definition":"The total willingness to buy at a price; it is the sum that individual behaviours produce.","definitionCN":"在某个价格上愿意购买的总量；它是无数个体行为汇总出的结果。"},{"word":"lifestyle","ipa":"/ˈlaɪfstaɪl/","tag":"context","definition":"The general way a person lives; it shapes consumer behavior without being the behaviour itself.","definitionCN":"一个人总体的生活方式；它塑造消费者行为，但本身不是行为。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: two real verbs, one Latin and one English, joined into one phrase.","cn":"正常联想：两个真实的动词，一个来自拉丁语，一个来自英语，合成一个短语。"},"normal":[{"en":"consume 'use up' + behave 'conduct oneself': the conduct of people who use things up.","cn":"consume「用尽」加 behave「持身行事」：把东西用掉的人如何行事。"},{"en":"The chain has five links: need, search, buy, use, dispose.","cn":"这条链有五环：需求、搜寻、购买、使用、处置。"},{"en":"Fixed phrases show the field: consumer behaviour research, consumer behaviour patterns, online consumer behaviour.","cn":"固定搭配显示这个领域：消费者行为研究、消费者行为模式、线上消费行为。"},{"en":"British spelling keeps behaviour with -our; American spelling uses behavior.","cn":"英式拼写保留 behaviour 的 -our；美式拼写写作 behavior。"},{"en":"The cousin word customer narrows the actor to one seller's buyers.","cn":"近亲词 customer 把行为者收窄为某个卖家的买家。"}],"abstract":[{"en":"Picture a single line drawn from an empty shelf to a full bin: the whole line is the behaviour.","cn":"想象一条线，从空货架一直画到满溢的垃圾桶：整条线就是这种行为。"},{"en":"Every sense is a segment of that line, and none of the segments is the whole line.","cn":"每个义项都只是这条线上的一段，任何一段都不是整条线。"},{"en":"Habits simply make the line run in the same groove again.","cn":"习惯只是让这条线再一次沿着同一道槽跑。"}]},"examples":[{"en":"The report treats disposal as part of consumer behavior rather than as a rubbish problem.","cn":"这份报告把处置看作消费者行为的一部分，而不是垃圾问题。"},{"en":"Online consumer behavior shifted toward late-night buying.","cn":"线上消费行为转向深夜下单。"},{"en":"She teaches consumer behavior to first-year marketing students.","cn":"她给营销专业一年级学生讲授消费者行为学。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「康苏默-比黑夫」——康苏默把东西用光，比黑夫（举止）就是他用光东西时的样子 → 消费者行为","word":"consumer behavior"},"root":"consumer 出自拉丁 consumere「整个取用、耗尽」= com- + sumere（sub- + emere「买」）；behavior 出自古英语 behave「持身行事」= be- + have。","sensesIntro":{"en":"Eight senses mark one line of conduct around goods: the whole set, the decision chain, the purchase, the use, the disposal, the habit that repeats it, the group pattern and the discipline that studies it.","cn":"八个义项标出围绕货物的一条行为线：整套行为、决策链、购买、使用、处置、把它重复成习惯、群体的模式，以及研究它的那门学科。"},"semanticMap":{"core":{"en":"CORE IMAGE: one drawn line from searching to discarding.","cn":"核心意象：一条从搜寻画到丢弃的线。"},"chain":["NEED","SEARCH","CHOOSE","BUY","USE","DISPOSE"],"branches":[{"senses":"01 · 08","en":"WHOLE AND STUDY: the complete line and the classroom that examines it share one name.","cn":"整体与学科：整条线与考察它的课堂共用一个名字。"},{"senses":"02","en":"CHAIN: the decision process is the line read in order.","cn":"链条：决策过程就是把这条线按顺序读一遍。"},{"senses":"03","en":"THE HANDOVER: money changes hands at one point on the line.","cn":"交接：钱在线上某一点易手。"},{"senses":"04 · 05","en":"AFTER THE SALE: use and disposal are the second half that sellers used to ignore.","cn":"售出之后：使用与处置是卖家过去常忽略的后半段。"},{"senses":"06 · 07","en":"REPEAT AND AGGREGATE: a line run many times becomes a habit, and many lines together become a group pattern.","cn":"重复与汇总：跑过多次的线成了习惯，许多条线合起来成了群体模式。"}]},"affixes":{"intro":{"en":"The phrase is two verbs' worth of history: a Latin root for using up and an English compound verb for behaving.","cn":"这个短语是两部动词史：一个拉丁词根表示「用尽」，一个英语复合动词表示「持身行事」。"},"latinIntro":{"en":"Latin emere 'to buy' with sub- gives sumere 'take up', and with com- gives consumere 'use up'; the same emere is behind redeem, exempt and premium.","cn":"拉丁 emere「买」加 sub- 得 sumere「取用」，加 com- 得 consumere「用尽」；同一个 emere 还藏在 redeem、exempt 与 premium 背后。"},"items":[{"word":"consumer","structure":"consume + -er","meaning":"one who uses goods up","meaningCN":"把货物用掉的人","example":"Consumers ignored the small print.","exampleCN":"消费者不看那些小字。"},{"word":"consume","structure":"con- + sumere (to take up)","meaning":"to use up","meaningCN":"用尽；消耗","example":"The plant consumes enormous power.","exampleCN":"这家工厂消耗巨量电力。"},{"word":"consumption","structure":"consume + -ption","meaning":"the act or amount used","meaningCN":"消耗的动作或数量","example":"Consumption rose with incomes.","exampleCN":"消费随收入上升。"},{"word":"behave","structure":"be- + have","meaning":"to conduct oneself","meaningCN":"举止；表现","example":"Children behave differently in groups.","exampleCN":"孩子在群体中表现不同。"},{"word":"behaviour","structure":"behave + -our (British)","meaning":"conduct; observable action","meaningCN":"举止；可观察的行为","example":"Behaviour follows the shape of the shop.","exampleCN":"行为会随店铺的布局而变。"},{"word":"behavioural","structure":"behaviour + -al","meaning":"relating to behaviour","meaningCN":"与行为有关的","example":"Behavioural studies need long records.","exampleCN":"行为研究需要长期记录。"},{"word":"-or / -our","structure":"Latin -or versus French -our","meaning":"noun ending for a state or action","meaningCN":"表状态或动作的名词词尾","example":"American keeps -or, British keeps -our.","exampleCN":"美式保留 -or，英式保留 -our。"},{"word":"consumer behavior","structure":"consumer + behavior","meaning":"the conduct of buyers","meaningCN":"买家的行为","example":"Consumer behavior studies began after the war.","exampleCN":"消费者行为研究始于战后。"}],"latinEntries":[{"word":"emere","structure":"emere, emi, emptum (verb, third conjugation)","meaning":"to buy","meaningCN":"买"},{"word":"sumere","structure":"sub- + emere","meaning":"to take up","meaningCN":"取用；拿起"},{"word":"consumere","structure":"com- + sumere","meaning":"to use up, waste","meaningCN":"用尽；耗费"}],"derivatives":[{"word":"consumer","pos":"n.","zh":"消费者"},{"word":"consume","pos":"v.","zh":"消耗；消费"},{"word":"consumption","pos":"n.","zh":"消费；消耗"},{"word":"behave","pos":"v.","zh":"表现；举止"},{"word":"behavioural","pos":"adj.","zh":"行为的"},{"word":"behaviour","pos":"n.","zh":"行为；举止（英式拼写）"}]}},{"word":"consumer preference","ipa_uk":"/kənˈsjuːmə ˈprefərəns/","ipa_us":"/kənˈsuːmər ˈprefərəns/","definition_zh":"消费者偏好；消费偏好","definition_en":"the tendency of buyers to favour one product, brand or feature over another","core_image":"两只手各拿一样东西，顾客把其中一只推向自己，另一只推回货架","scene":"两只手各举一样东西，顾客把其中一样拉向自己，另一样轻轻推回货架。Consumer preference shifted to refillable bottles once the deposit returned.","sceneCN":"两只手各举一样东西，顾客把其中一样拉向自己，另一样轻轻推回货架；句中的这个短语指「消费者对某一选项的倾向性选择」（第 1 个义项：买家在两件可比之物中更愿意要哪一件）。图中可辨识物件：两只举起的手、两件商品、推回货架的动作、押金标签、货架。","pos":[{"tag":"n.","zh":"消费者偏好（不可数；指具体偏好时可数）"},{"tag":"n.","zh":"消费偏好（经济学与营销术语）"}],"collocations":[{"phrase":"consumer preferences shift","zh":"消费者偏好发生转变"},{"phrase":"match consumer preferences","zh":"契合消费者偏好"},{"phrase":"a survey of consumer preferences","zh":"消费者偏好调查"},{"phrase":"changing consumer preferences","zh":"不断变化的消费者偏好"},{"phrase":"regional consumer preferences","zh":"地区性消费偏好"},{"phrase":"price and consumer preference","zh":"价格与消费者偏好"}],"forms":[{"label":"复数（指多种偏好）","form":"consumer preferences"},{"label":"组成名词（消费者）","form":"consumer"},{"label":"组成动词（更偏爱）","form":"prefer"},{"label":"相关形容词（优先的；优惠的）","form":"preferential"},{"label":"相关形容词（更受偏爱的）","form":"preferred"}],"derivatives":[{"word":"consumer","pos":"n.","zh":"消费者"},{"word":"prefer","pos":"v.","zh":"更偏爱"},{"word":"preference","pos":"n.","zh":"偏好；偏爱"},{"word":"preferential","pos":"adj.","zh":"优先的；优惠的"},{"word":"preferred","pos":"adj.","zh":"更受偏爱的"},{"word":"preferably","pos":"adv.","zh":"最好；更可取地"}],"senses":[{"no":"01","title":"A leaning toward one option","titleCN":"对某一选项的倾向","definition":"the tendency of buyers to favour one product, brand or feature over another","definitionCN":"买家在两件可比之物中更愿意要其中一件的倾向","example":"Consumer preference shifted to refillable bottles once the deposit returned.","exampleCN":"押金恢复之后，消费者偏好转向了可补充装瓶。","why":"Preference is from a Latin verb meaning 'to place before': one thing is set in front of another in the buyer's mind.","whyCN":"preference 出自一个意为「放在前面」的拉丁动词：在买家心里，一件东西被摆到另一件之前。"},{"no":"02","title":"An order among several options","titleCN":"偏好排序","definition":"a ranking in which several options are placed in order of desirability","definitionCN":"把若干选项按想要的程度的先后排成次序","example":"The survey asked for a preference order among four colours.","exampleCN":"调查要求被试在四种颜色中排出一个偏好次序。","why":"Placing before can be repeated: a whole list can be sorted by what is put first.","whyCN":"「放在前面」可以重复进行：一整张清单都能按「谁在最前」排出来。"},{"no":"03","title":"Preference shown by actual buying","titleCN":"显示性偏好：由实际购买体现","definition":"the preference revealed by what buyers actually choose when they spend money","definitionCN":"买家真正花钱时所做的选择所显示出来的偏好","example":"Revealed consumer preference contradicted everything the interviews said.","exampleCN":"由实际购买显示的消费者偏好，与访谈里说的完全相反。","why":"Economists distrust words and trust receipts: a choice that costs money is a preference that cannot be politely revised.","whyCN":"经济学家不信话语而信收据：花了钱的选择，是一种不能客气地改口的偏好。"},{"no":"04","title":"Preference stated in a survey","titleCN":"陈述性偏好：由调查表达","definition":"the preference buyers report when asked, without necessarily acting on it","definitionCN":"买家在被询问时报告的偏好，未必会照着行动","example":"Stated preference for local food was far higher than actual purchases.","exampleCN":"对本地食品的陈述性偏好远高于实际购买。","why":"Saying what one prefers is cheap; the gap between saying and buying is the reason both measures exist.","whyCN":"说出偏好很廉价；「说」与「买」之间的落差，正是两种测量都要做的原因。"},{"no":"05","title":"A taste for a flavour or style","titleCN":"口味与风格偏好","definition":"a liking for a particular flavour, texture or design rather than for a whole product class","definitionCN":"对某种味道、质感或设计的喜爱，而不是对整类产品的偏好","example":"Consumer preference for darker chocolate grew with age.","exampleCN":"对更苦巧克力的偏好随年龄增长。","why":"The oldest sense of preferring is liking one thing more; here the thing is a sensation on the tongue or the eye.","whyCN":"「更偏爱」最古老的意思就是更喜欢某物；这里那件东西是舌尖或眼睛上的一种感受。"},{"no":"06","title":"A leaning toward a price band","titleCN":"价格偏好","definition":"a tendency to favour goods within a particular price range","definitionCN":"倾向于选择落在某个价位区间内的商品","example":"Consumer preference moved to the middle band when incomes rose.","exampleCN":"收入上升后，消费者偏好移向了中段价位。","why":"A preference is always relative, and price is one of the clearest axes on which two goods can be compared.","whyCN":"偏好永远是相对的，而价格是两件商品最清楚的可比坐标之一。"},{"no":"07","title":"A leaning toward one brand","titleCN":"品牌偏好","definition":"a tendency to choose one brand over others in a category","definitionCN":"在某个品类里倾向于选择某一个品牌","example":"Brand preference survived the price rise for two years.","exampleCN":"涨价之后，品牌偏好仍维持了两年。","why":"If a name is preferred consistently across products, the preference has attached itself to the name.","whyCN":"如果一个名字在各种产品上都被一致地偏爱，这份偏好就已经附着在名字上了。"},{"no":"08","title":"A change in what buyers lean toward","titleCN":"偏好转变","definition":"a recorded shift in what buyers favour over time","definitionCN":"随着时间推移，买家所偏爱之物发生的可记录的移动","example":"The decade's biggest consumer preference was away from ownership.","exampleCN":"这十年最大的消费者偏好转变，是离开「拥有」。","why":"Preferences are stable but not fixed; tracking them turns a state into a movement.","whyCN":"偏好稳定却并不固定；追踪它就把一种状态变成了一段移动。"}],"etymology":{"intro":{"en":"Preference is a Latin noun built on ferre 'to carry'; with prae- 'before' it means 'placing something before something else'.","cn":"preference 是建立在 ferre「携带」之上的拉丁名词；加 prae-「在前」后，意思是「把某物放到另一物之前」。"},"items":[{"era":"LATIN FERRE","en":"Ferre meant 'to carry, to bear'. Its participle latus is irregular but widely used, and the root sits in transfer, offer and refer.","cn":"ferre 意为「携带、承载」。它的分词 latus 虽不规则却极常用，这个词根还出现在 transfer、offer 与 refer 里。"},{"era":"LATIN PRAEFERRE","en":"Prae- 'before, in front' plus ferre gave praeferre 'to place before, to put in front, hence to prefer'.","cn":"prae-「在前、在面前」加 ferre 构成 praeferre「放到前面、摆在前面，因而表示更偏爱」。"},{"era":"LATIN PRAEFERENTIA","en":"The noun praeferentia named the act of placing one thing before another; French préférence and English preference continue it.","cn":"名词 praeferentia 指「把一物置于另一物之前」的动作；法语 préférence 与英语 preference 是它的延续。"},{"era":"FOURTEENTH CENTURY","en":"English preference first meant the act of preferring or a prior claim, a sense still alive in 'preference shares'.","cn":"英语 preference 最初指「优先的行为」或「优先权」，这个义项至今活在 preference shares（优先股）里。"},{"era":"CONSUMER SENSE","en":"Consumer entered economics in the eighteenth century, and the pair consumer preference became standard once demand was studied as a sum of individual likings.","cn":"consumer 在十八世纪进入经济学；当需求被当作无数个人喜好的加总来研究时，consumer preference 这一组合成为标准说法。"},{"era":"MID-TWENTIETH CENTURY","en":"Marketing research separated stated preference from revealed preference, and both became routine measures of demand.","cn":"二十世纪中叶的市场研究把陈述性偏好与显示性偏好分开，两者都成了需求的常规测量。"}]},"similar":{"note":{"en":"Group one swaps or reshapes a half of the phrase; group two names neighbouring demand ideas.","cn":"第一组替换或改写短语的一半；第二组是相邻的需求概念。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"consumer preferences","ipa":"/kənˈsjuːmə ˈprefərənsɪz/","tag":"plural","definition":"The countable plural for several distinct likings; the singular names the general tendency.","definitionCN":"可数复数，指若干种不同的喜好；单数则指总体倾向。"},{"word":"consumer behavior","ipa":"/kənˈsjuːmə bɪˈheɪvjə/","tag":"acts, not likings","definition":"The acts of buying and using; a preference is the leaning behind those acts.","definitionCN":"购买与使用的动作；偏好是这些动作背后的倾向。"},{"word":"customer preference","ipa":"/ˈkʌstəmə ˈprefərəns/","tag":"narrower actor","definition":"The preference of those who already buy from a particular seller.","definitionCN":"已经向某个卖家购买的人的偏好。"},{"word":"preferential","ipa":"/ˌprefəˈrenʃl/","tag":"adjective","definition":"The adjective meaning 'giving an advantage', as in preferential treatment; it does not name a buyer's liking.","definitionCN":"形容词，意为「给予优待」，如 preferential treatment；它不指买家的喜好。"}]},{"heading":"NEAR MEANING","entries":[{"word":"demand","ipa":"/dɪˈmɑːnd/","tag":"aggregate","definition":"The total willingness to buy at a given price; preference is the individual leaning that produces it.","definitionCN":"在给定价格下愿意购买的总量；preference 是产生它的个体倾向。"},{"word":"taste","ipa":"/teɪst/","tag":"aesthetic","definition":"A sense of what is pleasing, usually about style or flavour rather than measurable choice.","definitionCN":"对何者悦人的判断力，通常关于风格或味道，而不是可测量的选择。"},{"word":"liking","ipa":"/ˈlaɪkɪŋ/","tag":"emotional","definition":"A plain fondness for something, without the comparative structure of choosing between options.","definitionCN":"对某物朴素的喜爱，不含「在选项间比较」的结构。"},{"word":"willingness to pay","ipa":"/ˈwɪlɪŋnəs tə peɪ/","tag":"money measure","definition":"The top price a buyer would accept; it turns a preference into a number.","definitionCN":"买家能接受的最高价；它把偏好变成一个数字。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin comparative structure and real research terms.","cn":"正常联想：真实的拉丁比较结构，加上真实的研究术语。"},"normal":[{"en":"prae- 'before' + ferre 'carry': to prefer is to carry one thing in front of another.","cn":"prae-「在前」加 ferre「携带」：偏爱就是把一件东西捧到另一件前面。"},{"en":"The family runs prefer, preference, preferential, preferred, preferably.","cn":"同族词包括 prefer、preference、preferential、preferred、preferably。"},{"en":"Fixed phrases show the trade: consumer preferences shift, match consumer preferences, a survey of consumer preferences.","cn":"固定搭配显示行业说法：消费者偏好转变、契合消费者偏好、消费者偏好调查。"},{"en":"Research splits preference in two: what people say and what their receipts show.","cn":"研究会把偏好分两半：人说的，和收据显示的。"},{"en":"The same ferre root sits in transfer, refer and offer.","cn":"同一个 ferre 词根还在 transfer、refer 与 offer 里。"}],"abstract":[{"en":"Picture two hands held out, and one of them closes first: the closing hand is the preference.","cn":"想象两只手伸出来，其中一只先合拢：先合拢的那只就是偏好。"},{"en":"A preference is always a relation, never a thing on its own.","cn":"偏好永远是一种关系，从不单独成物。"},{"en":"That is why it can be measured twice, once by asking and once by watching.","cn":"所以它可以被测量两次：一次靠问，一次靠看。"}]},"examples":[{"en":"Consumer preference for smaller cars followed the rise in fuel prices.","cn":"燃油价格上涨之后，消费者偏好转向更小的车。"},{"en":"The survey recorded stated preference, not revealed preference.","cn":"这项调查记录的是陈述性偏好，而不是显示性偏好。"},{"en":"Regional consumer preferences forced the chain to stock different menus.","cn":"地区性的消费偏好迫使这家连锁店备不同的菜单。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「康苏默-普瑞弗伦斯」——康苏默把偏爱的那件捧到前面（普瑞-弗），另一件就留在后面 → 消费者偏好","word":"consumer preference"},"root":"consumer 出自拉丁 consumere「用尽」；preference 出自拉丁 praeferre「放到前面」= prae-（在前）+ ferre「携带」。","sensesIntro":{"en":"Eight senses all perform one comparison: one thing is carried in front of another, whether the comparison is between products, ranks, receipts and words, flavours, prices, brands or whole decades.","cn":"八个义项都在做同一个比较：把一件东西捧到另一件前面——比较的对象可以是产品、名次、收据与说法、口味、价格、品牌，甚至整整十年。"},"semanticMap":{"core":{"en":"CORE IMAGE: two hands hold out two things, and the buyer closes on one.","cn":"核心意象：两只手各举一物，买家在其中一只上合拢手指。"},"chain":["CARRY BEFORE","LIKING","RANKING","REVEALED","STATED","SHIFT"],"branches":[{"senses":"01 · 02","en":"LEANING AND ORDER: one thing placed before another, or a whole list put in order of that placing.","cn":"倾向与次序：把一件摆到另一件之前，或把整张清单按这种摆放排好。"},{"senses":"03","en":"BY RECEIPT: what money actually chose, which speech cannot undo.","cn":"由收据证明：钱实际选了什么，话语改不回来。"},{"senses":"04","en":"BY ANSWER: what people say when asked, cheaply and sometimes untruthfully.","cn":"由回答显示：被问时说的，代价很低，有时并不真实。"},{"senses":"05 · 06","en":"SENSES AND MONEY: flavour and price band are two axes on which the same leaning is measured.","cn":"感官与金钱：味道与价位，是测量同一倾向的两条坐标。"},{"senses":"07 · 08","en":"NAME AND MOVEMENT: a leaning can attach to a brand, and the set of leanings can move over a decade.","cn":"名字与移动：倾向可以附着在品牌上，而整组倾向能在十年里移动。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin verb of using up with a Latin verb of carrying before; both roots build large English families.","cn":"这个短语把拉丁语「用尽」的动词与拉丁语「捧到前面」的动词连在一起；两个词根都构成庞大的英语词族。"},"latinIntro":{"en":"Consumere 'use up' and praeferre 'place before' are both Latin; preferre's ferre also gives transfer, refer and offer.","cn":"consumere「用尽」与 praeferre「置于前」都出自拉丁语；praeferre 的 ferre 还给了 transfer、refer 与 offer。"},"items":[{"word":"consumer","structure":"consume + -er","meaning":"one who uses goods","meaningCN":"使用货物的人","example":"Consumers compare two labels at once.","exampleCN":"消费者会同时比较两个标签。"},{"word":"consume","structure":"con- + sumere","meaning":"to use up","meaningCN":"用尽","example":"The city consumes more water each year.","exampleCN":"这座城市每年消耗更多水。"},{"word":"prefer","structure":"prae- + ferre","meaning":"to like one thing more","meaningCN":"更喜欢某一件","example":"Most buyers prefer glass to plastic.","exampleCN":"多数买家更喜欢玻璃而非塑料。"},{"word":"preference","structure":"prefer + -ence","meaning":"the state of liking one more","meaningCN":"更喜爱某一项的状态","example":"Her preference was clear from the receipt.","exampleCN":"从收据就能看出她的偏好。"},{"word":"preferential","structure":"preference + -ial","meaning":"giving an advantage","meaningCN":"给予优待的","example":"Members get preferential rates.","exampleCN":"会员享受优惠价。"},{"word":"preferred","structure":"prefer + -ed","meaning":"liked better","meaningCN":"更受偏爱的","example":"The preferred size sold out first.","exampleCN":"最受欢迎的尺寸最先售罄。"},{"word":"preferably","structure":"preferable + -ly","meaning":"if choice allows","meaningCN":"如可挑选的话","example":"Bring cash, preferably in small notes.","exampleCN":"带现金，最好是小面额。"},{"word":"fer / lat","structure":"ferre, latus (Latin root, 'carry')","meaning":"to carry","meaningCN":"携带","example":"The root appears in transfer and refer.","exampleCN":"这个词根出现在 transfer 与 refer 里。"},{"word":"consumer preference","structure":"consumer + preference","meaning":"the buyer's leaning","meaningCN":"买家的倾向","example":"Consumer preference moved to refills.","exampleCN":"消费者偏好转向了补充装。"}],"latinEntries":[{"word":"ferre","structure":"ferre, tuli, latum (verb, irregular)","meaning":"to carry, bear","meaningCN":"携带；承载"},{"word":"praeferre","structure":"prae- + ferre","meaning":"to place before, prefer","meaningCN":"放到前面；偏爱"},{"word":"praeferentia","structure":"noun from praeferent-","meaning":"a placing before","meaningCN":"置于前的动作"}],"derivatives":[{"word":"consumer","pos":"n.","zh":"消费者"},{"word":"prefer","pos":"v.","zh":"更偏爱"},{"word":"preference","pos":"n.","zh":"偏好；偏爱"},{"word":"preferential","pos":"adj.","zh":"优先的；优惠的"},{"word":"preferred","pos":"adj.","zh":"更受偏爱的"},{"word":"preferably","pos":"adv.","zh":"最好；更可取地"}]}},{"word":"customer","ipa_uk":"/ˈkʌstəmə/","ipa_us":"/ˈkʌstəmər/","definition_zh":"顾客；客户；老主顾；（口语）家伙","definition_en":"a person who buys goods or services from a shop, company or professional","core_image":"一个人第三次走进同一家店，店员不必问就报出他要的那样东西","scene":"同一个人第三次走进这家店，店员不必问就报出他要的那样东西。The customer paid without asking the price.","sceneCN":"同一个人第三次走进这家店，店员不必问就报出他要的那样东西；句中的这个词指「向某商家购买商品或服务的人」（第 1 个义项：付钱买东西的买家）。图中可辨识物件：柜台、常客的手、同一件商品、价目牌、收银机。","pos":[{"tag":"n.","zh":"顾客；客户（可数）"},{"tag":"n.","zh":"（口语）家伙、人（带形容词时，如 a tough customer）"}],"collocations":[{"phrase":"a regular customer","zh":"常客"},{"phrase":"customer service","zh":"客户服务"},{"phrase":"customer satisfaction","zh":"顾客满意度"},{"phrase":"a loyal customer","zh":"忠诚顾客"},{"phrase":"customer base","zh":"客户群"},{"phrase":"a tough customer","zh":"难对付的人"}],"forms":[{"label":"复数","form":"customers"},{"label":"名词（习惯；风俗；customs 海关）","form":"custom"},{"label":"形容词（惯常的；定制的）","form":"custom"},{"label":"形容词（面向客户的）","form":"customer-facing"},{"label":"相关名词（委托客户）","form":"client"}],"derivatives":[{"word":"custom","pos":"n.","zh":"习惯；风俗；海关"},{"word":"customary","pos":"adj.","zh":"惯常的；按习俗的"},{"word":"customer-facing","pos":"adj.","zh":"面向客户的"},{"word":"customize","pos":"v.","zh":"按需定制"},{"word":"client","pos":"n.","zh":"客户；委托人"}],"senses":[{"no":"01","title":"A person who buys from a seller","titleCN":"向卖家购买的人","definition":"a person who buys goods or services from a shop, company or professional","definitionCN":"向商店、公司或专业人士购买商品或服务的人","example":"The customer paid without asking the price.","exampleCN":"这位顾客没问价就付了钱。","why":"The word began as 'one who has the habit of coming to a place', and a buyer is simply someone who keeps coming back to buy.","whyCN":"这个词原指「习惯性来某处的人」，而买家就是那个反复回来买东西的人。"},{"no":"02","title":"A regular, long-standing buyer","titleCN":"常客、老主顾","definition":"a buyer who returns to the same seller repeatedly over time","definitionCN":"长期反复回到同一个卖家那里买东西的人","example":"The shop knows its customers by name.","exampleCN":"这家店叫得出老主顾的名字。","why":"Habit is still visible in this sense: the customer is defined by repeated visits, not by one purchase.","whyCN":"这个义项里「习惯」仍看得见：顾客是由反复到访定义的，而不是由一次购买定义的。"},{"no":"03","title":"The client of a service provider","titleCN":"服务提供者的客户","definition":"a person or organization that pays a firm or a professional for a service","definitionCN":"为某项服务向公司或专业人士付钱的人或机构","example":"Every customer of the bank has a named adviser.","exampleCN":"这家银行的每位客户都有一名指定顾问。","why":"Goods and services differ, but the relation is the same: one side pays, the other side supplies.","whyCN":"货物与服务不同，关系却一样：一边付钱，另一边提供。"},{"no":"04","title":"A difficult person, informally","titleCN":"（口语）难对付的人","definition":"in informal speech, a person who is hard to deal with, used with adjectives such as tough or awkward","definitionCN":"口语中与 tough、awkward 等形容词连用，指难以打交道的人","example":"The last caller was a tough customer.","exampleCN":"最后那个来电的人很难应付。","why":"The commercial word turned ironic: the person you must deal with is now simply a person, judged by how hard he is to handle.","whyCN":"这个商业词转成了反讽：你必须应对的那个人，如今只按「多难应付」来评判。"},{"no":"05","title":"A fellow, in casual speech","titleCN":"（口语）家伙、人","definition":"in casual British speech, a person of a particular sort, as in a rough customer","definitionCN":"英式口语中指某一类人，如 a rough customer（粗野的家伙）","example":"He looked a cool customer, never rattled.","exampleCN":"他看起来是个沉得住气的家伙，从不慌。","why":"Once the word can mean 'person to be dealt with', it spreads to any person being judged.","whyCN":"一旦这个词能表示「要应付的人」，它就可以扩展到任何被评判的人。"},{"no":"06","title":"One head counted in a shop's traffic","titleCN":"客源中的一位来客","definition":"one individual counted by a seller as a visit or a sale in a period","definitionCN":"卖家在一段时期内计为一次到访或一笔成交的单个来客","example":"The chain counts every customer twice if he buys twice.","exampleCN":"这位顾客若买两次，连锁店就把他计两次。","why":"Commerce counts bodies: the same habitual visitor becomes a unit in a ledger.","whyCN":"商业要数人头：同一个习惯性来客，在账本里成了一个单位。"},{"no":"07","title":"An internal customer inside a firm","titleCN":"内部客户（企业上下游部门）","definition":"in business usage, a colleague or department that receives work from another department","definitionCN":"商业用语中，接收另一部门交付成果的同事或部门","example":"The design team treats the sales desk as its customer.","exampleCN":"设计团队把销售台当作自己的内部客户。","why":"The supplying relation is copied inside the firm, so every receiving desk plays the buyer's part.","whyCN":"供应关系被复制到公司内部，于是每个接收成果的岗位都在扮演买家的角色。"},{"no":"08","title":"The user of a product, in broad business usage","titleCN":"用户（宽泛的商务说法）","definition":"in modern business speech, anyone who uses a product, even when the payer is someone else","definitionCN":"现代商务说法中指任何使用某产品的人，即使付钱的是别人","example":"The app has three million customers but only one payer.","exampleCN":"这个应用有三百万用户，却只有一个付钱方。","why":"The word stretches from buyer to user because firms care about the person at the end of the chain more than about the invoice.","whyCN":"这个词从买家延伸到使用者，因为企业更在乎链条末端的那个使用者，而不是那张发票。"}],"etymology":{"intro":{"en":"Customer is custom plus -er, and custom is a Latin word for habit. The buyer sense came from the habit of frequenting a place.","cn":"customer 是 custom 加 -er，而 custom 是拉丁语表示「习惯」的词。买家义来自「习惯性光顾某处」这个意思。"},"items":[{"era":"LATIN CONSUETUDO","en":"Consuetudo meant 'habit, custom', built on consuescere 'to become accustomed', from com- 'thoroughly' plus suescere 'to become used'.","cn":"consuetudo 意为「习惯、习俗」，由 consuescere「变得习惯」构成，即 com-「彻底」加 suescere「变得习以为常」。"},{"era":"OLD FRENCH COSTUME","en":"Old French costume carried the word into English as custom, first naming a habitual practice or a usual way of doing things.","cn":"古法语 costume 把这个词带入英语作 custom，最初指习惯性的做法或惯常的行事方式。"},{"era":"CUSTOM + -ER","en":"From the early fifteenth century customer named 'one who habitually frequents a place', roughly what English earlier called a habitué.","cn":"从十五世纪初，customer 指「习惯性常来某处的人」，大致相当于英语早先说的常客。"},{"era":"COMMERCIAL SENSE","en":"By the seventeenth and eighteenth centuries the word settled on the buyer who comes back to a shop, and the trading sense pushed the older one aside.","cn":"到十七、十八世纪，这个词落在「反复回到某店购物的买家」上，商业义把旧义挤到一边。"},{"era":"IDIOMATIC SENSE","en":"The ironic use for a person who must be dealt with, as in a tough customer, appears in colloquial English and survives mainly with adjectives.","cn":"反讽地指「必须应付的人」（如 a tough customer）出现在口语英语里，如今主要与形容词连用。"},{"era":"MODERN ENGLISH","en":"Twentieth-century business added customer service, customer base and the internal customer, and the word now reaches users who never pay.","cn":"二十世纪的商业又添上客户服务、客户群与内部客户等说法，这个词如今也指从不付钱的使用者。"}]},"similar":{"note":{"en":"Group one shares the habit root or a near spelling; group two names the roles on either side of a sale.","cn":"第一组共享「习惯」词根或拼写相近；第二组是交易两侧的角色。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"custom","ipa":"/ˈkʌstəm/","tag":"the base noun","definition":"The noun of habit or usual practice, and in the plural the duties collected at a border. It is the stem, not the person.","definitionCN":"表示习惯或惯常做法的名词，复数还指在边境征收的关税。它是词干，不是那个人。"},{"word":"customary","ipa":"/ˈkʌstəməri/","tag":"adjective","definition":"Usual, according to habit; the ending -ary marks an adjective, not a buyer.","definitionCN":"惯常的、按习俗的；-ary 结尾标示形容词，不是买家。"},{"word":"client","ipa":"/ˈklaɪənt/","tag":"different root","definition":"A customer of professional services, from Latin cliens 'dependent follower'; the two words are not related at the root.","definitionCN":"专业服务的客户，出自拉丁 cliens「依附的跟随者」；这两个词在词根上并无关联。"},{"word":"costumer","ipa":"/ˈkɒstjuːmə/","tag":"one letter apart","definition":"A maker or supplier of costumes for theatre; the single letter u changes the whole word and the whole trade.","definitionCN":"为戏剧制作或供应戏服的人；只差一个字母 u，整词与整个行当都变了。"}]},{"heading":"NEAR MEANING","entries":[{"word":"buyer","ipa":"/ˈbaɪə/","tag":"plain act","definition":"Anyone who buys, including a professional purchasing agent; it names the act rather than the relationship.","definitionCN":"任何买东西的人，也包括职业采购员；它命名动作，而不是关系。"},{"word":"consumer","ipa":"/kənˈsjuːmə/","tag":"user, not payer","definition":"The end user of goods, who may not be the person who paid for them.","definitionCN":"货物的最终使用者，未必是付钱的人。"},{"word":"patron","ipa":"/ˈpeɪtrən/","tag":"supporting regular","definition":"A regular supporter or client of a shop, hotel or arts institution; it carries a tone of loyalty and sometimes of money given.","definitionCN":"商店、旅馆或艺术机构的常客与支持者；带忠诚的意味，有时也含出钱的意味。"},{"word":"shopper","ipa":"/ˈʃɒpə/","tag":"in the act of looking","definition":"A person going round shops looking for goods; the word marks the browsing stage rather than a settled buyer.","definitionCN":"在各家店里转着找东西的人；这个词标的是浏览阶段，而不是已成交的买家。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real habit word plus a real agent suffix.","cn":"正常联想：真实的「习惯」词加上真实的施事后缀。"},"normal":[{"en":"custom 'habit' + -er: the buyer is the one in the habit of coming back.","cn":"custom「习惯」加 -er：买家就是那个养成「回来」习惯的人。"},{"en":"Fixed phrases mark the trade: customer service, customer base, customer satisfaction.","cn":"固定搭配标出行业：客户服务、客户群、顾客满意度。"},{"en":"The idioms keep the old irony: a tough customer, a cool customer.","cn":"习语保留了旧的反讽：难对付的人、沉得住气的家伙。"},{"en":"Do not confuse it with costumer: one buys, the other makes costumes.","cn":"别和 costumer 混：一个买东西，一个做戏服。"},{"en":"Latin consuetudo 'habit' is the ancestor of both custom and costume.","cn":"拉丁 consuetudo「习惯」是 custom 与 costume 的共同祖先。"}],"abstract":[{"en":"Picture a worn path from one door to a shop counter: the path is the word.","cn":"想象一条从自家门口磨到店柜台的小径：这条小径就是这个词。"},{"en":"A single visit makes a buyer; only repetition makes a customer.","cn":"一次到访只造出一个买家；只有重复才造出一个顾客。"},{"en":"That is why the word can later mean anyone you must deal with: repetition is a relationship.","cn":"所以这个词后来能指任何你必须应付的人：重复本身就是一种关系。"}]},"examples":[{"en":"The bakery's oldest customer has come every morning for forty years.","cn":"这家面包店最老的顾客连续四十年每天早上都来。"},{"en":"Customer service answered within a minute.","cn":"客户服务一分钟内就回应了。"},{"en":"The negotiator described the other side as a tough customer.","cn":"谈判者把对方称为难对付的人。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「卡斯特默」——卡斯特（常客）默默地把钱放在柜台上，一次又一次 → customer 顾客","word":"customer"},"root":"custom「习惯、惯例」+ -er（施事后缀）；custom 经古法语 costume 出自拉丁 consuetudo「习惯」= com- + suescere「习以为常」。","sensesIntro":{"en":"Eight senses grow from one idea: a person in the habit of coming to a place. The habit makes a buyer, then a client, then a counted unit, and finally any person one has to deal with.","cn":"八个义项都从一个意思长出来：一个养成了「来某处」习惯的人。这个习惯先造出买家，再造成客户、记账单位，最后变成任何你必须应付的人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a worn path between one door and one counter.","cn":"核心意象：一道门与一个柜台之间被磨出的小径。"},"chain":["HABITUÉ","PATRON","BUYER","REGULAR","TOUGH PERSON","INTERNAL CLIENT"],"branches":[{"senses":"01 · 03","en":"GOODS AND SERVICES: buying a thing and paying for a service make the same relationship.","cn":"货物与服务：买东西与买服务建立的是同一种关系。"},{"senses":"02 · 06","en":"REPETITION: the habitual visitor is also the unit a shop counts.","cn":"重复：习惯性来客同时也是商店计数的那个单位。"},{"senses":"04 · 05","en":"IRONY: the person you must deal with takes the trader's word for a customer.","cn":"反讽：你必须应付的人，借用了商人称顾客的那个词。"},{"senses":"07","en":"INSIDE THE FIRM: one department plays buyer to another.","cn":"公司内部：一个部门对另一个部门扮演买家。"},{"senses":"08","en":"STRETCHED TO USERS: the word reaches the person who uses without paying.","cn":"延伸到使用者：这个词触到了只用不付的那一端。"}]},"affixes":{"intro":{"en":"Customer is a Latin-derived noun stem plus a native agent suffix, and the stem has its own large family.","cn":"customer 是一个拉丁来源的名词词干加本土施事后缀，而这个词干自有庞大的词族。"},"latinIntro":{"en":"Latin consuetudo 'habit' gives custom, costume and customary; suescere 'become used' is the verb inside it.","cn":"拉丁 consuetudo「习惯」给了 custom、costume 与 customary；其中的动词是 suescere「变得习以为常」。"},"items":[{"word":"custom","structure":"custom (noun from Old French costume)","meaning":"a habitual practice","meaningCN":"习惯性的做法","example":"It is the custom to pay on delivery.","exampleCN":"货到付款是这里的惯例。"},{"word":"-er","structure":"-er (agent suffix)","meaning":"one who does or is something","meaningCN":"做某事或属于某类的人","example":"The suffix marks the person.","exampleCN":"这个后缀标出那个人。"},{"word":"customer","structure":"custom + -er","meaning":"one who habitually comes to buy","meaningCN":"习惯性来买东西的人","example":"Customers queue before opening.","exampleCN":"顾客在开门前排队。"},{"word":"customary","structure":"custom + -ary","meaning":"according to habit","meaningCN":"按习惯的","example":"A customary tip is ten per cent.","exampleCN":"惯常的小费是一成。"},{"word":"costume","structure":"costume (same Latin source)","meaning":"clothing for a role or period","meaningCN":"角色或某时代的服装","example":"The costume was borrowed for the play.","exampleCN":"这套戏服是为这部剧借来的。"},{"word":"customize","structure":"custom + -ize","meaning":"to make to a buyer's wish","meaningCN":"按买家要求制作","example":"They customize the seats.","exampleCN":"他们按需定制座椅。"},{"word":"client","structure":"client (Latin cliens)","meaning":"a customer of a professional","meaningCN":"专业人士的客户","example":"The lawyer met her client at noon.","exampleCN":"律师中午见了客户。"},{"word":"customs","structure":"custom (plural, habitual toll)","meaning":"border duties on goods","meaningCN":"对货物征收的边境税","example":"Customs held the parcel for a day.","exampleCN":"海关扣了包裹一天。"}],"latinEntries":[{"word":"consuetudo","structure":"consuetudo, consuetudinis (noun, third declension)","meaning":"habit, custom","meaningCN":"习惯；惯例"},{"word":"consuescere","structure":"com- + suescere","meaning":"to become accustomed","meaningCN":"变得习惯"},{"word":"suescere","structure":"suescere (verb, inceptive)","meaning":"to become used to","meaningCN":"逐渐习惯"}],"derivatives":[{"word":"custom","pos":"n.","zh":"习惯；风俗；海关"},{"word":"customary","pos":"adj.","zh":"惯常的；按习俗的"},{"word":"customer-facing","pos":"adj.","zh":"面向客户的"},{"word":"customize","pos":"v.","zh":"按需定制"},{"word":"client","pos":"n.","zh":"客户；委托人"}]}},{"word":"clientele","ipa_uk":"/ˌkliːənˈtel/","ipa_us":"/ˌkliːənˈtel/","definition_zh":"客户群；顾客总称；（律师等的）委托人群体","definition_en":"the body of clients or customers that a business, professional or institution serves","core_image":"一家小店的门口，几张熟悉的面孔按同样的顺序在同一个时间出现","scene":"小店门口，几张熟悉的面孔在同一个时间按同样的顺序出现。The clientele of the small hotel returns every August.","sceneCN":"小店门口，几张熟悉的面孔在同一个时间按同样的顺序出现；句中的这个词指「某机构所服务的顾客总体」（第 1 个义项：把许多客户当作一个整体来看的集合）。图中可辨识物件：店门、几张熟悉的面孔、固定的时刻、门牌、登记簿。","pos":[{"tag":"n.","zh":"客户群；顾客总称（集合名词，不可数）"},{"tag":"n.","zh":"（律师、医生等的）委托人群体"}],"collocations":[{"phrase":"a loyal clientele","zh":"忠实的客户群"},{"phrase":"a wealthy clientele","zh":"富裕的客户群"},{"phrase":"build a clientele","zh":"建立客户群"},{"phrase":"the hotel's clientele","zh":"这家旅馆的客源"},{"phrase":"a local clientele","zh":"本地客源"},{"phrase":"attract a younger clientele","zh":"吸引更年轻的客源"}],"forms":[{"label":"复数（少见，指多类客户群）","form":"clienteles"},{"label":"组成名词（单个客户）","form":"client"},{"label":"相关名词（委托关系）","form":"clientage"},{"label":"相关说法（客户基础）","form":"client base"},{"label":"相关形容词（客户侧的）","form":"client-side"}],"derivatives":[{"word":"client","pos":"n.","zh":"客户；委托人"},{"word":"clientage","pos":"n.","zh":"委托关系；全体委托人群"},{"word":"clientelism","pos":"n.","zh":"庇护主义（政治学术语）"},{"word":"client base","pos":"n.","zh":"客户基础"},{"word":"client-side","pos":"adj.","zh":"客户端的"}],"senses":[{"no":"01","title":"The whole body of customers","titleCN":"客户群总称","definition":"the body of clients or customers that a business, professional or institution serves","definitionCN":"某个商家、专业人士或机构所服务的客户总体","example":"The clientele of the small hotel returns every August.","exampleCN":"这家小旅馆的客源每年八月都会回来。","why":"The Latin noun named the whole group of dependants, not one dependant, so English took it as a collective.","whyCN":"这个拉丁名词指的是依附者的整体，而不是某一个依附者，所以英语把它当作集合名词接收。"},{"no":"02","title":"The clients of a professional","titleCN":"律师、会计师等的委托人群","definition":"the people or firms who pay a professional for advice or representation","definitionCN":"为获得建议或代理而向专业人士付钱的人或公司","example":"His clientele is mostly small family firms.","exampleCN":"他的委托人大多是小型家族企业。","why":"A professional's practice is measured by the group of people who rely on him, and that group is the clientele.","whyCN":"一位专业人士的业务，是用依赖他的那群人来衡量的，而那群人就是 clientele。"},{"no":"03","title":"The trade of a restaurant or hotel","titleCN":"餐厅或旅馆的客源","definition":"the customers who regularly use a place of hospitality","definitionCN":"经常光顾某家餐饮或住宿场所的顾客","example":"The restaurant changed its clientele when it moved uptown.","exampleCN":"餐厅搬到上城后，客源换了。","why":"A place has a character, and its clientele is the group that character attracts.","whyCN":"一个场所自有一种性格，而它的 clientele 就是被这种性格吸引来的那群人。"},{"no":"04","title":"A group of habitual returners","titleCN":"常客群","definition":"the customers who come back again and again, seen as a group","definitionCN":"反复回来的那些顾客，被当作一个群体来看","example":"Decades of work built a clientele that never moved away.","exampleCN":"几十年的经营养出了一群从不离开的常客。","why":"Collective naming hides the individual: what matters is the pattern of return, not any one person.","whyCN":"集合命名抹掉了个人：要紧的是「回来」这个模式，而不是任何一个人。"},{"no":"05","title":"A wealthy or select group","titleCN":"高端客源","definition":"a clientele of high income or high status, often used as a selling point","definitionCN":"收入高或身份高的客源，常用作卖点","example":"The jeweller's clientele includes three royal families.","exampleCN":"这家珠宝店的客户里有三个王室。","why":"When a group is named collectively, it can be graded, and the grade becomes part of the shop's image.","whyCN":"一群人被集合命名之后就可以被分级，而这个等级又成了店铺形象的一部分。"},{"no":"06","title":"The customer base a firm depends on","titleCN":"客户基础","definition":"the total group whose custom keeps a business going","definitionCN":"靠其惠顾维持生意的整个群体","example":"Losing half its clientele closed the clinic within a year.","exampleCN":"失去一半客户后，这家诊所一年内就关门了。","why":"A collective noun can be treated as an asset: the group is what the business owns and can lose.","whyCN":"集合名词可以被当作资产：这群人就是企业拥有、也可能失去的东西。"},{"no":"07","title":"The make-up of a customer group","titleCN":"客源结构","definition":"the composition of a customer group by age, income, place or type","definitionCN":"客户群体按年龄、收入、地域或类型形成的构成","example":"The bar's clientele is now two thirds students.","exampleCN":"这家酒吧的客源现在三分之二是学生。","why":"Once a group is counted, it can be broken into parts, and the parts describe the whole.","whyCN":"一群人被计数之后就能拆成几部分，而这几部分又描述了整体。"},{"no":"08","title":"The patients or users of an institution","titleCN":"就诊或受助对象群体","definition":"the group served by a clinic, a charity or a public institution","definitionCN":"由诊所、慈善机构或公共机构所服务的那群人","example":"The clinic's clientele has grown older every year.","exampleCN":"这家诊所的就诊人群逐年变老。","why":"Service institutions also have dependants, and the old Latin word fits them as well as shops.","whyCN":"服务机构同样有依附者，这个古老的拉丁词用在它们身上和用在商店身上一样合适。"}],"etymology":{"intro":{"en":"Clientele is the collective of client: Latin clientela, the whole body of dependants, borrowed through French.","cn":"clientele 是 client 的集合形式：拉丁 clientela 指依附者的整体，经法语借入英语。"},"items":[{"era":"LATIN CLUERE","en":"Client comes from cliens, the present participle of cluere 'to hear, to listen, to obey'. The deeper origin of cluere is uncertain; it is generally considered related to a reconstructed root for hearing.","cn":"client 出自 cliens，即 cluere「听、听从、服从」的现在分词。cluere 的更早来源不确定，一般认为与一个重构的「听」词根相关。"},{"era":"LATIN CLIENS","en":"In Roman society a cliens was a dependent who owed loyalty and services to a patron, and who in return received protection and support. The plural is clientes.","cn":"在罗马社会，cliens 是依附于庇护人的从属者，对庇护人负有忠诚与服务之责，作为回报获得保护与支持。复数是 clientes。"},{"era":"LATIN CLIENTELA","en":"Clientela named the whole condition and body of such dependants, the patronage relationship and the group itself.","cn":"clientela 指这些依附者的整体状况与群体，也指庇护关系本身。"},{"era":"FRENCH CLIENTÈLE","en":"French clientèle kept the collective sense and passed it into English in the eighteenth century.","cn":"法语 clientèle 保留了集合义，并在十八世纪把它传入英语。"},{"era":"COMMERCIAL SENSE","en":"English applied the word to the customers of a shop or a hotel, so that a group of buyers inherited the tone of dependants.","cn":"英语把这个词用于商店或旅馆的顾客，于是一群买家继承了「依附者」的语气。"},{"era":"MODERN ENGLISH","en":"The word now names a customer group as an asset or a market segment, and it survives in political science as clientelism.","cn":"这个词如今把客户群当作资产或市场细分来命名，并在政治学里以 clientelism（庇护主义）的形式留存。"}]},"similar":{"note":{"en":"Group one shares the client root; group two names related collections of buyers.","cn":"第一组共享 client 词根；第二组是相关的买家集合。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"client","ipa":"/ˈklaɪənt/","tag":"singular","definition":"One customer or principal. Clientele is the whole group, so it cannot be counted with numbers.","definitionCN":"单个客户或委托人。clientele 是整群，所以不能用数字直接数。"},{"word":"clientage","ipa":"/ˈklaɪəntɪdʒ/","tag":"the relationship","definition":"The state of being a client, or the relation of dependence; it names the bond rather than the group.","definitionCN":"作为客户的身份，或依附关系；它命名的是那层纽带，而不是群体。"},{"word":"clientelism","ipa":"/ˌkliːənˈtelɪzəm/","tag":"political term","definition":"A political system that trades favours for loyalty; it shares the root but belongs to politics, not retail.","definitionCN":"以恩惠换取忠诚的政治体制；共享词根，但属于政治而非零售。"},{"word":"clientele's","ipa":"/ˌkliːənˈtelz/","tag":"possessive","definition":"The possessive form, as in the clientele's tastes. It is a grammar form, not a different word.","definitionCN":"所有格形式，如 clientele's tastes。它是语法形式，不是另一个词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"customer base","ipa":"/ˈkʌstəmə beɪs/","tag":"business term","definition":"The countable business phrase for the whole set of buyers; clientele is the same idea in older, more formal dress.","definitionCN":"商业里指全部买家的可数说法；clientele 是同一想法的更古老、更正式的说法。"},{"word":"customers","ipa":"/ˈkʌstəməz/","tag":"countable","definition":"Individual buyers counted one by one; clientele treats them as one body.","definitionCN":"一个一个数的个体买家；clientele 把他们当作一个整体。"},{"word":"following","ipa":"/ˈfɒləʊɪŋ/","tag":"loyal audience","definition":"A group that follows a person, brand or programme; it stresses devotion rather than paying.","definitionCN":"追随某人、品牌或节目的一群人；强调忠诚，而非付钱。"},{"word":"patronage","ipa":"/ˈpætrənɪdʒ/","tag":"support, often money","definition":"The support a patron gives, or the custom of patrons as a body; it stresses the giving side.","definitionCN":"庇护者给予的支持，或庇护者全体的惠顾；强调给予的一方。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: one Latin collective noun, one French spelling, one clear grammar.","cn":"正常联想：一个拉丁集合名词、一个法语拼写、一条清楚的语法。"},"normal":[{"en":"client + -ele, from Latin clientela: the group, not the one.","cn":"client 加 -ele，出自拉丁 clientela：指群体，不指单个。"},{"en":"The client root means 'one who listens and obeys', and a clientele is a whole body of such listeners.","cn":"client 词根意为「听从、服从的人」，而 clientele 是这样一群人的整体。"},{"en":"Fixed phrases show the group: a loyal clientele, a wealthy clientele, build a clientele.","cn":"固定搭配显示「群」：忠实的客户群、富裕的客户群、建立客户群。"},{"en":"French clientèle explains the spelling: -èle, not the English -el.","cn":"法语 clientèle 解释了拼写：是 -èle，不是英语的 -el。"},{"en":"The political cousin clientelism keeps the same dependant picture.","cn":"政治上的近亲 clientelism 保留了同一幅「依附」画面。"}],"abstract":[{"en":"Picture a queue at one door where every face is familiar: the queue is the clientele.","cn":"想象一道门前排队，每张脸都熟悉：这支队伍就是 clientele。"},{"en":"A client is a thread; the clientele is the cloth woven from those threads.","cn":"一个 client 是一根线；clientele 是用这些线织成的布。"},{"en":"Because it is cloth, it can be measured, graded, lost and replaced.","cn":"正因为它是布，它可以被衡量、分级、失去、替换。"}]},"examples":[{"en":"The bookshop built its clientele through forty years of school orders.","cn":"这家书店靠四十年的学校订单建立了客户群。"},{"en":"A younger clientele now fills the bar on weeknights.","cn":"如今工作日的晚上，酒吧里坐满更年轻的客源。"},{"en":"The firm's clientele includes several city governments.","cn":"这家公司的客户里有好几个市政府。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「克利恩-泰尔」——克利恩们一排排站在泰尔（柜台）前，就是一群人 → clientele 客户群","word":"clientele"},"root":"法语 clientèle，出自拉丁 clientela「依附者群体」；其词根 cliens 出自动词 cluere「听、听从」。","sensesIntro":{"en":"Eight senses all look at buyers as one body: a shop's trade, a professional's dependants, a hotel's regulars, a loyal circle, a select circle, an asset, a structure and an institution's served group.","cn":"八个义项都把买家当作一个整体来看：一家商店的客源、一位专业人士的委托人、一家旅馆的常客、一个忠实圈子、一个高端圈子、一项资产、一种结构，以及一个机构的受助群体。"},"semanticMap":{"core":{"en":"CORE IMAGE: a familiar queue at one door.","cn":"核心意象：一道门前一支熟悉的面孔排成的队。"},"chain":["LEAN ON","DEPENDENT","PATRON","GROUP","BASE","SEGMENT"],"branches":[{"senses":"01 · 06","en":"GROUP AND ASSET: the same body can be described as a set of people or as what a business owns.","cn":"群体与资产：同一群人既可被描述为一群人，也可被描述为企业拥有的东西。"},{"senses":"02 · 08","en":"DEPENDANTS: the Roman follower survives in the professional's clients and in the institution's patients.","cn":"依附者：罗马的从属者活在专业人士的委托人与机构的就诊者身上。"},{"senses":"03","en":"PLACE: a restaurant's character selects its trade.","cn":"场所：一家餐厅的性格筛出了它的客源。"},{"senses":"04","en":"RETURN: loyalty exists only as repetition.","cn":"回头：忠诚只以重复的形式存在。"},{"senses":"05 · 07","en":"GRADE AND COMPOSITION: a collective can be valued and also broken into parts.","cn":"等级与构成：一个集合体既能被估值，也能被拆成几部分。"}]},"affixes":{"intro":{"en":"Clientele is the Latin collective of client, borrowed whole through French, so it adds no English suffix of its own.","cn":"clientele 是 client 的拉丁集合形式，整体经法语借入，因此自身不带英语后缀。"},"latinIntro":{"en":"Latin cliens 'listener, dependant' and clientela 'body of dependants' both come from cluere 'to hear, obey'; the deeper origin of cluere is uncertain.","cn":"拉丁 cliens「听从者、依附者」与 clientela「依附者群体」都出自 cluere「听、服从」；cluere 的更早来源不确定。"},"items":[{"word":"client","structure":"client (from Latin cliens)","meaning":"one who pays for a service","meaningCN":"为服务付钱的人","example":"The client signed the letter.","exampleCN":"客户签了这封信。"},{"word":"clientele","structure":"client + -ele (Latin collective)","meaning":"the whole group of clients","meaningCN":"客户的整体","example":"The clientele stayed loyal for decades.","exampleCN":"客户群几十年保持忠诚。"},{"word":"clientage","structure":"client + -age","meaning":"the relation of dependence","meaningCN":"依附关系","example":"Clientage bound him to one patron.","exampleCN":"依附关系把他绑在一位庇护人身上。"},{"word":"clientelism","structure":"clientele + -ism","meaning":"politics of traded favours","meaningCN":"以恩惠交换忠诚的政治","example":"Clientelism weakened the civil service.","exampleCN":"庇护主义削弱了文官体系。"},{"word":"cluere","structure":"cluere (Latin verb, 'to hear, obey')","meaning":"to listen and obey","meaningCN":"听从；服从","example":"The verb describes a follower's duty.","exampleCN":"这个动词描述跟随者的义务。"},{"word":"cliens","structure":"cliens, clientis (Latin noun)","meaning":"a dependant, a follower","meaningCN":"依附者；跟随者","example":"A cliens owed service to a patron.","exampleCN":"依附者对庇护人负有服务之责。"},{"word":"client base","structure":"client + base","meaning":"the customers a firm relies on","meaningCN":"企业赖以生存的客户","example":"The client base grew by a third.","exampleCN":"客户基础增长了三分之一。"},{"word":"client-side","structure":"client + side","meaning":"running on the user's machine","meaningCN":"在用户机器上运行的","example":"The client-side code loads first.","exampleCN":"客户端代码先加载。"}],"latinEntries":[{"word":"cluere","structure":"cluere (verb, second conjugation)","meaning":"to hear, listen, obey","meaningCN":"听；听从；服从"},{"word":"cliens","structure":"cliens, clientis (noun, third declension)","meaning":"a dependant follower","meaningCN":"依附的跟随者"},{"word":"clientela","structure":"clientela (noun, first declension)","meaning":"the body of dependants, patronage","meaningCN":"依附者群体；庇护关系"}],"derivatives":[{"word":"client","pos":"n.","zh":"客户；委托人"},{"word":"clientage","pos":"n.","zh":"委托关系；全体委托人群"},{"word":"clientelism","pos":"n.","zh":"庇护主义"},{"word":"client base","pos":"n.","zh":"客户基础"},{"word":"client-side","pos":"adj.","zh":"客户端的"}]}},{"word":"client","ipa_uk":"/ˈklaɪənt/","ipa_us":"/ˈklaɪənt/","definition_zh":"客户；委托人；（计算机）客户端；当事人","definition_en":"a person or organization that pays a professional or a firm for advice, service or representation","core_image":"桌子两边各坐一人，一边推过文件，另一边付了钱并签下名字","scene":"桌子两边各坐一人，一边把文件推过去，另一边读完才签下名字。The client read the contract twice before signing.","sceneCN":"桌子两边各坐一人，一边把文件推过去，另一边读完才签下名字；句中的这个词指「付费获得专业服务的客户」（第 1 个义项：为建议、服务或代理向专业人士付钱的一方）。图中可辨识物件：桌子、文件、笔、签名处、茶杯。","pos":[{"tag":"n.","zh":"客户；委托人（可数）"},{"tag":"n.","zh":"顾客（较正式，指购买服务者）"},{"tag":"n.","zh":"（计算机）客户端（可数）"},{"tag":"n.","zh":"（法律）当事人；委托人"}],"collocations":[{"phrase":"a client meeting","zh":"客户会议"},{"phrase":"advise a client","zh":"为客户提供建议"},{"phrase":"client confidentiality","zh":"客户保密义务"},{"phrase":"a prospective client","zh":"潜在客户"},{"phrase":"client-server architecture","zh":"客户端—服务器架构"},{"phrase":"the client's brief","zh":"客户的需求说明"}],"forms":[{"label":"复数","form":"clients"},{"label":"名词（客户群）","form":"clientele"},{"label":"名词（委托关系）","form":"clientage"},{"label":"形容词（客户端的）","form":"client-side"},{"label":"相关名词（客户基础）","form":"client base"}],"derivatives":[{"word":"clientele","pos":"n.","zh":"客户群；委托人群"},{"word":"clientage","pos":"n.","zh":"委托关系"},{"word":"clientelism","pos":"n.","zh":"庇护主义"},{"word":"client-side","pos":"adj.","zh":"客户端的"},{"word":"clientship","pos":"n.","zh":"客户身份"}],"senses":[{"no":"01","title":"A payer of professional services","titleCN":"付费获得专业服务的人","definition":"a person or organization that pays a professional for advice, service or representation","definitionCN":"为获得建议、服务或代理而向专业人士付钱的人或机构","example":"The client read the contract twice before signing.","exampleCN":"委托人把合同读了两遍才签字。","why":"The Latin word names a dependant who listens to a patron; in modern use the dependence is commercial, and the listening is advice taken.","whyCN":"这个拉丁词指听从庇护人的依附者；现代用法里依附变成了商业关系，而「听」变成了接受建议。"},{"no":"02","title":"A customer, more formally","titleCN":"顾客（较正式的说法）","definition":"a buyer of a firm's services, used where customer would sound too retail","definitionCN":"某公司服务的购买者，用在 customer 显得过于零售的场合","example":"Each client of the agency keeps one account manager.","exampleCN":"代理公司的每位客户都配一名客户经理。","why":"The two words overlap, but client carries service, discretion and a continuing relationship.","whyCN":"两个词有重叠，但 client 带有「服务、保密、持续关系」的意味。"},{"no":"03","title":"The requesting side in computing","titleCN":"（计算机）客户端","definition":"a program or device that requests data or services from a server","definitionCN":"向服务器请求数据或服务的程序或设备","example":"The client sends a request and waits for the reply.","exampleCN":"客户端发出请求，然后等待回应。","why":"The same dependant relation was borrowed by computing: one side asks, the other side serves.","whyCN":"计算机借用了同一套依附关系：一侧提出请求，另一侧负责服务。"},{"no":"04","title":"The principal in a legal matter","titleCN":"（法律）当事人、委托人","definition":"the person or party a lawyer acts for in a case","definitionCN":"律师在某案件中代理的人或一方","example":"Counsel may not act against a former client.","exampleCN":"律师不得做出不利于前委托人的事。","why":"Law keeps the oldest shape: one party relies on another's knowledge and speaks through him.","whyCN":"法律保留了最古老的形状：一方依赖另一方的知识，并通过他说话。"},{"no":"05","title":"A long-standing customer of a firm","titleCN":"老客户","definition":"a buyer who has stayed with the same firm over many years","definitionCN":"多年来一直留在同一家公司购买的买家","example":"The firm keeps its oldest clients on the same terms.","exampleCN":"公司让最老的客户仍按原来的条件合作。","why":"A continuing relation is the point of the word, so duration turns a client into a fixture.","whyCN":"「持续关系」正是这个词的要害，所以时间一长，客户就成了固定陈设。"},{"no":"06","title":"A dependant in Roman society","titleCN":"（历史）古罗马的依附平民","definition":"in Roman history, a plebeian who depended on a patrician patron for protection and support","definitionCN":"罗马史中依附于贵族庇护人、以换取保护与支持的平民","example":"In the Republic a client owed his patron daily attendance.","exampleCN":"在共和国时期，依附者须每日到庇护人处请安。","why":"This is the literal origin: dependence on a protector, from which every later sense borrows its shape.","whyCN":"这是字面本义：对保护者的依附，后来每个义项都借用这个形状。"},{"no":"07","title":"The paying party for an agency","titleCN":"（广告、设计公司的）甲方客户","definition":"the firm that commissions work from an agency and approves what is produced","definitionCN":"委托代理公司做事并审定成果的企业","example":"The client rejected the third version of the poster.","exampleCN":"客户否掉了海报的第三版。","why":"An agency's dependence is total: the client holds both the money and the final yes.","whyCN":"代理公司的依附是彻底的：客户既握着钱，也握着最后的那个「行」。"},{"no":"08","title":"A person served by a welfare body","titleCN":"（社会服务机构的）受助者","definition":"a person receiving support from a social service, clinic or charity","definitionCN":"从社会服务机构、诊所或慈善组织获得支持的人","example":"Social workers now record each client's own goals.","exampleCN":"社工如今记录每位受助者自己的目标。","why":"Care work also runs on reliance, so the service language of client spread from law and business into welfare.","whyCN":"照护工作同样建立在依赖之上，于是 client 这套服务语言从法律与商业扩散到了福利领域。"}],"etymology":{"intro":{"en":"Client is Latin cliens 'a dependant who listens', a word of Roman social life before it was a word of trade.","cn":"client 是拉丁 cliens「听从的依附者」，它先是罗马社会生活的词，后来才是商业的词。"},"items":[{"era":"LATIN CLUERE","en":"Cluere meant 'to hear, to listen, to obey'. Its deeper origin is uncertain; it is generally considered related to a reconstructed root for hearing, but the exact path is not demonstrated.","cn":"cluere 意为「听、听从、服从」。它的更早来源不确定，一般认为与一个重构的「听」词根相关，但确切路径未被证明。"},{"era":"LATIN CLIENS","en":"Clines, clientis was the present participle of cluere, naming the one who listens: a dependant attached to a patron.","cn":"cliens、clientis 是 cluere 的现在分词，指「听从的那个人」：依附于庇护人的从属者。"},{"era":"ROMAN SOCIETY","en":"A client owed his patron morning attendance, political support and sometimes money; the patron owed protection, legal help and food. The bond was moral before it was commercial.","cn":"依附者对庇护人负有清晨请安、政治支持乃至金钱之责；庇护人则负保护、法律帮助与食物之责。这层纽带先是道德的，后来才是商业的。"},{"era":"FRENCH AND ENGLISH","en":"Through French the word entered English in the fourteenth century, first for one who employs a lawyer or an adviser.","cn":"经法语，这个词在十四世纪进入英语，最初指雇佣律师或顾问的人。"},{"era":"COMMERCIAL WIDENING","en":"From the eighteenth and nineteenth centuries client spread from law to banking, agencies and any paid service, while customer kept the shop.","cn":"从十八、十九世纪起，client 从法律扩展到银行、代理公司与各类付费服务，而 customer 留在店铺里。"},{"era":"COMPUTING","en":"In the late twentieth century the client-server model reused the word for the side that asks and the side that serves.","cn":"二十世纪后期，客户端—服务器模型把这个词再次用于「提出请求的一侧」与「提供服务的一侧」。"}]},"similar":{"note":{"en":"Group one shares the root or the shape; group two names other parties in a service relationship.","cn":"第一组共享词根或形状；第二组是服务关系里的其他各方。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"clientele","ipa":"/ˌkliːənˈtel/","tag":"collective","definition":"The whole group of clients; client is one member of that group.","definitionCN":"客户的整体；client 是那个群体中的一个成员。"},{"word":"clientage","ipa":"/ˈklaɪəntɪdʒ/","tag":"the relation","definition":"The condition of being a client, the bond of dependence itself.","definitionCN":"身为客户的状态，即依附这一纽带本身。"},{"word":"clientship","ipa":"/ˈklaɪəntʃɪp/","tag":"status","definition":"The status of being a client, a rarer synonym of clientage.","definitionCN":"作为客户的身份，是 clientage 较少见的同义说法。"},{"word":"climax","ipa":"/ˈklaɪmæks/","tag":"different root","definition":"From Greek klimax 'ladder'; it starts with the same letters but has no listening in it.","definitionCN":"出自希腊语 klimax「梯子」；开头字母相同，里面却没有「听」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"customer","ipa":"/ˈkʌstəmə/","tag":"retail tone","definition":"A buyer in a shop or a consumer service; it stresses the habit of buying rather than a relationship of advice.","definitionCN":"商店或消费服务中的买家；强调购买习惯，而非提供建议的关系。"},{"word":"patron","ipa":"/ˈpeɪtrən/","tag":"the other side, historically","definition":"The protector or regular supporter to whom a client once owed loyalty; the word now mainly means a supporter of the arts.","definitionCN":"依附者昔日须效忠的保护者或常客资助人；如今主要指艺术赞助人。"},{"word":"principal","ipa":"/ˈprɪnsəpl/","tag":"legal pairing","definition":"The party a lawyer or agent acts for; in law it names the same person as client, seen from the agency side.","definitionCN":"律师或代理人代为行事的一方；在法律里，它从代理方视角指同一个当事人。"},{"word":"account","ipa":"/əˈkaʊnt/","tag":"business shorthand","definition":"A client firm, called an account by agencies; the word names the business relationship, not the person.","definitionCN":"代理公司口中的客户企业，称为 account；这个词命名业务关系，而不是那个人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: a real Latin participle, a real social history and real modern uses.","cn":"正常联想：真实的拉丁分词、真实的社会史与真实的现代用法。"},"normal":[{"en":"cliens 'the one who listens' → client: the party who takes the advice and pays for it.","cn":"cliens「听从的那个人」→ client：接受建议并为其付钱的一方。"},{"en":"The family runs client, clientele, clientage, clientship.","cn":"同族词包括 client、clientele、clientage、clientship。"},{"en":"Fixed phrases mark the trade: advise a client, client confidentiality, a prospective client.","cn":"固定搭配标出行业：为客户提供建议、客户保密义务、潜在客户。"},{"en":"Computing split the world into client and server, the asker and the answerer.","cn":"计算机把世界分成客户端与服务器，也就是提问者与回答者。"},{"en":"The Roman patron sits on the other side of the same bond.","cn":"罗马的庇护人坐在同一条纽带的另一端。"}],"abstract":[{"en":"Picture two chairs facing across a desk: one asks, one answers, one pays.","cn":"想象桌子两侧相对的两把椅子：一侧提问，一侧回答，一侧付钱。"},{"en":"Every sense keeps the leaning: one party rests on the other's knowledge.","cn":"每个义项都保留那份倚靠：一方倚在另一方的知识上。"},{"en":"Computing only renamed the chairs; the leaning is unchanged.","cn":"计算机只是给椅子换了名字，倚靠并没有变。"}]},"examples":[{"en":"The architect showed the client three versions of the stair.","cn":"建筑师给客户看了楼梯的三种方案。"},{"en":"A lawyer cannot reveal a client's confidence without consent.","cn":"未经同意，律师不得泄露客户的秘密。"},{"en":"The client waits for the server to confirm the order.","cn":"客户端等待服务器确认订单。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「克莱恩特」——克莱恩靠在桌子这一边听，听完了就签名字 → client 客户、委托人","word":"client"},"root":"拉丁 cliens（cluere「听、听从」的现在分词）「听从的依附者」，复数 clientes；经法语进入英语。更深来源不确定。","sensesIntro":{"en":"Eight senses keep one relation: one party leans on another's knowledge or service and pays for it. The leaning becomes legal, commercial, historical, social and finally digital.","cn":"八个义项守住同一种关系：一方倚靠另一方的知识或服务，并为此付钱。这份倚靠依次变成法律的、商业的、历史的、社会的，最后是数字的。"},"semanticMap":{"core":{"en":"CORE IMAGE: two chairs across a desk, one leaning toward the other.","cn":"核心意象：桌子两侧两把椅子，一把向另一把倾过去。"},"chain":["LEAN","DEPENDENT","PATRON","FEE PAYER","CUSTOMER","TERMINAL"],"branches":[{"senses":"01 · 04","en":"PAID ADVICE: the commercial client and the legal principal both buy another's knowledge.","cn":"付费的建议：商业客户与法律当事人都在购买他人的知识。"},{"senses":"02 · 05","en":"SERVICE AND DURATION: the formal customer and the long-standing account differ only in how long the relation runs.","cn":"服务与时长：正式的顾客与长期客户，只差在这段关系持续多久。"},{"senses":"03","en":"TERMINAL: computing keeps the asking side and renames it a client.","cn":"终端：计算机保留提问的一侧，把它改叫客户端。"},{"senses":"06","en":"ROMAN ORIGIN: the whole shape began as a plebeian leaning on a patron.","cn":"罗马源头：整个形状起于一个平民倚靠庇护人。"},{"senses":"07 · 08","en":"COMMISSION AND CARE: an agency's payer and a welfare body's served person are the same chair in different rooms.","cn":"委托与照护：代理公司的甲方与福利机构的受助者，是不同房间里的同一把椅子。"}]},"affixes":{"intro":{"en":"Client is a Latin noun taken whole, so its word-building lives in the Latin pieces around it rather than in English suffixes.","cn":"client 是一个整体借入的拉丁名词，因此它的构词活在周围的拉丁构件里，而不在英语后缀里。"},"latinIntro":{"en":"Cluere 'to hear, obey' gives cliens 'listener' and clientela 'body of listeners'; the deeper origin of cluere is uncertain.","cn":"cluere「听、服从」给了 cliens「听从者」与 clientela「听从者群体」；cluere 的更早来源不确定。"},"items":[{"word":"client","structure":"client (from Latin cliens, clientis)","meaning":"one who relies on another's service","meaningCN":"依靠他人服务的人","example":"The client approved the plan.","exampleCN":"客户批准了这个方案。"},{"word":"clientele","structure":"client + -ele","meaning":"the whole body of clients","meaningCN":"客户整体","example":"The clientele grew younger.","exampleCN":"客户群变年轻了。"},{"word":"clientage","structure":"client + -age","meaning":"the state of dependence","meaningCN":"依附状态","example":"Clientage shaped Roman politics.","exampleCN":"依附关系塑造了罗马政治。"},{"word":"clientship","structure":"client + -ship","meaning":"the status of a client","meaningCN":"客户身份","example":"Clientship brings certain duties.","exampleCN":"客户身份带来某些义务。"},{"word":"clientelism","structure":"clientele + -ism","meaning":"a system of traded favours","meaningCN":"恩惠换忠诚的体制","example":"Clientelism distorted hiring.","exampleCN":"庇护主义扭曲了招聘。"},{"word":"client-side","structure":"client + side","meaning":"running on the asking machine","meaningCN":"在提问的那台机器上运行","example":"The client-side script failed.","exampleCN":"客户端脚本出错了。"},{"word":"cluere","structure":"cluere (Latin verb)","meaning":"to hear, obey","meaningCN":"听；服从","example":"The verb underlies the whole family.","exampleCN":"这个动词支撑着整个词族。"},{"word":"cliens","structure":"cliens, clientis (Latin noun)","meaning":"a listening dependant","meaningCN":"听从的依附者","example":"A cliens greeted his patron at dawn.","exampleCN":"依附者清晨向庇护人问安。"}],"latinEntries":[{"word":"cluere","structure":"cluere (verb, second conjugation)","meaning":"to hear, listen, obey","meaningCN":"听；听从；服从"},{"word":"cliens","structure":"cliens, clientis (noun, third declension)","meaning":"a dependant follower","meaningCN":"依附的跟随者"},{"word":"clientela","structure":"clientela (noun, first declension)","meaning":"body of dependants, patronage","meaningCN":"依附者群体；庇护关系"}],"derivatives":[{"word":"clientele","pos":"n.","zh":"客户群；委托人群"},{"word":"clientage","pos":"n.","zh":"委托关系"},{"word":"clientship","pos":"n.","zh":"客户身份"},{"word":"clientelism","pos":"n.","zh":"庇护主义"},{"word":"client-side","pos":"adj.","zh":"客户端的"}]}}]);
